/* テキストの「さらに深く」拡充(担当:国語・古文・漢文・共通テスト国語・中学国語) */
(function (L) {
  function add(id, o) {
    var x = L[id]; if (!x) return;
    ['secs', 'drill', 'faq'].forEach(function (k) { if (o[k]) x[k] = (x[k] || []).concat(o[k]); });
  }

  add('j_hyoron', {
    secs: [
      { h: 'さらに深く:筆者は言葉を「定義し直す」', t: '評論文の筆者は、ふだん私たちが何気なく使っている言葉を、わざと【定義し直す】ことがよくあります。たとえば「豊かさ」という語は、ふつう「お金や物がたくさんあること」と考えられています。ところが筆者が「本当の豊かさとは、何もしない時間を楽しめることだ」と書いたとき、この語は筆者独自の意味をもつようになります。\nこのような【再定義】に気づかないと、傍線部の説明問題で「ふつうの意味」のまま答えてしまい、大きく点を落とします。見つける手がかりは次の3つです。\n①【かぎかっこつきの語】…「 」でくくられた語は、「ふつうとはちがう意味で使っていますよ」という合図であることが多いです。\n②【「本当の〜」「真の〜」「〜とは、実は…である」】…一般の意味を否定して、新しい意味を与える形です。\n③【同じ語が二つの意味で使い分けられる】…「便利な道具は時間を生むが、その時間は『自由な時間』ではない」のように、前後で意味がずれていることがあります。\n再定義を見つけたら、「一般の意味」と「筆者の意味」を並べてメモします。この2つのずれこそが、筆者が文章を書いた理由であり、主張そのものです。選択肢では、一般の意味のほうで説明している選択肢が「もっともらしい誤答」として必ず用意されています。', key: 'かぎかっこの語や「本当の〜」の形は、筆者が言葉に新しい意味を与えている合図。一般の意味と筆者の意味のずれが、そのまま主張になる。', ex: [{ q: '「私たちは、旅行のガイドブックを見て、名所を確かめるように歩く。だが、それは『旅』ではなく、地図の答え合わせにすぎない。本当の旅とは、予定にない出会いに身をまかせることである。」\nこの文章で、筆者は「旅」をどのように定義し直しているか。一般の意味と比べて説明しよう。', hint: 'かぎかっこの『旅』と、「本当の旅とは」の部分に注目しましょう。', steps: ['かぎかっこつきの『旅』と「本当の旅とは〜である」という形があるので、再定義の文章だと判断する。', '一般の意味を確かめる。ふつう「旅行」は名所をめぐることであり、本文の前半がそれにあたる。', '筆者はそれを「地図の答え合わせにすぎない」と否定している。つまり、あらかじめ知っていることを確認するだけの行為だととらえている。', '筆者の意味は「予定にない出会いに身をまかせること」。一般の意味=決められたものを確かめる、筆者の意味=決められていないものに出会う、という対比でまとめる。'], a: '一般には、名所をめぐって見どころを確かめることが旅だと考えられているが、筆者はそれを予定どおりの確認にすぎないとし、予定にない出会いに身をまかせることこそが本当の旅だと定義し直している。', check: '答えに「一般の意味」と「筆者の意味」の両方が入っているか確かめます。片方だけでは、何をどう定義し直したのかが伝わりません。' }] },
      { h: '実戦演習:再定義と逆説をふくむ評論', t: '入試の評論では、1つの文章の中に「再定義」「逆説」「対比」が重なって出てきます。解く前の戦略は次のとおりです。\n①まず本文全体を読み、筆者が否定している考え(一般論)と、筆者の考えに線を引き分けます。\n②傍線部に、再定義された語や逆説(一見矛盾した言い方)がふくまれていないかを確かめます。ふくまれていれば、その語を「本文中の別の言葉」で言いかえることが答えの中心になります。\n③理由説明では、「AだからB」の形にしたとき、本文の論理がつながるかを確かめます。\n典型的な落とし穴は、傍線部の語をそのまま答えに使ってしまうことです。傍線部の語を使っても説明にはなりません。', key: '傍線部の中のむずかしい語・かぎかっこの語を、本文の別の言葉で置きかえられるかどうかで差がつく。', ex: [{ q: '次の文章を読んで答えよう。\n「現代の私たちは、待つことを嫌う。電車が二分遅れただけでいらだち、返事が来ないメッセージを何度も確かめる。技術は、待ち時間をできるだけ短くする方向へと進んできた。しかし、待つことは、ただの無駄な時間なのだろうか。種をまいた農夫は、芽が出るまで何もできない。だが、その時間に彼は空を見上げ、土の湿りを確かめ、作物のことを考えつづける。待つとは、自分の思いどおりにならないものに心を向けつづけることなのだ。だとすれば、待ち時間を消していく社会は、【私たちから、他者を思う時間を奪っている】のかもしれない。」\n傍線部はどういうことか。説明しよう。', hint: '「待つ」が筆者によってどう定義し直されているかを先に確かめます。', steps: ['一般論を確認する。前半の「待つことを嫌う」「無駄な時間」が一般の考え方で、筆者はそれを「しかし」で問い直している。', '再定義を見つける。「待つとは、自分の思いどおりにならないものに心を向けつづけることなのだ」が筆者の定義である。', '傍線部の「他者」を本文に当てはめる。農夫の例では作物、メッセージの例では返事をくれる相手であり、どちらも「自分の思いどおりにならないもの」にあたる。', '「奪っている」の中身を、技術の進歩=待ち時間を消すことと結びつける。待ち時間が消えると、思いどおりにならないものに心を向ける時間も消える。', '一般の意味(無駄な時間)と筆者の意味(他者に心を向ける時間)のずれを入れてまとめる。'], a: '技術によって待ち時間がなくなることは、一般には無駄が省かれることだと考えられているが、待つことは自分の思いどおりにならない相手やものに心を向けつづける時間でもあるので、待ち時間を消す社会は、人がそうした他者について考える機会そのものを失わせているということ。', check: '答えから傍線部の語(他者・奪う)を消しても意味が通るか確かめます。「待つ」の再定義が答えに入っていれば、筆者の論理をたどった説明になっています。' }] }
    ],
    drill: [
      { lv: 2, q: '「科学は世界を『説明』するが、世界を『理解』させるとはかぎらない。」この文で、かぎかっこがついている理由を説明しよう。', a: '「説明」と「理解」を、ふつうとはちがう、区別された意味で使っていることを示すため。(説明=しくみを言葉や数式で示すこと、理解=自分のこととして納得すること、という区別。)', exp: 'ふだんは「説明される」と「理解できる」はほぼ同じ意味で使われます。筆者はかぎかっこをつけることで、2つの語を区別し、「しくみが説明されても、納得できるとはかぎらない」という主張を示しています。\nかぎかっこには、ほかに①会話や引用、②強調、③「いわゆる〜」という皮肉の意味などの働きもあります。評論文では、②と③、そして今回のような「特別な意味で使う」働きが多いので、かぎかっこを見たら、その語が本文でどう定義されているかを探すくせをつけましょう。' },
      { lv: 3, q: '「速く移動できるようになった人間は、そのぶん遠くまで行けるようになった。だが、遠くへ行けるようになったことで、人は近くを見なくなった。私たちは、速さによって世界を広げると同時に、狭めてもいるのだ。」\n最後の文の「狭めている」とはどういうことか。本文の言葉を使って説明しよう。', a: '速く遠くまで移動できるようになったことで、身近な場所に目を向けなくなり、実際に見て知っている世界が小さくなっているということ。', exp: '最後の文は「広げる」と「狭める」が同時に起こるという【逆説】です。逆説を説明するときは、「何の面では広がり、何の面では狭まるのか」と、2つの軸に分けるのがコツです。\nここでは、広がる=行ける範囲(距離)、狭まる=実際に目を向ける範囲(近く)です。「近くを見なくなった」が根拠になります。\nまちがえやすいのは「人間が遠くへ行けなくなった」と、事実として狭まったように書くことです。筆者は行動範囲ではなく、見る・知るという意味での世界が狭まると言っています。' },
      { lv: 3, q: '「多くの人は、個性とは他人とちがうことだと考えている。しかし、ちがうことだけをめざして奇抜な服を着ても、それは『ちがって見られたい』という、だれもがもつ願いに従っているにすぎない。個性とは、むしろ、他人の目を気にせずに自分の好きなものを選びつづけた結果として、あとから現れるものなのである。」\n筆者の考える「個性」を、一般の考えと対比して60字以内で説明しよう。', a: '(例)他人とちがうことをめざすことではなく、他人の目を気にせず好きなものを選びつづけた結果として、あとから現れるもの。(56字)', exp: 'まず一般論(他人とちがうこと)と、筆者の再定義(好きなものを選びつづけた結果、あとから現れるもの)を分けます。\n本文の中ほどにある「ちがって見られたい」という部分は、一般の考え方の問題点を示す理由の部分です。奇抜な服を着ることは、実は「みんなと同じ願い」に従っているので、個性とは言えない、という逆説になっています。\n字数指定があるときは、具体例(奇抜な服)は入れず、「〜ではなく、〜である」の対比の形でまとめると、必要な要素がもれなく入ります。「あとから現れる」という時間の順序も、筆者の考えの大事な部分なので落とさないようにしましょう。' }
    ],
    faq: [
      ['筆者が言葉を定義し直すのは、ずるいことではないの?', 'ずるいことではありません。言葉の意味を問い直すことは、評論の大切な仕事です。ふつうの意味のままでは見えない問題を、新しい意味を与えることで見えるようにするのです。ただし、良い評論では、なぜその意味で使うのかという理由が必ず書かれています。読むときは、その理由に納得できるかどうかを考えると、筆者の主張を深く理解でき、自分の意見も持てるようになります。'],
      ['「逆説」と「再定義」は、どうちがうの?', '逆説は「急がば回れ」のように、一見矛盾しているようで真理を言い当てている言い方のことです。再定義は、ある語に新しい意味を与えることです。この2つはよくいっしょに使われます。たとえば「本当の強さとは、弱さを認めることだ」は、「強さ」を再定義した結果、逆説の形になっています。逆説を見つけたら、その裏に再定義された語がないかを探すと、説明しやすくなります。']
    ]
  });

  add('j_shinjo', {
    secs: [
      { h: 'さらに深く:行動と気持ちが「逆」になるとき', t: '小説の人物は、いつも気持ちどおりに行動するとはかぎりません。むしろ入試で問われるのは、【行動と気持ちが食いちがっている場面】です。人は、本当の気持ちを知られたくないとき、反対の行動をとることがあるからです。\n代表的なパターンは次の3つです。\n①【照れかくし】…うれしいのに、わざとぶっきらぼうにふるまう。例:ほめられて「べつに、ふつうだし」と顔をそむける。\n②【強がり】…悲しい・くやしいのに、平気なふりをする。例:負けたあと、いつもより大きな声で笑う。\n③【気づかい】…自分の気持ちより、相手を思って行動する。例:本当は引き止めたいのに「行っておいで」と送り出す。\nこうした場面を見分ける手がかりは、【行動の不自然さ】です。「いつもより」「わざと」「なぜか」などの言葉や、言葉と表情・しぐさのずれ(笑って言いながら手がふるえている など)に注目します。\n説明するときは、「表面の行動」と「内側の気持ち」の両方を書き、さらに「なぜ隠そうとしたのか(理由)」まで書けると、記述問題で満点に近づきます。たとえば「ほめられてうれしかったが、それを素直に見せるのが照れくさかったので、そっけない態度をとった」という形です。', key: '行動の不自然さ(いつもより・わざと・言葉と表情のずれ)は、気持ちを隠しているサイン。表面の行動・内側の気持ち・隠す理由の3つで説明する。', ex: [{ q: '「弟がつくった不格好なおにぎりを、兄は『しょっぱいな』と言いながら、残さず食べた。皿を流しに運ぶとき、兄は弟のほうを見ないまま、『また作れよ』とだけ言った。」\nこのときの兄の気持ちを説明しよう。', hint: '「しょっぱい」と言ったのに、どう行動したかを比べましょう。', steps: ['言葉と行動を並べる。言葉は「しょっぱいな」(不満)、行動は「残さず食べた」(受け入れている)で、食いちがっている。', 'さらに「また作れよ」という言葉から、弟のおにぎりをうれしく思っていることが分かる。', '「弟のほうを見ないまま」は、素直な気持ちを見せるのが照れくさいことを表すしぐさだと読める。', '表面(そっけない言葉)・内側(うれしさ)・理由(照れくささ)の3つをまとめる。'], a: '弟が自分のために作ってくれたおにぎりをうれしく思っているが、それを素直に伝えるのが照れくさいので、わざとそっけない言い方をしている。', check: '「本当にしょっぱくて不満だった」と読むと、「残さず食べた」「また作れよ」と矛盾します。すべての行動と矛盾しない気持ちになっているかで確かめます。' }] },
      { h: '実戦演習:複数の気持ちが重なる場面の記述', t: '入試の心情説明でいちばん差がつくのは、【気持ちが2つ以上重なっている場面】です。うれしいけれどさびしい、くやしいけれどほっとした、などです。\n戦略は次のとおりです。\n①傍線部の前の「できごと」を確かめ、それぞれのできごとに対応する気持ちを1つずつ考えます。\n②傍線部の行動・しぐさが、どちらの気持ちを表しているかを考えます。両方が混ざっていることもあります。\n③記述では「〜だが、〜も感じている」「〜とともに〜」と、気持ちを並べる形にします。\n落とし穴は、片方の気持ちだけを書いてしまうことです。本文に2つのできごとがあれば、2つの気持ちを疑いましょう。', key: 'できごとが2つあれば、気持ちも2つあると考える。「〜だが、〜も」の形で、両方を書けるかどうかで差がつく。', ex: [{ q: '次の文章を読んで答えよう。\n「引っこしの朝、トラックの荷台に最後の段ボールが積まれた。祖母は門の前に立ったまま、『体に気をつけるんだよ』と何度も同じことを言った。新しい町には、ぼくが入りたかったサッカーのクラブがある。昨日までは、それが楽しみでしかたなかった。けれど、走り出した車の窓から、小さくなっていく祖母の姿を見ているうちに、ぼくは【ひざの上の手を、ぎゅっとにぎりしめていた】。」\n傍線部の「ぼく」の気持ちを説明しよう。', hint: '「楽しみ」なこと(新しい町)と、いま目の前で起きていること(祖母との別れ)の2つがあります。', steps: ['できごとを2つに分ける。①新しい町でサッカーのクラブに入れる。②祖母と別れて遠くへ行く。', '①に対応する気持ちは期待・楽しみ。ただし「昨日までは」とあるので、今はそれだけではないことが分かる。', '②に対応する気持ちはさびしさ・別れのつらさ。「何度も同じことを言った」祖母の様子から、祖母も別れを惜しんでいることが「ぼく」に伝わっている。', '傍線部の「ぎゅっとにぎりしめる」は、こみあげる気持ちをこらえるしぐさ。主にさびしさを表すが、その気持ちが「楽しみ」と入れかわるように強くなったことを読みとる。', '「〜を楽しみにしていたが、〜」の形で、2つの気持ちとその変化をまとめる。'], a: '新しい町でサッカーのクラブに入れることを楽しみにしていたが、別れを惜しむ祖母の姿が遠ざかっていくのを見て、祖母と離れるさびしさが強くこみあげ、それを必死にこらえている。', check: '「楽しみ」だけ、または「さびしさ」だけの答えになっていないか確かめます。「昨日までは」という言葉が、気持ちの変化があったことの根拠になっています。' }] }
    ],
    drill: [
      { lv: 2, q: '「試合に負けた日の夕食で、姉はいつもより多くしゃべり、だれよりも大きな声で笑っていた。」このときの姉の気持ちとして考えられることを説明しよう。', a: '試合に負けたくやしさや悲しさを家族に気づかれたくないので、わざと明るくふるまっている(強がっている)。', exp: '手がかりは「いつもより」「だれよりも」という比較の言葉です。ふだんとちがう行動は、何か理由があるサインです。\n試合に負けたというできごとからすると、本来の気持ちは「くやしい」「悲しい」はずです。それなのに明るくふるまうのは、気持ちを隠すための【強がり】、あるいは家族に心配をかけたくないという【気づかい】と考えられます。\n「負けたけれど楽しかったから明るい」と読むこともできそうですが、それなら「いつもより」と強調する必要がありません。不自然さを示す言葉があるときは、隠された気持ちを考えましょう。' },
      { lv: 3, q: '「父は、ぼくの合格の知らせを聞くと、『そうか』とだけ言って新聞に目をもどした。だが、その新聞は、さっきから一ページもめくられていなかった。」\n最後の一文は、父のどんな気持ちを表しているか。また、作者がこの一文を書いた効果を説明しよう。', a: '気持ち:合格をとてもうれしく思っていて、新聞を読むどころではない(が、それを表に出さないでいる)。効果:父の気持ちを直接書かず、「めくられていない新聞」という具体的な事実で示すことで、そっけない態度の裏にある喜びを読者に気づかせ、父の不器用な愛情を印象づけている。', exp: '「そうか」「新聞に目をもどした」だけなら、父は無関心に見えます。しかし「一ページもめくられていなかった」から、父は新聞を読んでいるふりをしているだけで、心は合格の知らせでいっぱいだと分かります。\n「だが」という逆接が、読者に「表面とはちがう」と気づかせる合図になっています。\n表現の効果を答えるときは、①何が書かれているか(事実)、②そこから何が分かるか(心情)、③直接書かないことで読者にどう伝わるか(効果)の3段階で書くと、まとまった答えになります。' },
      { lv: 3, q: '「美術の時間、友だちの絵がほめられた。『すごいね』とわたしは言った。本当にすごいと思った。それなのに、帰り道の足取りは、なぜか重かった。」\n「なぜか重かった」とあるが、「わたし」の心の中には、どんな気持ちが重なっていると考えられるか。2つ答えて説明しよう。', a: '①友だちの絵を本当にすごいと思い、認める気持ち。②自分の絵はほめられなかったことへのくやしさやうらやましさ(自分でも認めたくない気持ち)。', exp: '「本当にすごいと思った」と本文にあるので、①の気持ちはうそではありません。ここが大事な点で、「本当はすごいと思っていなかった」と答えると誤りになります。\nそれでも足取りが重いのは、別の気持ちが同時にあるからです。友だちがほめられたというできごとから考えられるのは、自分と比べてしまうくやしさ、うらやましさです。\n「なぜか」という言葉は、「わたし」自身もその気持ちをはっきり意識していない(認めたくない)ことを示しています。語り手が自分の気持ちに気づいていない場合も、読者は行動から読みとることができます。' }
    ],
    faq: [
      ['気持ちを隠しているのか、本当にそう思っているのか、どう区別すればいいの?', '前後のほかの行動と矛盾しないかで区別します。「しょっぱい」と言いながら残さず食べるなら、言葉と行動が矛盾しているので、言葉のほうが本心ではないと分かります。反対に、言葉と行動がそろっているなら、そのまま受けとってかまいません。「いつもより」「わざと」「なぜか」など、不自然さを示す語があるかどうかも大きな手がかりです。根拠が1つしかないときは、決めつけずに文章の後半まで読んで確かめましょう。'],
      ['心情の記述で、気持ちを表す言葉を2つ書くと、減点されないの?', '本文に根拠があれば、減点されるどころか、むしろ必要な要素として採点されます。入試の模範解答には「〜だが、〜も感じている」のように、2つの気持ちを入れたものがよくあります。ただし、根拠のない気持ちを思いつくまま並べると、まちがった要素として減点されることがあります。それぞれの気持ちに対応する「できごと」が本文にあるかを確かめてから書きましょう。']
    ]
  });

  add('j_hyogen', {
    secs: [
      { h: 'さらに深く:問いの「言葉」を定義し、条件つきで主張する', t: '小論文で評価が高い答案は、問いに対していきなり賛成・反対を述べるのではなく、まず【問いの中の言葉をはっきりさせる】ところから始まります。たとえば「学校に制服は必要か」という問いでも、「必要」が「学校生活に欠かせない」という意味なのか、「あったほうがよい」という意味なのかで、答えの重さが変わります。\n定義をはっきりさせると、次に【条件つきの主張】ができるようになります。「制服は必要だ」と言い切るよりも、「少なくとも式典などの行事の場では、制服は必要だ」「生徒が自分で選べる仕組みがあるなら、制服はあってよい」のように、どんな場合にそう言えるのかを示すと、反論に強い主張になります。\nこれは「どっちつかず」とはちがいます。どっちつかずとは、結論を出さないことです。条件つきの主張は、結論ははっきり出したうえで、【その結論が成り立つ範囲】を自分で決めることです。\n手順は、①問いのキーワードを一文で定義する、②賛成・反対それぞれが強く当てはまる場面を考える、③自分の結論と、それが成り立つ条件を決める、の3段階です。条件を決めると、第3段落の「譲歩→反論」も書きやすくなります。反対側が強く当てはまる場面を認めたうえで、「しかし、〜の場面では」と自分の範囲にもどればよいからです。', key: 'キーワードを定義し、「どんな場合に」その結論が成り立つかを示すと、反論に強い主張になる。条件つきの主張は、結論をぼかすことではない。', ex: [{ q: '「高校生はSNSを使うべきではない」という意見について、条件つきの主張を1文で作り、その主張にした理由を説明しよう。', hint: 'SNSが役に立つ場面と、害になりやすい場面を分けてみましょう。', steps: ['キーワードを定義する。「SNSを使う」には、情報を見るだけ・発信する・知らない人と交流する、などいろいろな使い方がある。', '害になりやすい場面を考える。知らない人と個人情報をやりとりする、夜おそくまで使って睡眠が減る、などは問題が大きい。', '役に立つ場面を考える。学校や部活の連絡、興味のある分野の情報を集める、などは役に立つ。', '結論と条件を決める。全面的に禁止するのではなく、使い方の範囲を決めて主張する。'], a: '(例)主張:高校生は、個人情報を公開せず、使う時間を自分で決めるという条件のもとでならSNSを使ってよい。理由:SNSには連絡や情報収集などの利点があり、全面的に禁止すると利点まで失われる一方、問題の多くは個人情報の公開と使いすぎから生まれるので、その2点を条件にすれば害をおさえられるから。', check: '主張の文に「はい・いいえ」がはっきり読みとれるか(この例では「使ってよい」)、条件が具体的か(「適切に」のようなあいまいな言葉だけになっていないか)を確かめます。' }] },
      { h: '実戦演習:課題文の主張に対して、自分の立場を組み立てる', t: '課題文型の小論文では、課題文の主張に「賛成か反対か」を問われることが多いです。戦略は次のとおりです。\n①課題文の主張を1文に要約します。要約がずれると、答案全体がずれます。\n②課題文の主張が、どんな前提に立っているかを考えます。前提とは、筆者が当然だと考えて書いていないことです。反対するなら前提を、賛成するなら課題文にない新しい根拠を示すと、オリジナリティが出ます。\n③自分の立場を、条件つきで決めます。\n落とし穴は、課題文の内容をくり返すだけで終わることです。課題文と同じ例を使わず、自分で考えた例を1つ入れることを目標にしましょう。', key: '課題文の「前提」を見つけられるかどうかで差がつく。前提を問い直すと、課題文をくり返すだけの答案から抜け出せる。', ex: [{ q: '次の課題文を読み、筆者の主張に対するあなたの考えを、構成メモ(4段落)の形で示そう。\n課題文(作例)「電子書籍が広まり、紙の本はやがて役目を終えるだろう。電子書籍なら何千冊も持ち歩け、文字の大きさも変えられ、置き場所にも困らない。読書の目的が内容を知ることにある以上、より便利な形が選ばれるのは当然である。」', hint: '「読書の目的が内容を知ることにある以上」の部分が、筆者の前提です。', steps: ['課題文の主張を要約する:「電子書籍のほうが便利なので、紙の本は役目を終える」。', '前提を見つける:「読書の目的は内容を知ることだけである」と考えている。ここが問い直せるポイント。', '前提を問い直す:読書には、内容を知るほかに、ページをめくりながら全体の中の位置を感じる、書きこみをする、本棚に並べて見返す、といった体験の面もある。', '立場を条件つきで決める:情報を得るための読書では電子書籍が適しているが、くり返し読み味わう本では紙の本の役目は残る。', '4段落に配置する:①問題提起と主張、②前提への疑問と理由、③譲歩(電子書籍の利点を認める)と反論、④結論。'], a: '(構成メモの例)\n第1段落:紙の本は役目を終えるのか。私は、読書の目的によっては紙の本の役目は残ると考える。\n第2段落:筆者は読書の目的を「内容を知ること」に限っているが、読書には、ページの厚みで全体の中の位置を感じたり、書きこみをしながら考えたりする体験の面がある。\n第3段落:たしかに、調べものや多くの本を持ち歩く場合は電子書籍が便利である。しかし、くり返し読み、考えを深めたい本では、紙の本のほうが適している。\n第4段落:したがって、紙の本と電子書籍は目的に応じて使い分けられ、紙の本が完全に役目を終えることはないと考える。', check: '第2段落が課題文のくり返しになっていないか、自分で考えた具体例(書きこみ・ページの厚み)が入っているかを確かめます。電子書籍に賛成の立場でも、「課題文にない新しい根拠」を示せば同じように高い評価が得られます。' }] }
    ],
    drill: [
      { lv: 2, q: '「部活動は全員参加にすべきだ」という主張を、条件つきの主張に書きかえよう。', a: '(例)入学してから最初の一年間に限っては、部活動は全員参加にすべきだ。(または)活動日数を週三日以内にするなら、部活動は全員参加にしてもよい。', exp: '条件つきの主張を作るには、「いつ」「だれが」「どの程度」のどれかに範囲をつけます。この例では「最初の一年間」(いつ)、「週三日以内」(どの程度)が条件です。\n条件をつけるときは、反対意見が強く当てはまる場面を外すのがコツです。全員参加への反対理由として「勉強や家の手伝いの時間がなくなる」が考えられるので、活動日数をしぼれば、その反対理由に答えられます。\n「できるだけ参加すべきだ」のような表現は、範囲がはっきりしないので条件つきの主張とは言えません。' },
      { lv: 3, q: '課題文の主張「失敗をおそれる若者が増えたのは、社会が失敗を許さなくなったからだ」には、どんな前提がふくまれているか。また、その前提を問い直すと、どんな反論ができるか説明しよう。', a: '前提:①失敗をおそれる若者が実際に増えている、②若者の態度は社会のあり方によって決まる。反論の例:②について、社会だけでなく、SNSなどで他人の評価がすぐ目に見えるようになったことも原因ではないか。または、①について、本当に増えたのかを示すデータが必要ではないか。', exp: '前提を見つけるには、主張を「AだからB」の形にして、AとBそれぞれについて「本当にそう言えるか」と問います。\nこの主張では、Bの「増えた」は事実として語られていますが、比べるデータが示されていなければ、それ自体が前提になります。また、原因をA(社会)だけにしぼっていることも前提です。\n反論するときは、相手の主張を全部否定する必要はありません。「原因は社会だけではない」と、原因を一つ足すだけでも立派な反論になります。このように、主張の一部を修正する反論のほうが、説得力が高くなることが多いです。' },
      { lv: 3, q: '小論文で「〜べきだ」と主張するとき、「理由」に加えて何を示すと説得力が増すか。「図書館の開館時間を夜十時まで延ばすべきだ」を例に説明しよう。', a: '主張を実行したときの「利点がだれにとって、どのくらいあるか」に加えて、「実現のための費用や問題点への対策(実現可能性)」を示すとよい。例:働く人や塾帰りの学生が利用できるという利点に加え、夜間の職員を増やす費用を、利用の少ない朝の時間を短くすることでおさえる、という対策を示す。', exp: '「〜べきだ」という主張は、【その方がよい】という価値の判断と、【実際にできる】という実現可能性の判断の2つからできています。多くの答案は前者だけを書いてしまいます。\n採点者は「それはよいことだが、どうやって実現するのか」と考えます。費用・人手・ほかへの影響など、問題点を自分から挙げ、それへの対策を示すと、「よく考えた答案」と評価されます。\nただし、対策が具体的すぎて主張から離れないように注意しましょう。一つか二つの問題点にしぼって答えるのが適切です。' }
    ],
    faq: [
      ['条件をつけると、主張が弱くなって見えませんか?', '反対です。「すべての場合に正しい」という主張は、たった一つの反例で崩れてしまいます。条件をつけた主張は、その範囲の中では反例が出にくく、守りが固くなります。採点者から見ても、物事をいろいろな角度から考えたことが伝わります。ただし、条件をたくさんつけすぎると、何を言いたいのかが分かりにくくなります。条件は一つか二つにしぼり、結論ははっきり言い切るのがコツです。'],
      ['課題文の筆者に反対してもいいの? 賛成しないと失礼では?', '反対してかまいません。小論文で見られているのは、課題文を正しく読みとったうえで、自分の頭で考えた筋道です。賛成でも反対でも評価は変わりません。ただし、反対するときは、筆者の主張を正確に要約してから反対することが大切です。主張を読みちがえたまま反対すると、「読めていない」と判断されます。また、全面的に反対するより、「この点には賛成だが、この点は問い直したい」という形のほうが、深く読めていることを示せます。']
    ]
  });

  add('j_h1', {
    secs: [
      { h: 'さらに深く:現代語から歴史的仮名遣いを「推理」する', t: 'これまでは歴史的仮名遣いを現代の読み方に直す練習をしてきました。ここでは逆に、【現代の読みから、昔の書き方を推理する】考え方を学びます。これができると、文法問題(活用の行)や和歌の掛詞を見ぬく力がぐっと上がります。\n手がかり①【動詞の活用】…現代語で「思う・言う・笑う」のように「〜う」で終わる五段動詞の多くは、古文ではハ行四段活用で「思ふ・言ふ・笑ふ」と書きます。「思わない」と「わ」になるのは、昔の「思はず」の「は」が「わ」と読まれるようになったからです。つまり、現代語で【ア段が「わ」になる動詞】は、古文ではハ行の動詞だと推理できます。ただし「植う」(ワ行下二段・植ゑ)のように、ワ行の動詞もあるので注意します。\n手がかり②【同じ音の別の語】…現代語の「いる」には、「居る」(古文では「ゐる」)と「射る」(「いる」)があります。「おる」も、「居る・をる」と「折る・をる」「下りる・おる」があります。漢字が分かれば、昔の書き方も決まります。\n手がかり③【「お」と「を」】…語の頭の「お」は、古文では「お」の場合と「を」の場合があります(「おもふ」と「をかし」)。これは語ごとに覚えるしかありませんが、助詞の「を」だけは今も「を」と書くので、目印になります。\nこの推理は、文法の問題で「この動詞は何行か」と問われたときにそのまま役に立ちます。', key: '現代語で「〜わない」となる五段動詞の多くは、古文ではハ行四段。漢字(居る・射る)が分かれば、ゐ・いの書き分けも決まる。', ex: [{ q: '次の現代語の動詞を、古文の終止形で歴史的仮名遣いを使って書き、何行何活用かを答えよう。①歌う ②払う ③居る(座っている)', hint: '①②は「〜わない」の形にしてみましょう。③は「ゐ」か「い」かを考えます。', steps: ['①「歌わない」と「わ」になるので、昔は「歌はず」。ハ行で活用し、ア・イ・ウ・ウ・エ・エの4段に変わるので四段活用。終止形は「歌ふ」。', '②「払わない」→「払はず」。同じくハ行四段活用で、終止形は「払ふ」。', '③「居る」は古文では「ゐる」と書き、ワ行上一段活用(ゐ・ゐ・ゐる・ゐる・ゐれ・ゐよ)。上一段の動詞は数が少ないので覚える語である。', '確かめとして、①②の連用形「歌ひ」「払ひ」を現代の読みに直すと「うたい」「はらい」になり、現代語の「歌い」「払い」と一致する。'], a: '①歌ふ(ハ行四段活用) ②払ふ(ハ行四段活用) ③ゐる(ワ行上一段活用)', check: '推理した書き方を、もう一度「現代仮名遣い」に直して、元の現代語と同じ読みになるかを確かめます。往復して一致すれば正しいと判断できます。' }] },
      { h: '実戦演習:仮名遣いと活用を組み合わせて読む', t: '入試では、仮名遣いの問題は単独ではなく、活用や掛詞と組み合わせて出されます。戦略は次のとおりです。\n①まず本文の語を現代の読みにして、意味をとります。\n②活用の行を問われたら、歴史的仮名遣いの「書いてあるとおりの文字」で判断します。読みで判断すると、ハ行をワ行やア行とまちがえます。\n③掛詞では、清音と濁音を区別しないこと、歴史的仮名遣いの文字どうしで重なることに注意します。\n典型的な落とし穴は、「言ふ」の連用形を「言い」と書いてしまうことです。答えを歴史的仮名遣いで書くのか、現代仮名遣いで書くのかを、問題文で必ず確かめましょう。', key: '活用の行は「書いてある文字」で、意味は「読み」で考える。答えをどちらの仮名遣いで書くかを、設問で確かめられるかで差がつく。', ex: [{ q: '次の作例を読んで答えよう。\n「をさなき子の、庭に出でて、花をひとつ折りて、母に見せむとて、いそぎ帰りけり。母、これを見て、いとうれしとおもひけり。」\n(1)「をさなき」「おもひ」を現代仮名遣いに直そう。(2)「おもひ」の動詞の終止形を歴史的仮名遣いで書き、何行何活用かを答えよう。(3)「折り」の終止形を書き、「をる」と書くか「おる」と書くかを、理由とともに答えよう。', hint: '(3)は、同じ「おる」でも、漢字によって書き方が変わることを思い出しましょう。', steps: ['(1)「をさなき」は語の頭の「を」を「お」に直して「おさなき」。「おもひ」は語の頭以外の「ひ」を「い」に直して「おもい」。', '(2)「おもひ」は現代語の「思い」にあたる。「思わない」→「思はず」とハ行で活用するので、終止形は「おもふ」、ハ行四段活用。', '(3)「花をひとつ折りて」は「折る」(花の枝を折る)の意味。「折る」は古文では「をる」と書く。', '「居る」も「をり」(ラ変)と書くが、ここは花を折る動作なので「折る」である。「下りる」の意味の「おる」は文脈に合わない。文脈から漢字を決め、その漢字の書き方に従う。'], a: '(1)おさなき/おもい (2)おもふ(ハ行四段活用) (3)終止形は「をる」(折る)。花を折る動作の意味なので、「折る」の歴史的仮名遣いである「をる」と書く。', check: '(2)は、連用形「おもひ」と終止形「おもふ」で、どちらもハ行の文字(ひ・ふ)が使われていることを確かめます。読みの「い・う」で考えるとア行と誤ります。' }] }
    ],
    drill: [
      { lv: 2, q: '現代語の「笑う」「習う」を、古文の終止形で歴史的仮名遣いを使って書こう。また、そう判断した理由を答えよう。', a: '笑ふ・習ふ。現代語で「笑わない」「習わない」と、打消の形でア段が「わ」になるのは、昔の「笑はず」「習はず」の「は」が「わ」と読まれるようになったためで、もとはハ行で活用していたと考えられるから。', exp: '現代語の五段動詞で、打消の形が「〜わない」になるものは、古文ではハ行四段活用の動詞であることが多いです(買う→買ふ、会う→会ふ、追う→追ふ など)。\nただし例外もあります。「植える」は古文で「植う」と書き、ワ行下二段活用(植ゑ・植ゑ・植う…)です。また「老いる」は「老ゆ」でヤ行上二段活用です。\nこの推理は「多くの場合」に当てはまる手がかりで、絶対のルールではありません。最後は辞書で確かめるくせをつけると、正確な知識になります。' },
      { lv: 3, q: '小野小町の和歌「花の色は移りにけりないたづらに わが身世にふるながめせしまに」の「ふる」と「ながめ」は掛詞である。それぞれの2つの意味を答え、なぜ1つの言葉で2つの意味を重ねられるのか、仮名遣いの観点から説明しよう。', a: '「ふる」=「経る」(時がたつ)と「降る」(雨が降る)。「ながめ」=「長雨」と「眺め」(もの思いにふけること)。和歌はひらがなで書かれることが多く、漢字を当てる前の同じ仮名の並び(ふる・ながめ)に、別の漢字の語を重ねることができるから。', exp: '掛詞は、同じ音(仮名)の並びに2つの語を重ねる技法です。和歌が主にひらがなで書かれたことで、読み手は一つの仮名の並びから複数の語を思いうかべることができました。\nこの歌では、「花の色があせていく」ことと「自分の容姿が衰えていく」ことが重ねられています。長雨が降る間に花の色があせたように、もの思いにふけっている間に自分も年をとった、という意味です。\nなお「ながめ」の「眺め」は、現代語の「景色を見る」とちがい、古文では「ぼんやりともの思いにふける」という意味が中心です。語の意味の変化にも注意しましょう。' },
      { lv: 3, q: '次の語を歴史的仮名遣いで書こう。(1)「いる」(弓を射る) (2)「いる」(座っている) (3)「こえ」(声) (4)「かお」(顔)', a: '(1)いる (2)ゐる (3)こゑ (4)かほ', exp: '(1)と(2)は現代では同じ「いる」ですが、古文では書き分けます。「射る」はヤ行上一段活用で「いる」、「居る」はワ行上一段活用で「ゐる」です。上一段活用の動詞「着る・似る・煮る・干る・見る・射る・鋳る・居る・率る」などは、語呂合わせで覚えておくと、行も一緒に確かめられます。\n(3)「こゑ」は「ゑ」を使う代表的な語です。(4)の「かほ」は、語の頭以外の「ほ」が「お」と読まれるルールの逆で、「かお」の「お」が昔は「ほ」だったと推理できます。ただし、「お」がすべて「ほ」だったわけではない(「あを(青)」など)ので、よく出る語は書き方ごと覚えることが大切です。' }
    ],
    faq: [
      ['現代語から昔の書き方を推理する方法は、いつも正しいの?', 'いつも正しいわけではありません。たとえば「〜わない」になる動詞の多くはハ行ですが、「植う」のようにワ行の語もあります。また、「青(あを)」の「を」のように、語ごとに決まっているものは推理だけでは分かりません。この方法は、「たぶんこうだろう」と見当をつけるための手がかりです。よく出る語は書き方ごと覚え、迷ったら辞書で確かめるという使い方をすると、効率よく正確な知識が身につきます。'],
      ['なぜ活用の行は、読みではなく書いてある文字で決めるの?', '活用の行は、文法上の決まりとして、歴史的仮名遣いで書いたときの文字で決めることになっているからです。「言ふ」は「は・ひ・ふ・ふ・へ・へ」とハ行の文字で活用するのでハ行四段活用です。読みの「いわ・いい・いう」で考えると、ワ行やア行がまざって、正しい行が決まりません。古文の文法は、平安時代ごろの書き方をもとに整理されているので、文字を基準にするのです。']
    ]
  });

  add('j_katsuyo', {
    secs: [
      { h: 'さらに深く:音便 ― 連用形が形を変えるわけ', t: '古文を読んでいると、「書いて」「思うて」「読んで」「立って」のように、活用表にない形の動詞に出会います。これは【音便】といって、発音しやすくするために、連用形の最後の音が変わったものです。平安時代から話し言葉で起こり、やがて文章にも書かれるようになりました。\n音便には4種類あります。\n①【イ音便】…「き・ぎ・し」が「い」になる。書きて→書いて、急ぎて→急いで。\n②【ウ音便】…「ひ・び・み」などが「う」になる。思ひて→思うて、給ひて→給うて。\n③【撥音便】…「に・び・み・り」が「ん」になる。死にて→死んで、飛びて→飛んで、読みて→読んで。\n④【促音便】…「ち・ひ・り」が「っ」になる。立ちて→立って、取りて→取って。\n大事なのは、【音便になっても活用形は連用形のまま】だということです。「書いて」の「書い」は、カ行四段活用「書く」の連用形(イ音便)と答えます。\nまた、撥音便の「ん」は、昔の文章では書かれないことがよくあります。ラ変動詞「あり」の連体形「ある」に「めり」「なり」がつくと、「あるめり」→「あんめり」→「あめり」と表記されます。「あめり」を見て「あ+めり」と考えると意味がとれません。「ん」が隠れていると気づくことが、読解のカギになります。\n現代語の五段活用の「書いた・読んだ・立った」は、この音便がそのまま残ったものです。古文の音便は、現代語のふるさとでもあるのです。', key: '音便は連用形の最後の音が「い・う・ん・っ」に変わったもの。形が変わっても活用形は連用形。「あめり」のように「ん」が書かれないこともある。', ex: [{ q: '次の傍線部の動詞の、もとの形(終止形)・活用の種類・活用形と、音便の種類を答えよう。\n①文を【書い】て遣はす。 ②人の【死ん】で後 ③【思う】て言ひけり', hint: '音便になる前の「〜きて」「〜にて」「〜ひて」の形にもどしてみましょう。', steps: ['①「書いて」を音便の前にもどすと「書きて」。「書く」は書か・書き・書く…と活用するカ行四段活用で、「書き」は連用形。「き」が「い」になったのでイ音便。', '②「死んで」をもどすと「死にて」。「死ぬ」はナ行変格活用(死な・死に・死ぬ・死ぬる・死ぬれ・死ね)で、「死に」は連用形。「に」が「ん」になったので撥音便。', '③「思うて」をもどすと「思ひて」。「思ふ」はハ行四段活用で、「思ひ」は連用形。「ひ」が「う」になったのでウ音便。', 'どれも接続助詞「て」の前にあることを確かめる。「て」は連用形につくので、連用形という判断と合う。'], a: '①書く・カ行四段活用・連用形・イ音便 ②死ぬ・ナ行変格活用・連用形・撥音便 ③思ふ・ハ行四段活用・連用形・ウ音便', check: '音便の形を元の形にもどして、文が自然につながるか(書きて遣はす/死にて後/思ひて言ひけり)を確かめます。' }] },
      { h: '実戦演習:文章の中で活用の種類と活用形をすべて判定する', t: '入試では、文章の中のいくつかの動詞について、活用の種類と活用形を答えさせる問題が出ます。戦略は次のとおりです。\n①まず【終止形】にもどします。音便の形なら、もとの形にもどしてから考えます。\n②【覚える動詞】(上一段・下一段・カ変・サ変・ナ変・ラ変)かどうかを先に確かめます。当てはまらなければ、「ず」をつけて四段・上二段・下二段を見分けます。\n③活用形は、【後ろの語】で決めます。係り結びがあれば、文末は連体形・已然形になります。\n落とし穴は、カ変「来」の読み方です。「来ず」は「こず」(未然形)、「来て」は「きて」(連用形)と、読みで活用形が変わります。', key: '「終止形にもどす → 覚える動詞か確かめる → 後ろの語で活用形を決める」の順を守れるかで差がつく。', ex: [{ q: '次の作例を読んで答えよう。\n「男、文を書いて、使ひの者に持たせて遣はしけり。返り事を待てど来ず。男、『いかなることにかあらむ』と思うて、みづから行きぬ。」\n(1)「来ず」の「来」の読みと、活用の種類・活用形を答えよう。(2)「待て」の終止形・活用の種類・活用形を答えよう。(3)「あら」「行き」の活用の種類と活用形を答えよう。', hint: '(2)の「待てど」の「ど」は、已然形につく接続助詞です。', steps: ['(1)「来」はカ行変格活用(こ・き・く・くる・くれ・こ/こよ)。後ろの「ず」は未然形につくので、未然形で「こ」と読む。', '(2)「待てど」の「待て」の終止形は「待つ」。「待たず」とア段になるのでタ行四段活用。後ろの「ど」(〜けれども)は已然形につくので已然形。', '(3)「あら」の終止形は「あり」。ラ行変格活用(あら・あり・あり・ある・あれ・あれ)で、後ろの推量の助動詞「む」は未然形につくので未然形。', '「行き」の終止形は「行く」。「行かず」とア段になるのでカ行四段活用。後ろの完了の助動詞「ぬ」は連用形につくので連用形。'], a: '(1)「こ」と読む。カ行変格活用・未然形。(2)待つ・タ行四段活用・已然形。(3)あら=ラ行変格活用・未然形、行き=カ行四段活用・連用形。', check: '(2)の「待て」は、四段活用では已然形と命令形が同じ形です。後ろに「ど」があるので命令形ではないと確かめます。命令形なら文がそこで切れるはずです。' }] }
    ],
    drill: [
      { lv: 2, q: '「立って」「飛んで」は、それぞれどんな形が音便になったものか。もとの形・活用形・音便の種類を答えよう。', a: '「立って」=「立ちて」(タ行四段「立つ」の連用形)が促音便になったもの。「飛んで」=「飛びて」(バ行四段「飛ぶ」の連用形)が撥音便になったもの。', exp: '音便の種類は、変わった後の音で名前が決まります。「っ」(促音)なら促音便、「ん」(撥音)なら撥音便です。\n「飛びて」が「飛んで」になるとき、「て」が「で」と濁ることにも注意しましょう。撥音「ん」の後では、発音の都合で「て」が「で」になります。現代語の「飛んで」「読んで」も同じです。\nなお、ハ行四段の「言ひて」は、ウ音便「言うて」にも促音便「言って」にもなります。地域や時代によって、なり方がちがうことがあるのです。' },
      { lv: 3, q: '「京には見えぬ鳥なれば、みな人見知らず。」(『伊勢物語』)の「見え」と「見知ら」の活用の種類と活用形を答えよう。また、「見え」がヤ行の動詞である理由を説明しよう。', a: '見え=ヤ行下二段活用「見ゆ」の未然形。見知ら=ラ行四段活用「見知る」の未然形。「見ゆ」は、見え・見え・見ゆ・見ゆる・見ゆれ・見えよ と活用し、終止形が「ゆ」で、「え」もヤ行の「え」なので、ヤ行の動詞になる。', exp: '「見え」の後ろの「ぬ」は、打消の助動詞「ず」の連体形です(後ろに「鳥」という体言がある)。「ず」は未然形につくので、「見え」は未然形です。\n「見ゆ」は「見る」とは別の動詞で、「見える・見られる」という意味の下二段活用です。終止形「見ゆ」の「ゆ」はヤ行の音なので、「見え」の「え」もヤ行の「え」と考えます。ア行の「え」で活用する動詞は「得(う)」一語だけ(心得・所得などの複合語をふくむ)なので、それ以外の「え」はヤ行かワ行(ゑ)と考えるのが基本です。\n「見知ら」は、「見知らず」の形で四段活用と判断できます。' },
      { lv: 3, q: '作例「この山には、鬼すむなりとぞ人言ふなる。げにおそろしき所にこそあめれ。」の「あめれ」は、どのような形が変化したものか。もとの形をすべて示し、文法的に説明しよう。', a: 'ラ変動詞「あり」の連体形「ある」+推定の助動詞「めり」の已然形「めれ」。「あるめれ」が撥音便で「あんめれ」となり、撥音「ん」が表記されずに「あめれ」と書かれたもの。「こそ」の結びなので已然形になっている。', exp: '推定の助動詞「めり」は終止形につきますが、ラ変型の語には連体形につきます。そのため「あり」は連体形「ある」になり、「あるめり」となります。\n「る」の音が「ん」に変わるのが撥音便で、昔の文章では「ん」を書かないことが多かったため、「あめり」と書かれます。これを「あめ(雨)+り」などと読んでしまうと、意味が通りません。\n文末が「めれ」(已然形)になっているのは、前に係助詞「こそ」があるからです。訳は「本当に恐ろしい所であるようだ」です。同じしくみで「あなり」(あるなり)、「なかめり」(なかるめり)なども出てきます。' }
    ],
    faq: [
      ['音便になった動詞は、活用形を何形と答えればいいの?', 'もとの活用形のまま答えます。「書いて」の「書い」はカ行四段活用の連用形で、「連用形(イ音便)」のように音便の種類を添えるのがていねいな答え方です。音便は、発音のしかたが変わっただけで、文法上の働きは変わらないからです。後ろに「て」「たり」などの連用形につく語があることも、連用形だと判断する手がかりになります。'],
      ['撥音便の「ん」が書かれないのは、なぜ?', '平安時代の仮名には、「ん」の音をはっきり書き表す習慣がまだ定まっていなかったと考えられています。そのため、発音では「あんめり」と言っていても、書くときには「あめり」となりました。読むときは、「ん」を補って読むのがふつうです。「あなり」「なかなり」「多かめり」などを見たら、ラ変型の連体形の「る」が撥音便になり、「ん」が書かれていない形だと考えると、正しく意味がとれます。']
    ]
  });

  add('j_h2', {
    secs: [
      { h: 'さらに深く:「む・らむ・けむ」は時間で使い分ける', t: '推量の助動詞「む」には、仲間が2つあります。「らむ」と「けむ」です。この3つは、【どの時間のことを推量するか】で使い分けられています。\n①【む】…未来のこと(まだ起こっていないこと)を推量する。「〜だろう」。未然形につく。例:明日は雨降らむ(明日は雨が降るだろう)。\n②【らむ】…今、目の前に見えていないところで起きていることを推量する(現在推量)。「今ごろ〜しているだろう」。終止形につく(ラ変型には連体形)。例:故郷では今ごろ花咲くらむ。\n③【けむ】…過去のことを推量する(過去推量)。「〜ただろう」。連用形につく。例:昔の人もこの月を見けむ。\nさらに、「らむ」「けむ」には、【原因を推量する】使い方があります。目の前の事実(らむ)や過去の事実(けむ)について、「どうして〜のだろう」とその理由を考える意味です。紀友則の「しづ心なく花の散るらむ」は、花が散っているのは目の前の事実で、その理由を「どうして落ち着いた心もなく散るのだろう」と推量しています。\n見分けのコツは、【その出来事は、もう起きているか】です。まだ起きていなければ「む」、今起きているが見えない(または理由が分からない)なら「らむ」、過去に起きたなら「けむ」です。接続(未然形・終止形・連用形)とあわせて判断すると、まちがいが減ります。', key: '未来は「む」、現在は「らむ」、過去は「けむ」。目の前の事実や過去の事実の「理由」を推量するときも「らむ・けむ」を使う。', ex: [{ q: '次の作例の傍線部を、時間に注意して現代語訳しよう。\n①都にある友も、今ごろはこの月を【見るらむ】。 ②いにしへの人も、この道を【通りけむ】。 ③明日は、この山を【越えむ】。', hint: 'それぞれ、未来・現在・過去のどれについての推量かを考えます。', steps: ['①「らむ」は終止形「見る」(マ行上一段)についている。「今ごろは」とあり、遠くにいる友の今の様子を推量しているので現在推量。', '②「けむ」は連用形「通り」についている。「いにしへの人」とあるので、過去のことを推量している。', '③「む」は未然形「越え」についている。「明日は」とあるので、未来のこと。主語は書かれていないが、話し手自身が山を越えるつもりなら意志、ほかの人について言うなら推量になる。ここでは話し手の予定として意志と考える。', 'それぞれの訳語(今ごろ〜ているだろう/〜ただろう/〜よう・〜だろう)を当てはめる。'], a: '①今ごろはこの月を見ているだろう。②この道を通っただろう。③この山を越えよう(越えるだろう)。', check: '接続を確かめると、①終止形+らむ、②連用形+けむ、③未然形+む、で時間の判断と一致しています。接続と時間の両方が合えば安心です。' }] },
      { h: '実戦演習:一文に重なる助動詞を、順番に分解して訳す', t: '入試の現代語訳の問題では、一つの動詞に助動詞がいくつも連なった形がよく出ます。戦略は次のとおりです。\n①動詞を見つけ、その後ろを【一語ずつ区切る】。\n②区切った語の【接続】を確かめながら、それぞれの意味を決める(前の語が何形かで候補がしぼれます)。\n③訳は【動詞に近い語から順に】つけていく。「受身→完了→推量」のように、内側から外側へ訳を重ねると自然な日本語になります。\n落とし穴は、「れ」「に」「な」などの短い形を見落とすことです。文字数の少ない語ほど、区切りをていねいに確かめましょう。', key: '助動詞は「区切る→接続で意味を決める→動詞に近い順に訳す」。短い形の見落としがないかで差がつく。', ex: [{ q: '次の作例を読んで答えよう。\n「かの人に笑はれなむと思へば、え言ひ出でず。」\n(1)「笑はれなむ」を単語に区切り、それぞれの品詞と意味を答えよう。(2)文全体を現代語訳しよう。(「え〜ず」=〜できない)', hint: '「笑は」の次の「れ」は何の助動詞でしょう。「なむ」の直前の形にも注意します。', steps: ['区切る:笑は/れ/な/む。「笑は」はハ行四段「笑ふ」の未然形。', '「れ」は助動詞「る」。四段の未然形についており、「かの人に」(〜に)とあるので受身。「る」は下二段型に活用するので、「れ」は連用形。', '「なむ」は、直前が連用形「れ」なので、願望の終助詞(未然形につく)ではない。完了(強意)の助動詞「ぬ」の未然形「な」+推量の助動詞「む」。', 'まだ笑われていない未来のことなので、「ぬ」は強意、「む」は推量。訳は動詞に近い順に「笑う→笑われる→きっと笑われてしまうだろう」。', '後半の「え言ひ出でず」は「言い出すことができない」。「思へば」は已然形+ばなので「思うので」。'], a: '(1)笑は(動詞「笑ふ」未然形)/れ(受身の助動詞「る」連用形)/な(強意の助動詞「ぬ」未然形)/む(推量の助動詞「む」終止形)。(2)あの人にきっと笑われてしまうだろうと思うので、言い出すことができない。', check: '「なむ」を願望(〜してほしい)と考えると、「笑われてほしい」となり、言い出せない理由として不自然です。接続(連用形「れ」)と文脈の両方から、強意+推量が正しいと確かめられます。' }] }
    ],
    drill: [
      { lv: 2, q: '作例「去年の今ごろ、君はこの庭の桜を見けむ。」の「けむ」の意味と、「けむ」がどの活用形につくかを答えよう。', a: '意味=過去推量(〜ただろう)。連用形につく(「見」はマ行上一段「見る」の連用形)。訳:去年の今ごろ、あなたはこの庭の桜を見ただろう。', exp: '「去年の今ごろ」とあり、過去のことを推量しているので過去推量です。\n「見る」は上一段活用で、未然形も連用形も「見」と同じ形です。そのため形だけでは活用形が決まりません。このような場合は、助動詞の接続から逆に考えます。「けむ」は連用形につく助動詞なので、ここの「見」は連用形だと判断します。\nまた、「けむ」には過去推量のほかに、過去の原因推量(どうして〜たのだろう)と、過去の伝聞・婉曲(〜たとかいう)の意味もあります。「など」「いかで」など理由を問う語があれば原因推量を考えましょう。' },
      { lv: 3, q: '作例「春雨の降る日、山里にすむ友は、いかに寂しく思ふらむ。」の「らむ」の意味を答え、訳そう。また、「思ふ」と「降る」はそれぞれ何形か、理由とともに答えよう。', a: '「らむ」=現在推量(今ごろ〜ているだろう)。訳:春雨の降る日、山里に住む友は、今ごろどんなに寂しく思っているだろう。「思ふ」=終止形(「らむ」は終止形につくから)。「降る」=連体形(体言「日」に続いているから)。', exp: '話し手は友のいる山里を見ていないので、目の前にない現在のことを推量する「らむ」が使われています。「いかに」(どんなに)とあるので、友の気持ちの程度を思いやっています。\n四段活用の「思ふ」「降る」は、どちらも終止形と連体形が同じ形なので、形だけでは区別できません。そこで後ろの語で決めます。「らむ」は終止形につく(ラ変型には連体形)という接続のきまりから、「思ふ」は終止形です。一方、「降る」は体言「日」に続いているので連体形です。\n同じ形でも、後ろに何が続くかで活用形が変わります。形が同じ活用形をもつ動詞ほど、後ろの語を確かめる習慣が大切です。' },
      { lv: 3, q: '作例「この子を見れば、苦しきこともやみぬ。」と「この子を見ねば、苦しきこともやまず。」の、「見れ」「見ね」の後の語に注意して、2つの文の意味のちがいを説明しよう。', a: '1つめ:見れ(上一段「見る」の已然形)+ば=「見ると・見るので」。訳:この子を見ると、苦しいこともおさまってしまう。2つめ:見(未然形)+ね(打消「ず」の已然形)+ば=「見ないので」。訳:この子を見ないので、苦しいこともおさまらない。', exp: '「見れば」の「見れ」は、上一段活用(見・見・見る・見る・見れ・見よ)の已然形です。已然形+ばは「〜すると・〜するので」と訳す確定条件です。\n「見ねば」の「ね」は、打消の助動詞「ず」の已然形(ざら・ず・ず・ぬ・ね・ざれ)です。完了の「ぬ」の命令形も「ね」ですが、後ろに「ば」が続くことと、文の意味から、打消と判断できます。\nまた、1つめの文末の「やみぬ」の「ぬ」は、連用形「やみ」についた完了の助動詞です。2つめの「やまず」の「ず」と見比べ、「ぬ」と「ず」の働きのちがいを確かめておきましょう。' }
    ],
    faq: [
      ['「らむ」と「けむ」は、和歌でよく見るのはなぜ?', '和歌は、目の前の景色から、見えない場所や過去の時間に思いをはせることが多いからです。遠くにいる恋人の今の様子を思う(らむ)、昔の人の心をしのぶ(けむ)といった気持ちは、和歌の大切な題材です。また、散る花や過ぎ去った出来事について「どうして〜のだろう」と理由を問いかける表現も、和歌でよく使われます。和歌の「らむ」「けむ」を見たら、どの時間の、何を思っているのかを考えると、歌の心が見えてきます。'],
      ['助動詞がいくつも連なるとき、並ぶ順番に決まりはあるの?', 'おおまかな決まりがあります。動詞のすぐ後ろには、使役(す・さす・しむ)や受身・尊敬(る・らる)など、動作そのものに関わる語がきます。その次に完了(つ・ぬ・たり・り)や過去(き・けり)、いちばん外側に推量(む・らむ・べし など)がきます。「笑はれなむ」も、受身→完了(強意)→推量の順です。この順番を知っていると、区切り方に迷ったときの手がかりになります。']
    ]
  });

  add('j_h3', {
    secs: [
      { h: 'さらに深く:「侍り・候ふ」が謙譲語になるとき', t: '「侍り(はべり)」「候ふ(さぶらふ・さうらふ)」は、丁寧語の代表として覚えます。しかし、この2語には【謙譲語として使われる場合】もあり、入試ではそこがよく問われます。\nもともと「侍り・候ふ」は、【身分の高い人のおそばにお仕えする・控える】という意味の謙譲語でした。そこから、「あり・をり」をていねいに言う丁寧語の使い方が生まれたのです。\n見分け方は次のとおりです。\n①【補助動詞(〜はべり・〜さぶらふ)】…動詞などの後ろについて「〜です・〜ます」と訳すなら、丁寧語です。例:「知りはべらず」(知りません)。\n②【本動詞で、身分の高い人のそばにいる場面】…「お仕えする・おそばに控える」と訳せるなら、謙譲語です。例:「女房、御前に候ふ」(女房が中宮のおそばにお仕えしている)。敬意の対象は、そばにいられる身分の高い人(この例では中宮)です。\n③【本動詞で、ただ「ある・いる」の意味】…会話の中で「ここに文はべり」(ここに手紙がございます)のように使われていれば、丁寧語です。敬意の対象は、話の聞き手です。\nつまり、【地の文で、貴人の「御前」「御もと」などにいる】という場面なら謙譲語、【会話文・手紙の中で「あります・おります」】なら丁寧語、と考えるのが目安です。「だれのそばにいるのか」が書かれているかどうかを、まず確かめましょう。', key: '補助動詞の「侍り・候ふ」は丁寧語。本動詞で貴人のそばにいる意味なら謙譲語(お仕えする)。「御前に」などの場所の語が大きな手がかり。', ex: [{ q: '次の作例の傍線部の敬語の種類と、だれへの敬意かを答えよう。\n地の文「中宮の御前に、女房あまた【さぶらふ】。」\n女房の会話「この文は、昨日より、ここに【はべり】。」', hint: '1つめは地の文で「御前に」があります。2つめは会話文で、ただ「ある」という意味です。', steps: ['1つめは本動詞で、「中宮の御前に」とある。女房たちが中宮のおそばにいる場面なので、「お仕えする・控えている」と訳す謙譲語。', '謙譲語の敬意は、動作の受け手(そばにいられる人)に向かう。地の文なので、作者から中宮への敬意。', '2つめは会話文の本動詞で、「この手紙は昨日からここにございます」と、ただ物が「ある」ことをていねいに言っている。丁寧語。', '丁寧語の敬意は聞き手に向かう。会話なので、話し手の女房から、その話を聞いている人への敬意。'], a: '1つめ=謙譲語(お仕えしている)。作者から中宮への敬意。2つめ=丁寧語(ございます)。話し手の女房から、聞き手への敬意。', check: '1つめを丁寧語「たくさんおります」と訳すと、地の文なのに読者への丁寧さを示すことになり、「中宮の御前に」という場所を示す語が生かされません。場面にいちばん合う訳を選んでいるか確かめます。' }] },
      { h: '実戦演習:敬語だけを手がかりに、省略された主語をすべて決める', t: '入試の古文では、人物が3人以上出てきて、主語がほとんど書かれていない場面がよく出ます。戦略は次のとおりです。\n①登場人物を【身分の高い順】に並べます(帝・中宮>大臣>女房 など)。\n②各文の動詞についている敬語を確かめ、【尊敬語がつく動作=身分の高い人】【尊敬語のつかない動作=身分の低い人(または作者自身)】と見当をつけます。\n③謙譲語があれば、その動作の【受け手】が身分の高い人です。\n④最後に、文脈(会話の流れ)で確かめます。\n落とし穴は、身分の低い人物どうしの会話の中で、話し手が相手に尊敬語を使う場合です。会話文の中では、話し手から見た上下で判断しましょう。', key: '敬語の有無で主語の候補をしぼり、謙譲語で動作の受け手を決める。会話文の中では「話し手から見た上下」で考えられるかで差がつく。', ex: [{ q: '次の作例を読み、①〜④の動作の主語を答えよう。\n「大納言、宮の御もとに参りたまひて、物語など聞こえたまふ。宮、いとをかしと①思したり。夜ふけぬれば、大納言②まかでたまふ。宮の御前にさぶらふ女房、③見送りて、『いとめでたき御有様かな』と④言ひあへり。」\n(宮=身分の高い女性。思す=お思いになる。まかづ=退出する(謙譲語)。言ひあへり=言い合っている)', hint: '身分は、宮>大納言>女房の順です。尊敬語がついているかどうかを見ましょう。', steps: ['①「思したり」の「思す」は尊敬語。直前の「宮、いとをかしと」から、主語は宮と分かる。宮は最も身分が高いので尊敬語と合う。', '②「まかでたまふ」は、謙譲語「まかづ」(退出する。退出する先ではなく、退出してくる元の場所の宮を高める)+尊敬語「たまふ」。主語「大納言」が明示されており、大納言を尊敬語で、宮を謙譲語で高める二方面の敬語。', '③「見送りて」には敬語がない。直前に「宮の御前にさぶらふ女房」とあり、身分の低い女房が主語。', '④「言ひあへり」にも敬語がなく、会話文の内容(大納言の様子をほめる)から、女房たちが言い合っていると分かる。', '敬語の有無と身分の順番がすべて一致していることを確かめる。'], a: '①宮 ②大納言 ③女房 ④女房(女房たち)', check: '③④を大納言とすると、尊敬語がないことと合いません。また④の会話の「御有様」は、話している女房たちから大納言への尊敬を表すので、話し手は大納言自身ではないと確かめられます。' }] }
    ],
    drill: [
      { lv: 2, q: '会話文「よろづのこと、知りはべらず。」の「はべら」の敬語の種類と、だれからだれへの敬意かを答え、文を現代語訳しよう。', a: '丁寧語(補助動詞)。話し手から聞き手への敬意。訳:何事も知りません。', exp: '「はべら」は、動詞「知り」の後ろについているので補助動詞です。補助動詞の「侍り」は丁寧語で、「〜です・〜ます」と訳します。\n丁寧語は、話題の中の人物ではなく、【話を聞いている人(会話文の場合)・読者(地の文の場合)】を高めます。ここは会話文なので、話し手から聞き手への敬意です。\n「はべら」は未然形で、打消の「ず」につづいています。「侍り」はラ変動詞(はべら・はべり・はべり・はべる・はべれ・はべれ)なので、終止形が「はべり」と「り」で終わることにも注意しましょう。' },
      { lv: 3, q: '作例「帝、御前にさぶらふ人々に、『この歌、たれか詠みし』と問はせたまふ。」について、(1)「さぶらふ」の敬語の種類と敬意の対象、(2)「せたまふ」の文法的説明と敬意の対象を答えよう。', a: '(1)謙譲語(お仕えする)。作者から帝への敬意。(2)尊敬の助動詞「す」の連用形「せ」+尊敬の補助動詞「たまふ」(最高敬語・二重尊敬)。作者から帝への敬意。', exp: '(1)「御前にさぶらふ」は、帝のおそばにお仕えしているという意味で、本動詞の謙譲語です。お仕えされる帝が敬意の対象になります。\n(2)「せたまふ」の「せ」は、使役の意味のときもありますが、ここでは帝が自分で「問う」動作をしているので尊敬です。「せたまふ・させたまふ」は、帝・中宮など、とくに身分の高い人に使われる【最高敬語(二重尊敬)】です。\n使役か尊敬かを見分けるには、「だれかに〜させる」という相手(使役の対象)が文中にいるかを確かめます。ここでの「人々に」は「問う」相手であり、問わせる相手ではないので、尊敬と判断します。' },
      { lv: 3, q: '作例「姫君の御もとに候ひける侍従といふ女房、姫君に『殿はいづくにかおはします』と申しければ、姫君、『あなたにぞおはしますめる』とのたまひけり。」の「候ひ」「申し」「のたまひ」と、2つの「おはします」について、敬語の種類と、敬意の向き(だれからだれへ)を答えよう。(殿=姫君の父。あなた=あちら)', a: '候ひ=謙譲語(お仕えする)、作者から姫君へ。申し=謙譲語(申し上げる)、作者から姫君へ。のたまひ=尊敬語(おっしゃる)、作者から姫君へ。1つめの「おはします」=尊敬語(いらっしゃる)、侍従から殿へ。2つめの「おはします」=尊敬語、姫君から殿へ。', exp: '地の文の敬語は、すべて作者からの敬意です。「候ひ」は「姫君の御もとに」とあるので、姫君にお仕えする意味の謙譲語で、姫君への敬意です。「申し」は言う相手(姫君)を高める謙譲語、「のたまひ」は言う人(姫君)を高める尊敬語です。\n会話文の敬語は、話し手からの敬意です。1つめの会話の話し手は侍従、2つめは姫君です。どちらも殿がいらっしゃる場所を話題にしているので、「おはします」は殿への敬意になります。\n同じ「おはします」でも、だれの会話の中にあるかで、敬意の主が変わることを確かめましょう。なお「めり」は推定で、「あちらにいらっしゃるようです」と訳します。' }
    ],
    faq: [
      ['「侍り」と「候ふ」は、どうちがうの?', '意味と働きはほぼ同じですが、使われた時代に傾向があります。平安時代の文章では「侍り」がよく使われ、鎌倉時代以降になると「候ふ」が多くなります。『平家物語』などの軍記物語では「候ふ」がたくさん出てきます。どちらも、本動詞で貴人のそばに控える意味なら謙譲語、補助動詞や「あります・おります」の意味なら丁寧語、という見分け方は同じです。'],
      ['会話文の中の敬語で、だれへの敬意かを決めるのがむずかしいです。', '会話文では、「敬意の主=話し手」と最初に決めてしまうのがコツです。そのうえで、尊敬語なら動作をする人、謙譲語なら動作の受け手、丁寧語なら話を聞いている人が、敬意の対象になります。話し手がだれかは、会話の後の「と言ふ」「と申す」の主語で確かめます。会話の中で話題になっている人物は、その場にいないこともあるので、聞き手と混同しないように注意しましょう。']
    ]
  });

  add('j_h4', {
    secs: [
      { h: 'さらに深く:比較と選択の句形 ― 「〜に如かず」「寧ろ〜」', t: '漢文には、2つのものを比べる【比較】と、2つのうちどちらかを選ぶ【選択】の句形があります。どちらも、文の中心になる主張がはっきり出る形なので、入試でよく問われます。\n①【A不如B】(AはBに如かず)…AはBに及ばない。つまり「Bのほうがよい」。「如」は「しく」と読み、「及ぶ」という意味です。\n②【莫如A】(Aに如くは莫し)…Aに及ぶものはない。つまり「Aがいちばんよい」(最上級)。\n③【A於B】(Bよりも〜)…形容詞の後ろに「於」があると、比較を表すことがあります。例:「苛政猛於虎也」(『礼記』)=苛政は虎よりも猛なり(きびしい政治は虎よりもおそろしい)。ここで「於」は置き字ですが、「〜より(も)」と送り仮名で訳を表します。\n④【与其A、寧B】(其のAよりは、寧ろBせよ)…AするよりはむしろBのほうがよい。『論語』の「礼与其奢也寧倹」(礼は其の奢らんよりは寧ろ倹せよ)は、「礼は、ぜいたくにするよりは、むしろつつましくするほうがよい」という意味です。\n⑤【寧A、無B】(寧ろAすとも、Bする無かれ)…たとえAしてもBしてはならない。『史記』の「寧為鶏口、無為牛後」(寧ろ鶏口と為るとも、牛後と為る無かれ)が有名です。\nこれらの句形に共通するのは、【筆者が選ぶのは後ろ(または「寧」のついた側)】だということです。「不如」なら後ろのB、「寧」なら寧のついたほうが、筆者の考える「よいもの」です。', key: '「A不如B」はBがよい、「莫如A」はAがいちばん、「寧」のついたほうを選ぶ。比較・選択の句形は、筆者の価値判断がそのまま表れる。', ex: [{ q: '「寧為鶏口、無為牛後。」を書き下し文にし、意味を答えよう。また、この言葉で、話し手が選んでいるのはどちらか答えよう。(鶏口=にわとりのくちばし、小さな集団の長のたとえ。牛後=牛のしり、大きな集団の下っ端のたとえ)', hint: '「寧A、無B」の形です。「寧」は「むしろ」と読みます。', steps: ['句形を確かめる。「寧A、無B」で、「寧ろAすとも、Bする無かれ」と読む。', '「為」は「なる」と読み、返り点にしたがって「鶏口と為る」「牛後と為る」と読む。', '書き下し文は「寧ろ鶏口と為るとも、牛後と為る無かれ」。「無」は「なかれ」と読んで禁止を表す。', '意味をとる。小さな集団でもその長になるほうがよく、大きな集団の下っ端にはなるな、ということ。選んでいるのは「寧」のついた鶏口のほう。'], a: '書き下し文:寧ろ鶏口と為るとも、牛後と為る無かれ。意味:たとえ小さな集団でもその長になるほうがよく、大きな集団の下につき従う者にはなるな。選んでいるのは「鶏口」。', check: '「寧」は選ぶ側につく字だと確かめます。「無」は禁止(〜するな)なので、牛後は「選ばない側」になり、判断が一致します。' }] },
      { h: '実戦演習:比較の句形をふくむ文章の主張をつかむ', t: '入試の漢文では、句形の知識を使って、本文の【主張や登場人物の考え】を説明させる問題が出ます。戦略は次のとおりです。\n①まず、比較・選択の句形(不如・莫如・寧・与其・於)を探して印をつけます。\n②句形にしたがって、「どちらがよいとされているか」を一言でメモします。\n③そのうえで、話の流れの中で、だれがその考えを述べ、相手はどう反応したかを確かめます。\n落とし穴は、「A不如B」を「AはBのようではない」と訳してしまうことです。「如」は「ごとし」(〜のようだ)とも読む字ですが、「不如」の形では「しかず」(及ばない)と読みます。', key: '「不如」は「如かず」と読み、後ろのほうがよいと判断する。読み方を誤ると主張が正反対になるので、ここで差がつく。', ex: [{ q: '次の作例の漢文を読んで答えよう。\n「人有二好レ書者一。家蔵二万巻一、而未三嘗読二一巻一。客謂レ之曰、蔵二書万巻一、不レ如レ読二一巻一。其人不レ聴。」\n(1)「未三嘗読二一巻一」を書き下し文にしよう。(2)客の言葉「蔵二書万巻一、不レ如レ読二一巻一」を書き下し文にし、意味を答えよう。(3)客がこの言葉で言いたかったことを説明しよう。', hint: '(1)「未」は再読文字です。(2)「不如」は「〜に如かず」と読みます。', steps: ['(1)「未」は再読文字で、1回目は「いまだ」、2回目は「ず」と読む。読む順は、未(いまだ)→嘗→一巻→読→未(ず)。「嘗」は「かつて」と読む。', '書き下し文は「未だ嘗て一巻を読まず」。意味は「これまでに一巻も読んだことがない」。', '(2)読む順は、書→万巻→蔵、一巻→読→如→不。「書万巻を蔵するは、一巻を読むに如かず」と読む。', '「A不如B」なので、Bの「一巻を読む」ほうがよいという意味。「本を一万巻持っていることは、一巻を読むことに及ばない」。', '(3)本を集めて持っていることよりも、たとえ一冊でも実際に読むことのほうが価値がある、と客は言いたかった。本文の「未だ嘗て一巻を読まず」という人物の様子と結びつけて説明する。'], a: '(1)未だ嘗て一巻を読まず。(2)書き下し文:書万巻を蔵するは、一巻を読むに如かず。意味:本を一万巻持っていることは、一巻を読むことに及ばない。(3)本をたくさん集めて持っているだけでは意味がなく、たとえ一冊でも実際に読むことのほうが大切だということ。', check: '「不如」を「〜のようではない」と訳すと、客の言葉の意味が通らなくなります。人物が「一巻も読んだことがない」という前の文と、客の忠告が対応していることを確かめましょう。最後の「其の人聴かず」は、その人が忠告を聞き入れなかったという意味です。' }] }
    ],
    drill: [
      { lv: 2, q: '「霜葉紅於二月花」(杜牧「山行」)を書き下し文にし、意味を答えよう。(霜葉=霜にあたって色づいた葉。二月=旧暦二月で、春のさかり)', a: '書き下し文:霜葉は二月の花よりも紅なり。意味:霜にあたって色づいた葉は、春(二月)の花よりも赤い。', exp: '形容詞「紅」の後ろに「於」があるので、比較の形です。「於」は置き字で読みませんが、「〜より(も)」という送り仮名をつけて比較の意味を表します。\n旧暦の二月は、今の暦でおよそ三月ごろにあたり、春の花が咲くころです。詩人は、秋の紅葉が春の花よりも美しいと感じ、その感動を比較の形で表しています。\n「於」は比較のほかに、場所(〜で・〜に)、対象(〜に)、受身(〜に…される)を表すこともあります。直前が形容詞かどうかが、比較を見分ける手がかりになります。' },
      { lv: 3, q: '『論語』の「礼与其奢也寧倹」を書き下し文にし、意味を答えよう。また、「与其A、寧B」の形が、ただ「Bせよ」と言うのとどうちがうかを説明しよう。(奢=ぜいたくにする。倹=つつましくする)', a: '書き下し文:礼は其の奢らんよりは寧ろ倹せよ。意味:礼は、ぜいたくにするよりは、むしろつつましくするほうがよい。ちがい:ただ「つつましくせよ」と言うのではなく、ぜいたくとつつましさの二つを比べたうえで、つつましさのほうを選んでいることを示し、どちらも完全ではないが、選ぶならこちら、という判断を表す。', exp: '「与其A、寧B」は、「其のAよりは、寧ろBせよ」と読む選択の形です。「与」をここでは「より」と読む点に注意しましょう。「与」はほかに「と」(AとB)、「あたふ」(与える)、「くみす」(味方する)、文末で「か・や」(疑問)などの読み方があります。\nこの言葉は、礼の根本について問われた孔子の答えの一部です。孔子は、ぜいたくな儀式もつつましすぎる儀式も理想ではないが、どちらかを選ぶなら、心のこもったつつましいほうがよい、と考えています。選択の形は、「最善ではないが、よりよいほう」を示すことが多いのです。' },
      { lv: 3, q: '作例「計莫レ如レ帰。」を書き下し文にし、意味を答えよう。また、この文を「不如」を使って同じ意味に書きかえるとき、どのようになるか、書き下し文で示そう。(計=はかりごと・方法)', a: '書き下し文:計は帰るに如くは莫し。意味:方法としては、帰ることがいちばんよい(帰るのに及ぶものはない)。書きかえの例:「他の計は帰るに如かず」(ほかの方法は、帰ることに及ばない)。', exp: '「莫如A」は「Aに如くは莫し」と読み、「Aに及ぶものはない=Aがいちばんよい」という最上級の意味になります。「莫」は「なし」と読み、「無」と同じ働きです。\n「不如」は2つのものの比較、「莫如」はすべてのものとの比較(最上級)という点がちがいます。そのため、「莫如」を「不如」で言いかえるときは、比べる相手を「他の計(ほかの方法)」のように、まとめて示す必要があります。\nどちらの句形でも、「如」は「しく」と読み、「及ぶ」という意味であることが共通しています。' }
    ],
    faq: [
      ['「如」と「若」は、同じように使うの?', '比較の句形では、「如」と「若」はほぼ同じ働きをします。「不若」も「しかず」と読み、「莫若」も「しくはなし」と読みます。また、どちらも「ごとし」(〜のようだ)と読む使い方もあります。「若」にはさらに「なんぢ」(おまえ)、「もし」(仮定)などの読み方もあるので、文の形から判断します。「不」「莫」の後ろにあれば「しく」、文末近くで「〜のようだ」の意味なら「ごとし」と考えるのが目安です。'],
      ['比較の「於」と、場所の「於」は、どう見分けるの?', '直前の語に注目します。「猛」「紅」「大」など、程度を表す形容詞の直後に「於」があれば比較のことが多く、「〜よりも」と訳します。動詞の後ろにあれば、場所(〜で・〜に)や対象(〜に)のことが多いです。また、「見」「為」などと組み合わされていれば受身のこともあります。書き下し文では「於」自体は読まないので、送り仮名の「より」「に」「で」が、どの意味かを表すことになります。']
    ]
  });

  add('j_kanword', {
    secs: [
      { h: 'さらに深く:「為」は読み方で働きが決まる', t: '漢文でいちばん多くの読み方をもつ字の一つが【為】です。「為」は、もともと「何かをする・作る」という広い意味をもつ字で、そこから多くの読み方が生まれました。読み方をまちがえると文の意味が大きく変わるので、形と読みをセットで整理しておきましょう。\n①【なす・する】…「為レ之」(之を為す)=それをする。\n②【なる】…「為二A一」(Aと為る)=Aになる。後ろに名詞があり、「〜と」と送ることが多い。\n③【つくる・をさむ】…「為レ詩」(詩を為る)=詩を作る、「為レ国」(国を為む)=国を治める。文脈で決める。\n④【ために】…「為レA」(Aの為に)=Aのために。後ろに動詞が続く。例:『論語』「為レ人謀而不レ忠乎」(人の為に謀りて忠ならざるか)。\n⑤【たり】…「AはB為り」と読んで、「AはBである」という断定を表すことがある。\n⑥【受身「為A所B」】…「A の B する所と為る」=AにBされる。例:『史記』「後則為二人所一レ制」(後るれば則ち人の制する所と為る)=おくれをとれば人に支配される。\n⑦【以A為B】…「Aを以てBと為す」=AをBとする・AをBだと考える。例:「以レ和為レ貴」(和を以て貴しと為す)。\n見分けのカギは【後ろに何が続くか】です。名詞だけなら②③、「名詞+動詞」なら④、「所」があれば⑥、前に「以」があれば⑦を考えます。', key: '「為」は後ろの形で読みが決まる。名詞なら「なる・なす」、名詞+動詞なら「ために」、「所」があれば受身、「以A為B」なら「AをBとする」。', ex: [{ q: '次の「為」の読み方と意味を答えよう。①為レ人謀(人のためにはかりごとをする) ②為二人所一レ制 ③以レ和為レ貴', hint: 'それぞれ「為」の後ろ(または前)にどんな字があるかを見ます。', steps: ['①「為」の後ろに「人」(名詞)、その後に「謀」(動詞)が続く。「名詞+動詞」なので「ために」と読み、「人の為に謀る」=人のためにはかりごとをする。', '②「為」の後ろに「人」と「所」がある。「為A所B」の受身の形なので、「人の制する所と為る」と読み、「為」は「なる」。意味は「人に支配される」。', '③前に「以」があり、「以A為B」の形。「和を以て貴しと為す」と読み、「為」は「なす」。意味は「調和を大切なものとする」。', 'それぞれの読み方で書き下し文を作り、意味が自然に通るかを確かめる。'], a: '①ため(に)…人のために ②なる(受身「為A所B」)…人に支配される ③なす(「以A為B」)…調和を大切なものとする', check: '①を「人と為りて謀る」(人になってはかる)と読むと、意味が通りません。読み方を決めたら、必ず書き下し文で意味を確かめましょう。' }] },
      { h: '実戦演習:「為」「以」をふくむ文の読みと意味', t: '入試では、「為」「以」の読みを問う問題と、それをふまえた解釈の問題がセットで出されます。戦略は次のとおりです。\n①「為」「以」を見つけたら、前後の字を確かめて、どの形かを判断します。\n②返り点にしたがって読む順番を数字でメモし、書き下し文を作ります。\n③人物の関係(だれが、だれを、どうしたか)を確かめて、意味をまとめます。\n落とし穴は、「以」を「〜で」と訳すだけで済ませ、「以A為B」の形を見落とすことです。「以」の後ろに「為」があれば、まず「AをBとする」を考えましょう。', key: '「以」と「為」が一文の中にそろったら、「以A為B」を疑えるかどうかで差がつく。', ex: [{ q: '次の作例の漢文を読んで答えよう。\n「王以レ甲為レ相。甲辞曰、臣非下能為二国家一謀者上也。」\n(甲=人名。相=宰相、王を助けて政治を行う役。辞=ことわる)\n(1)「王以レ甲為レ相」を書き下し文にし、意味を答えよう。(2)「臣非下能為二国家一謀者上也」を書き下し文にし、意味を答えよう。(3)甲は何をしたのか、説明しよう。', hint: '(1)は「以A為B」、(2)の「為」は後ろに「国家」と「謀」が続いています。', steps: ['(1)「以」と「為」がそろっているので「以A為B」。「王甲を以て相と為す」と読み、「王は甲を宰相にした」という意味。', '(2)読む順を確かめる。「能」は返り点がないので、その場で「能く」と読む。次に「国家」(一)→「為」(二)→「謀」→「者」(上)→「非」(下)→「也」。', '書き下し文は「臣は能く国家の為に謀る者に非ざるなり」。「為」は後ろに「国家」(名詞)+「謀」(動詞)が続くので「ために」。', '意味は「私は、国家のためにはかりごとをすることのできる者ではありません」。「臣」は家来が君主に対して自分をいう言葉。', '(3)「辞して曰はく」とあるので、甲は宰相の役を、自分には能力がないと言って辞退した。'], a: '(1)王甲を以て相と為す。王は甲を宰相にした(任命した)。(2)臣は能く国家の為に謀る者に非ざるなり。私は、国家のためにはかりごとをめぐらすことのできる者ではありません。(3)甲は、自分には国家のために政治を考える力がないと言って、王から任命された宰相の役を辞退した。', check: '(1)の「為」は「なす」、(2)の「為」は「ために」と、同じ字でも読みが変わることを確かめます。「非」は下から返って読む字で、「〜に非ず」と読むことも確認しましょう。' }] }
    ],
    drill: [
      { lv: 2, q: '「以レ和為レ貴」を書き下し文にし、意味を答えよう。また、この文の「以」と「為」の働きを説明しよう。', a: '書き下し文:和を以て貴しと為す。意味:調和を大切なものとする。働き:「以A為B」の形で、「AをBとする・AをBだと考える」という意味になる。「以」は「〜を」と対象を示し、「為」は「なす」と読んで「〜とする」を表す。', exp: '「以A為B」は、Aを何かとして「扱う」「認める」「考える」ことを表す、とても大事な形です。「以レ石為レ枕」(石を以て枕と為す=石を枕にする)のように、物を何かとして使う意味にもなります。\n「以」は単独では「もつて」と読み、「〜で(手段)」「〜によって(理由)」「〜を」などの意味をもちます。また「以為」と二字が続くと「おもへらく」(思うことには)と読む特別な形になるので、区別しましょう。\n「貴し」は形容詞で、送り仮名「と」をつけて「貴しと為す」と読みます。' },
      { lv: 3, q: '『史記』の「先即制レ人、後則為二人所一レ制」を書き下し文にし、意味を答えよう。また、前半と後半の対比から、この言葉が言おうとしていることを説明しよう。(即・則=すなはち)', a: '書き下し文:先んずれば即ち人を制し、後るれば則ち人の制する所と為る。意味:人より先に行動すれば人を支配でき、おくれをとれば人に支配される。言おうとしていること:同じ「制する」という動作でも、先に動くか後になるかで、支配する側と支配される側が入れかわるので、何事も先手をとることが大切だということ。', exp: '後半の「為二人所一レ制」は、「為A所B」の受身の形です。「人の制する所と為る」と読み、「人に支配される」と訳します。\n前半の「制レ人」(人を制す)と、後半の受身「人に制せらる」が対になっていることに注目しましょう。同じ動詞を使って、能動と受身を対比しています。漢文では、このような対句が主張を強めるために使われることが多いです。\n「即」「則」はどちらも「すなはち」と読み、「〜すれば(そのときは)」という条件と結果をつなぐ働きがあります。「先んずれば」「後るれば」と已然形+ばで読むのはそのためです。' },
      { lv: 3, q: '次の2つの「為」の読み方と意味のちがいを説明しよう。①「化為レ鶴」(化して鶴と為る) ②「為レ鶴作レ巣」(鶴の為に巣を作る)', a: '①「なる」…姿を変えて鶴になる。後ろが名詞「鶴」だけで、変化の結果を表している。②「ために」…鶴のために巣を作る。後ろに名詞「鶴」と、動詞をふくむ「作レ巣」が続き、目的・利益の相手を表している。', exp: 'どちらも「為レ鶴」という同じ並びですが、その後ろに何が続くかで読み方が変わります。\n①は「為レ鶴」で文が切れているので、「鶴と為る」と変化の結果を表します。前の「化して」(姿を変えて)という語とも意味が合います。\n②は「為レ鶴」の後ろに「作レ巣」という動作が続いているので、「鶴の為に」と読んで、その動作がだれのためかを表します。\nこのように、漢文では同じ字の並びでも、文全体の構造(どこで文が切れるか、後ろに動詞があるか)を見ないと読みが決まらないことがあります。' }
    ],
    faq: [
      ['「以為」は、なぜ「おもへらく」と読むの?', '「以為」は、本来「以て為す」(〜と考える)という意味で、「AをBと考える」の「A」が省略された形です。そこから、「思うことには」という意味の特別な読み方「おもへらく」が生まれました。「おもへらく」は、動詞「思ふ」の已然形に完了の「り」がつき、「〜すること」という意味の「く」がついた形です。「以為〜」とあれば、その後ろに、ある人の考えの内容が続くと考えて読みましょう。'],
      ['「為」の読み方は、全部覚えないといけないの?', '全部を同じように覚える必要はありません。入試で特によく問われるのは、「ために」「なる」「なす」と、受身の「為A所B」、「以A為B」の5つです。この5つは、形から判断できるように練習しておきましょう。「つくる」「をさむ」「たり」などは、文脈から判断することが多いので、出会ったときに意味を確かめれば十分です。大切なのは、読み方を決めたら書き下し文にして、意味が通るかを確かめることです。']
    ]
  });

  add('j_kanji', {
    secs: [
      { h: 'さらに深く:三字熟語の組み立てと「不・無・非・未」', t: '二字熟語の組み立てを学んだので、次は【三字熟語】です。三字熟語は、ほとんどが次の3つの型に分けられます。\n①【1字+2字】…上の1字が下の二字熟語に意味を加える。例:「未・解決」「不・完全」「大・自然」「新・学期」。\n②【2字+1字】…上の二字熟語に、下の1字が意味を加える。例:「積極・的」「安全・性」「近代・化」「図書・館」。\n③【1字+1字+1字】…3つの字が対等に並ぶ。例:「松竹梅」「衣食住」「市町村」。\nとくに大切なのが、①の上につく【打ち消しの字】です。4つの字は、それぞれ打ち消し方がちがいます。\n・【不】…「〜でない・〜しない」。例:不安定、不自由、不注意。\n・【無】…「〜がない」。例:無関心、無責任、無意識。\n・【非】…「〜ではない・〜に当たらない」。例:非常識、非公式、非科学的。\n・【未】…「まだ〜していない」。例:未解決、未完成、未成年。\n使い分けのコツは、下の熟語を文に入れて考えることです。「関心がない」なら「無」、「まだ解決していない」なら「未」となります。「未」は時間がたてば変わる可能性をふくみ(いつか解決するかもしれない)、「不」「無」は状態そのものを打ち消す、というちがいがあります。\nまた、②の下につく「的・性・化・感・観」なども、意味がはっきりしています。「的」は「〜のような・〜に関する」、「化」は「〜になる・〜にする」、「性」は「〜という性質」です。', key: '三字熟語は「1+2」「2+1」「1+1+1」の3型。打ち消しの字は、不=〜でない、無=〜がない、非=〜ではない、未=まだ〜ない、と意味で選ぶ。', ex: [{ q: '次の( )に「不・無・非・未」のどれかを入れて、三字熟語を完成させよう。①( )意識 ②( )公開 ③( )合理 ④( )常識', hint: '下の二字熟語を「〜がない」「まだ〜していない」などの文に入れてみましょう。', steps: ['①「意識」は「意識がない」と言えるので「無」。「無意識」=自分で気づかないまま。', '②「公開」は「まだ公開していない」が自然なので「未」。「未公開」=まだ公開されていない。', '③「合理」は「合理的でない」の意味なので「不」。「不合理」=理屈に合わない。', '④「常識」は「常識に当たらない・常識ではない」の意味なので「非」。「非常識」=常識から外れている。'], a: '①無意識 ②未公開 ③不合理 ④非常識', check: '完成した熟語を「〜がない」「まだ〜ない」などに言いかえて、意味が自然かを確かめます。「無公開」「未常識」などは実際に使われない形です。' }] },
      { h: '実戦演習:熟語の構成を見ぬいて同じ型を選ぶ', t: '高校入試では、「次の熟語と同じ構成のものを選べ」という問題がよく出ます。二字・三字が混ざって出ることもあります。戦略は次のとおりです。\n①まず、熟語を【訓読みや短い文に直して】、字と字の関係を言葉にします(「未解決」→「まだ解決していない」)。\n②三字熟語なら、どこで区切れるか(1+2、2+1、1+1+1)を確かめます。\n③選択肢も同じように言葉にしてから比べます。\n落とし穴は、見た目が似ているだけで選ぶことです。「不」と「非」は形が似た働きをしますが、選択肢に「不」が2つあるときは、その下の熟語の関係まで確かめましょう。', key: '熟語を短い文に言いかえ、区切り方と字どうしの関係で比べられるかで差がつく。見た目のにている字に引っぱられない。', ex: [{ q: '次の問いに答えよう。\n(1)「無関心」と同じ構成の三字熟語を、ア〜エから1つ選ぼう。\nア 自動車 イ 未完成 ウ 雪月花 エ 安全性\n(2)「積極的」と同じ構成の三字熟語を、ア〜エから1つ選ぼう。\nア 不安定 イ 運動場 ウ 上中下 エ 非公式', hint: 'それぞれ、どこで区切れるか(1+2、2+1、1+1+1)を確かめましょう。', steps: ['(1)「無関心」は「無・関心」の1+2で、「関心がない」と打ち消しの字が上につく型。', '選択肢を区切る。ア「自動・車」は2+1。イ「未・完成」は1+2で、打ち消しの字が上につく。ウ「雪・月・花」は1+1+1。エ「安全・性」は2+1。', '(1)の答えはイ。', '(2)「積極的」は「積極・的」の2+1で、下の「的」が「〜のような」という意味を加える型。', '選択肢では、ア「不・安定」は1+2、イ「運動・場」は2+1、ウは1+1+1、エ「非・公式」は1+2。2+1はイだけなのでイを選ぶ。'], a: '(1)イ (2)イ', check: '(2)のイ「運動場」は、「的」のような接尾語ではなく「場」という名詞ですが、「二字熟語+意味を加える1字」という型は同じです。選択肢の中で2+1がイだけであることを確かめれば、迷わず選べます。' }] }
    ],
    drill: [
      { lv: 2, q: '「衣食住」「市町村」と同じ組み立ての三字熟語を1つ書き、その組み立てを説明しよう。', a: '(例)松竹梅・上中下・雪月花。3つの漢字がそれぞれ対等の関係で並んでいる(1字+1字+1字)。', exp: '「衣食住」は「衣(着るもの)・食(食べるもの)・住(住むところ)」と、3つの字が対等に並んでいます。どれか1字が他の字を修飾しているわけではありません。\n同じ型には「松竹梅」「上中下」「雪月花」「心技体」「大中小」などがあります。\nまちがえやすいのは「大自然」のように、1字目が下の二字熟語を修飾している型です。「大・自然」は「大きな自然」と言いかえられるので1+2の型です。3つの字を1字ずつに区切ったとき、それぞれが対等に並んでいるかを確かめましょう。' },
      { lv: 3, q: '「不・無・非・未」のどれかを上につけて三字熟語を作り、意味を答えよう。①( )確定 ②( )関係 ③( )参加 ④( )人情', a: '①未確定(まだ確定していない) ②無関係(関係がない) ③不参加(参加しない) ④不人情(思いやりがない・人情に欠ける)', exp: '①「確定」は、時間がたてば決まる可能性があるので「未」を使います。②「関係」は「関係がない」なので「無」。\n③は「参加しない」という意味で「不参加」が一般的です。「非」は「非公式」「非常識」のように、ある性質に当たらないことを表すことが多く、動作の打ち消しにはあまり使いません。\n④の「人情」は「無人情」とは言わず、「不人情」と言います。このように、どの字がつくかは、意味からある程度推理できますが、最後は慣用で決まっている部分もあります。辞書でよく使われる形を確かめておきましょう。' },
      { lv: 3, q: '次のうち、熟語の構成が他と異なるものを1つ選び、理由を説明しよう。\nア 新学期 イ 高気圧 ウ 美術館 エ 大事件', a: 'ウ。ア「新・学期」、イ「高・気圧」、エ「大・事件」は、上の1字が下の二字熟語を修飾する1+2の型だが、ウ「美術・館」は、二字熟語「美術」に「館」がついた2+1の型だから。', exp: '三字熟語の構成を見分けるときは、どこで区切ると意味が通るかを考えます。\nア「新しい学期」、イ「高い気圧」、エ「大きな事件」と言いかえると、上の1字が下の二字熟語を修飾していることが分かります。\nウは「美しい術の館」ではなく、「美術の(ための)館」と区切るのが自然です。「館」は「図書館」「体育館」のように、建物を表す1字として下につきます。\nイの「高気圧」を「高気・圧」と区切ってしまうと意味が通りません。区切った後、それぞれの部分が独立した言葉になっているかを確かめるのがコツです。' }
    ],
    faq: [
      ['四字熟語にも、組み立ての型があるの?', 'あります。多くの四字熟語は、二字熟語が2つ組み合わさった【2字+2字】の型です。「起承転結」のように4字が対等に並ぶもの、「自画自賛」(自分で描いた絵を自分でほめる)のように上下の二字熟語が主語・述語や修飾の関係になるもの、「一進一退」のように対になる意味の二字を並べたものなどがあります。三字熟語と同じく、どこで区切ると意味が通るかを考えると、意味を覚えやすく、書きまちがいも減ります。'],
      ['「的」をつけた言葉は、なぜこんなに多いの?', '「的」は、明治時代以降に、英語などの「〜tic」「〜al」のような語を訳すときに盛んに使われるようになったと言われています。「科学的」「積極的」「現代的」のように、名詞に「的」をつけると、「〜のような・〜に関する・〜の性質をもった」という意味の言葉を簡単に作れるからです。便利な反面、意味があいまいになりやすいので、作文では「〜的」を使いすぎないように気をつけると、分かりやすい文章になります。']
    ]
  });

  add('j_m1', {
    secs: [
      { h: 'さらに深く:対義語・類義語は「漢字の対応」で整理する', t: '対義語(意味が反対の語)と類義語(意味が似ている語)は、漢字の組み合わせのしかたで整理すると、ずっと覚えやすくなります。\n【対義語の型】\n①【1字が共通で、もう1字が反対】…楽観⇔悲観、主観⇔客観、直接⇔間接、輸入⇔輸出、好況⇔不況。共通の字があるので、残りの字を反対にすればよいと分かります。\n②【2字とも反対】…上昇⇔下降(上⇔下、昇⇔降)、拡大⇔縮小、増加⇔減少、前進⇔後退。1字ずつ反対の字が対応しています。\n③【全体で反対】…原因⇔結果、権利⇔義務、需要⇔供給、理想⇔現実。字の対応はなく、意味のまとまりとして反対になっています。これは語ごとに覚えます。\n【類義語の型】\n類義語も、1字が共通のもの(基本≒基礎、永遠≒永久)と、字がまったくちがうもの(準備≒用意、手段≒方法、欠点≒短所)があります。\n大切なのは、【類義語は「まったく同じ」ではない】ということです。「体験」と「経験」は似ていますが、「体験」は自分の体で実際にしてみること(職場体験)、「経験」は実際にしてみて身についた知識や技能(経験を積む)を表すことが多く、「経験豊富」とは言っても「体験豊富」はあまり言いません。文の中で入れかえられるかどうかを試すと、ちがいが見えてきます。', key: '対義語は「1字共通」「2字とも反対」「全体で反対」の3型。類義語は似ていても入れかえられない場面があり、そこにそれぞれの語の個性がある。', ex: [{ q: '次の語の対義語を答え、どの型(1字共通/2字とも反対/全体で反対)かを答えよう。①往路 ②需要 ③延長', hint: '①は「路」、③は「長」の字に注目しましょう。', steps: ['①「往路」は「行きの道」。「往」の反対は「復」(もどる)なので、対義語は「復路」。「路」が共通なので1字共通の型。', '②「需要」は「物を求めること」。反対は「物を出して与えること」で「供給」。字の対応はないので、全体で反対の型。', '③「延長」は「のばして長くする」。反対は「ちぢめて短くする」で「短縮」。延⇔縮、長⇔短と2字とも反対になっているので、2字とも反対の型(字の順番が入れかわっている)。', 'それぞれ、文に入れて反対の意味になるか確かめる(往路は電車、復路はバス/需要が増える・供給が増える/時間を延長する・時間を短縮する)。'], a: '①復路(1字共通) ②供給(全体で反対) ③短縮(2字とも反対)', check: '③は「延⇔縮」「長⇔短」の対応が、字の並び順では入れかわっています(延長/短縮)。順番が同じとはかぎらないことに注意して確かめます。' }] },
      { h: '実戦演習:類義語の使い分けを文脈で決める', t: '高校入試の語彙問題では、似た意味の語から、文脈に最も合うものを選ぶ問題が出ます。戦略は次のとおりです。\n①選択肢の語を、それぞれ【短い例文】に入れて、ふつうに使える場面を思いうかべます。\n②問題文の( )の前後にある語(とくに、いっしょに使われる名詞や動詞)との結びつきを確かめます。「経験を積む」「利用者」のように、決まった結びつきがあることが多いからです。\n③迷ったら、( )に入れて声に出して読み、不自然な選択肢を消します。\n落とし穴は、意味だけで選んで、結びつきを確かめないことです。意味が近くても、いっしょに使えない語の組み合わせがあります。', key: '類義語は「いっしょに使われる語」との結びつきで決まることが多い。意味だけでなく結びつきまで確かめられるかで差がつく。', ex: [{ q: '次の( )に入る語として最も適切なものを、それぞれ選ぼう。\n①空き缶を( )して、子どもたちがおもちゃを作った。(ア 使用 イ 利用)\n②彼は長年の( )を生かして、後輩に的確な助言をした。(ア 体験 イ 経験)\n③この薬は、決められた量を守って( )してください。(ア 使用 イ 利用)', hint: '「利用」には「本来の目的以外に役立てる」という意味合いがあります。', steps: ['①空き缶は、本来おもちゃを作るためのものではない。本来の目的とちがう形で役立てているので、「利用」が適切。', '②「長年の」「生かして」とあるので、長い時間をかけて身についた知識や技能を表す「経験」が適切。「体験」は一回一回の実際の出来事を表すことが多い。', '③薬を本来の目的どおりに使うことなので、「使用」が適切。「使用量」「使用上の注意」という結びつきもある。', 'それぞれ( )に入れて読み、自然な文になるかを確かめる。'], a: '①イ(利用) ②イ(経験) ③ア(使用)', check: '①を「使用」にすると、空き缶を缶として使ったように読めてしまいます。逆に③を「利用」にすると、薬を別の目的に使うような印象になります。入れかえて違和感があるかで確かめます。' }] }
    ],
    drill: [
      { lv: 2, q: '次の語の対義語を答えよう。①楽観 ②拡大 ③権利', a: '①悲観 ②縮小 ③義務', exp: '①「楽観」は物事をよいほうに考えること、「悲観」は悪いほうに考えることです。「観」が共通しているので、「楽⇔悲」を反対にすれば作れます。\n②「拡大」は広げて大きくすること、「縮小」はちぢめて小さくすることです。「拡⇔縮」「大⇔小」と、2字とも反対の字が対応しています。\n③「権利」と「義務」は、字の対応がない「全体で反対」の型です。権利は「あることをしてよい資格」、義務は「しなければならないこと」です。社会科でもよく出る組み合わせなので、セットで覚えておきましょう。' },
      { lv: 3, q: '「基本」と「基礎」は類義語だが、入れかえられない場合がある。それぞれを使った例文を作り、ちがいを説明しよう。', a: '(例)「基礎工事」とは言うが「基本工事」とはあまり言わない。「基本料金」とは言うが「基礎料金」とはあまり言わない。ちがい:「基礎」は、その上に何かを積み上げるための土台という意味が強く、「基本」は、物事のよりどころとなる中心・標準という意味が強い。', exp: '「基礎」の「礎(いしずえ)」は、建物の柱の下に置く土台の石のことです。そのため「基礎」には「その上に積み上げていく土台」という意味合いがあります。「基礎体力」「基礎知識」は、その上にさらに力や知識を積み上げることを前提にしています。\n一方、「基本」の「本」は「もと・中心」という意味で、「基本方針」「基本料金」のように、物事の中心・標準となるものを表します。\n「基本を学ぶ」「基礎を学ぶ」のように、どちらも使える場合も多いですが、決まった結びつきでは入れかえられません。漢字の意味から、ちがいを説明できるようにしましょう。' },
      { lv: 3, q: '次の対義語の組み合わせのうち、誤っているものを1つ選び、正しい対義語に直そう。\nア 具体 ⇔ 抽象 イ 損失 ⇔ 利益 ウ 消費 ⇔ 生産 エ 単純 ⇔ 複雑 オ 革新 ⇔ 改革', a: 'オ。「改革」は「革新」とほぼ同じ意味(類義語)である。「革新」の対義語は「保守」。', exp: '「革新」は古いしくみを改めて新しくすること、「改革」も制度などを改めてよくすることで、意味はほとんど同じです。「革」という字が共通しているので、つい対義語と思ってしまいがちですが、共通の字があっても対義語とはかぎりません。\n「革新」の対義語は、古いしくみや伝統を守ろうとする「保守」です。\nほかの組み合わせはすべて正しい対義語です。イ「損失⇔利益」は「全体で反対」、ウ「消費⇔生産」も「全体で反対」、エ「単純⇔複雑」も「全体で反対」の型です。字が共通していることより、意味が反対かどうかを確かめることが大切です。' }
    ],
    faq: [
      ['対義語は、いつも1つに決まっているの?', '1つとはかぎりません。「高い」の対義語は、高さなら「低い」、値段なら「安い」になるように、意味によって対義語が変わります。熟語でも、「自然」の対義語は、文脈によって「人工」(人が作ったもの)にも「不自然」(自然でない)にもなります。対義語を答える問題では、問題文の中で、その語がどの意味で使われているかを確かめてから答えましょう。'],
      ['類義語のちがいは、どうやって調べればいいの?', '国語辞典で両方の語を引き、説明と用例を比べるのがいちばん確かです。辞典によっては、「使い分け」の欄があり、似た語のちがいを説明してくれています。また、自分で「〜を積む」「〜者」「〜料金」のように、後ろにつく語を変えて、両方に使えるかを試すのも効果的です。どちらか一方にしか使えない組み合わせを見つけると、その語の中心的な意味が見えてきます。']
    ]
  });

  add('j_m2', {
    secs: [
      { h: 'さらに深く:助詞の4つの種類と、同じ形の見分け方', t: '助詞は付属語で活用しない語ですが、働きによって4つの種類に分けられます。\n①【格助詞】…主に体言(名詞)について、その語が文の中でどんな役割(主語・目的語・場所など)かを示す。が・の・を・に・へ・と・から・より・で・や。覚え方「鬼が戸より出、空の部屋」(を・に・が・と・より・で・から・の・へ・や)。\n②【接続助詞】…主に用言や助動詞について、前後の文や文節をつなぐ。ば・と・ても(でも)・けれど(けれども)・が・のに・ので・から・し・て(で)・ながら など。\n③【副助詞】…いろいろな語について、意味をそえる。は・も・こそ・さえ・でも・しか・まで・ばかり・だけ・ほど・くらい・など など。\n④【終助詞】…文の終わりについて、疑問・感動・禁止などの気持ちを表す。か・な・よ・ね・ぞ・とも など。\n入試で問われるのは、【同じ形で種類がちがう助詞】です。見分けのカギは、【直前の語が体言か、活用する語か】です。\n・「が」…「雨が降る」(体言「雨」+が=格助詞、主語)/「雨が降ったが、試合は行われた」(助動詞「た」+が=接続助詞、逆接)。\n・「から」…「駅から歩く」(体言+から=格助詞、起点)/「寒いから上着を着る」(形容詞+から=接続助詞、理由)。\n・「と」…「友だちと遊ぶ」(体言+と=格助詞、相手)/「春になると暖かくなる」(動詞+と=接続助詞、条件)。\n直前の語を確かめ、体言なら格助詞、活用する語(動詞・形容詞・助動詞など)の終止形なら接続助詞、と考えるのが基本です。', key: '助詞は格・接続・副・終の4種類。同じ形の「が・から・と」は、直前が体言なら格助詞、活用語なら接続助詞が基本。', ex: [{ q: '次の傍線部の助詞の種類を答えよう。\n①兄【が】作った料理を食べた。 ②よく練習した【が】、試合に負けた。 ③暗くなった【から】、家に帰ろう。 ④学校【から】図書館まで歩いた。', hint: 'それぞれの直前の語が、体言(名詞)か、活用する語かを確かめましょう。', steps: ['①直前は「兄」で名詞(体言)。「兄が」は「作った」の主語を示しているので格助詞。', '②直前は「した」の「た」(過去の助動詞)。活用する語の後ろについて、「練習した」と「負けた」を逆接でつないでいるので接続助詞。', '③直前は「暗くなった」の「た」(助動詞)。理由を表して後ろにつないでいるので接続助詞。', '④直前は「学校」で名詞。「から」は起点(どこから)を示しているので格助詞。'], a: '①格助詞 ②接続助詞 ③接続助詞 ④格助詞', check: '格助詞の「が」は、主語を示すので「〜は」に言いかえられることが多いです(兄は作った)。接続助詞の「が」は「けれども」に言いかえられます(練習したけれども)。言いかえテストでも確かめられます。' }] },
      { h: '実戦演習:「同じ働きのもの」を選ぶ助詞の識別', t: '高校入試の文法問題では、「傍線部と同じ働きの助詞を選べ」という形がよく出ます。戦略は次のとおりです。\n①傍線部の【直前の語の品詞】を確かめます。\n②【言いかえテスト】をします。「が」なら「けれども」、「から」なら「ので」、「と」なら「〜すると・〜といっしょに・〜と言う」などに置きかえて、意味が通るか試します。\n③選択肢も同じ手順で調べ、働きが一致するものを選びます。\n落とし穴は、「と」の格助詞に、相手(〜といっしょに)・引用(〜と言う)・結果(〜となる)など、いくつも働きがあることです。種類が同じでも働きがちがうことがあるので、問題が「種類」を聞いているのか「働き(意味)」を聞いているのかを確かめましょう。', key: '直前の品詞+言いかえテストの2段階で判断する。「種類」と「意味・働き」のどちらを問われているかで差がつく。', ex: [{ q: '次の(1)(2)の傍線部と同じ働きのものを、それぞれア〜ウから選ぼう。\n(1)ボタンを押す【と】、ドアが開いた。\nア 母【と】買い物に行った。 イ 窓を開ける【と】、風が入ってきた。 ウ 「ありがとう」【と】言った。\n(2)このかばんは軽い【から】、旅行に便利だ。\nア 雨が降り出した【から】、急いで帰った。 イ 東京【から】大阪へ向かう。 ウ 豆腐は大豆【から】作られる。', hint: '(1)は「〜すると」の条件、(2)は理由を表しています。', steps: ['(1)傍線部の直前は動詞「押す」(終止形)。「押すと、開いた」は「押したら、そのとき」という条件・きっかけを表す接続助詞。', 'ア「母と」は名詞+と=格助詞(相手)。イ「開けると」は動詞+と=接続助詞(条件)。ウ「ありがとうと」は引用を表す格助詞。よって(1)はイ。', '(2)傍線部の直前は形容詞「軽い」(終止形)。「軽いので」と言いかえられるので、理由を表す接続助詞。', 'ア「降り出したから」は助動詞+から=接続助詞(理由)、「降り出したので」と言いかえられる。イ「東京から」は名詞+から=格助詞(起点)。ウ「大豆から」は名詞+から=格助詞(原料)。よって(2)はア。'], a: '(1)イ (2)ア', check: '(2)のイとウは、どちらも格助詞ですが、働きは起点と原料でちがいます。今回は「理由」を表すものを選ぶので、「ので」に言いかえられるかどうかで確かめれば、迷わず選べます。' }] }
    ],
    drill: [
      { lv: 2, q: '「弟でさえ、この問題は解けた。」の「さえ」と、「本を読みながら、音楽を聞く。」の「ながら」の助詞の種類を答えよう。', a: '「さえ」=副助詞 「ながら」=接続助詞', exp: '「さえ」は、「弟でさえ」のように語について、「(ほかはもちろん)〜でも」という意味をそえる副助詞です。副助詞は、取りのぞいても文の骨組みは残りますが、意味の細かいニュアンスが変わります(弟は解けた/弟でさえ解けた)。\n「ながら」は、動詞「読み」(連用形)について、「読む」と「聞く」という2つの動作が同時に行われることを表し、前後をつないでいるので接続助詞です。\nなお「ながら」には、「狭いながら、居心地のよい部屋」のように、逆接(〜けれども)を表す使い方もあります。同じ接続助詞でも、意味が1つとはかぎらないことを覚えておきましょう。' },
      { lv: 3, q: '次の傍線部のうち、助詞の種類が他と異なるものを1つ選び、理由を説明しよう。\nア 公園で遊ん【で】いる。 イ 図書館【で】勉強する。 ウ はさみ【で】紙を切る。 エ 病気【で】学校を休んだ。', a: 'ア。アの「で」は、動詞「遊ぶ」の連用形「遊ん」(撥音便)についた接続助詞「て」が濁ったもの。イ・ウ・エは、名詞について場所・手段・原因を表す格助詞「で」。', exp: 'イ「図書館で」(場所)、ウ「はさみで」(手段)、エ「病気で」(原因・理由)は、どれも名詞についている格助詞です。働きはそれぞれちがいますが、種類は同じ格助詞です。\nアは、「遊ぶ」の連用形「遊び」が撥音便で「遊ん」になり、その後ろの接続助詞「て」が「で」と濁った形です。「読んで」「飛んで」なども同じです。\n見分けのコツは、直前の語に注目することです。直前が名詞なら格助詞、動詞の音便形(〜ん・〜い)なら接続助詞「て」の濁ったもの、と考えましょう。また、「静かで」の「で」は形容動詞の活用語尾なので、これとも区別が必要です。' },
      { lv: 3, q: '「行くか行かないか、まだ決めていない。」と「明日は晴れるだろうか。」の「か」は、それぞれどの種類の助詞か。理由とともに答えよう。', a: '1つめの「か」=副助詞(「行くか行かないか」と並べて、不確かなことを示し、文の途中で使われている)。2つめの「か」=終助詞(文の終わりについて、疑問の気持ちを表している)。', exp: '「か」には、副助詞と終助詞の2つの使い方があります。\n終助詞の「か」は、文の終わりについて、疑問・反語・勧誘などの気持ちを表します(行きませんか/そんなことがあるものか)。\n副助詞の「か」は、文の途中で、「〜か〜か」と並べて選択を示したり、「だれか」「いつか」のように不確かなことを表したりします。\n見分けのコツは、「か」の位置です。文の終わり(句点の直前)にあれば終助詞、文の途中にあって後ろに文が続いていれば副助詞と考えるのが基本です。' }
    ],
    faq: [
      ['格助詞の覚え方「鬼が戸より出、空の部屋」に入っていない格助詞はないの?', '中学校で学ぶ主な格助詞は、この10個(を・に・が・と・より・で・から・の・へ・や)です。これ以外の語が格助詞として出てくることはほとんどありません。ただし、この10個の中にも、「の」のように主語(雨の降る日)・連体修飾(私の本)・体言の代用(走るのが速い)など、いくつもの働きをもつ語があります。種類を覚えたら、次はそれぞれの語の働きの見分け方を練習しましょう。'],
      ['副助詞と格助詞は、どうちがうの?', '格助詞は、主に体言について、その語が「主語なのか、目的語なのか、場所なのか」という文の中での役割を決めます。副助詞は、いろいろな語について、「〜だけ」「〜まで」「〜さえ」などの意味をそえますが、文の中での役割を決める働きはありません。たとえば「パンを食べる」の「を」は目的語を示す格助詞ですが、「パンだけ食べる」の「だけ」は「限定」という意味をそえる副助詞です。']
    ]
  });

  add('j_h5', {
    secs: [
      { h: 'さらに深く:広い範囲を指す指示語と、指示語+接続語', t: '指示語は、すぐ前の1語や1文を指すだけではありません。説明文では、【前の段落全体】を指す指示語がよく使われ、入試ではそこが問われます。\n①【まとめの指示語】…「このように」「こうした」「このような」は、それまでに挙げた具体例や説明をまとめて指すことが多い語です。例:「レジ袋をやめる人、マイボトルを持つ人、古着を活用する人が増えている。【こうした】動きは…」の「こうした」は、前の3つの例をまとめて指しています。答えるときは、例を全部並べるのではなく、【共通点で一つにまとめる】(「ごみを減らそうとする人々の行動」)ことが求められます。\n②【指示語+接続語】…「そのため」「それに対して」「このことから」「それでも」などは、指示語と接続の働きを同時にもっています。「そのため」なら、「その」が指す内容が【原因】、後ろが【結果】です。指示内容をはっきりさせると、文と文の論理関係が正確に分かります。\n③【指示語が後ろを指す】…「次のような」「こんな話がある」のように、これから述べることを指す場合もあります。\n広い範囲を指す指示語の内容を答えるときの手順は、(1)指示語の直前の段落を読み、(2)その段落の中心となる文を見つけ、(3)具体例は共通点でまとめ、(4)指示語に当てはめて意味が通るかを確かめる、です。指示語の後ろにある語(「こうした【動き】」の「動き」)が、まとめ方のヒントになることも覚えておきましょう。', key: '「このように」「こうした」は前の例をまとめて指す。答えは例を並べるのではなく、共通点で一つにまとめ、指示語の後ろの語に合う形にする。', ex: [{ q: '「駅前の商店街では、空き店舗を使って子ども向けの工作教室が開かれている。また、地元の高校生が店の看板をデザインする取り組みも始まった。さらに、毎月一回、通りを歩行者天国にして市場を開いている。【こうした】試みによって、商店街には少しずつ人が戻ってきた。」\n「こうした試み」とは何か。具体例をまとめて30字以内で答えよう。', hint: '3つの例に共通することは何でしょう。「試み」という語に合うようにまとめます。', steps: ['指示語「こうした」の前にある具体例を確かめる。工作教室、高校生の看板デザイン、歩行者天国の市場の3つ。', '共通点を考える。どれも、商店街に人を呼びこむための新しい活動であり、地域の人(子ども・高校生・住民)が関わっている。', '指示語の後ろの「試み」に合う形にまとめる。「〜する取り組み・活動」の形にする。', '指示語に当てはめて読み、「〜によって、人が戻ってきた」と意味が通るかを確かめる。'], a: '(例)地域の人々が関わり、商店街に人を呼ぶための新しい活動。(27字)', check: '答えを「こうした試み」の部分に入れると、「地域の人々が関わり、商店街に人を呼ぶための新しい活動によって、商店街には少しずつ人が戻ってきた」となり、意味が通ります。' }] },
      { h: '実戦演習:接続語と指示語から文章の論理をたどる', t: '高校入試では、接続語の空らん補充と指示語の内容を、1つの文章の中で組み合わせて問われることがよくあります。戦略は次のとおりです。\n①空らんの前後の文を読み、【指示語があれば、まずその内容を確かめる】。指示内容が分かると、前後の関係(原因と結果、対比など)がはっきりします。\n②関係を「だから」「しかし」などの言葉にしてから、選択肢を見ます。\n③指示語の答えを書くときは、指示語の後ろの語とつながる形で終えます。\n落とし穴は、空らんのすぐ前の1文だけを見て接続語を選ぶことです。段落全体を指す指示語があるときは、段落と段落の関係で考える必要があります。', key: '指示語の内容を先に確かめると、接続語の関係も決まる。指示語と接続語をばらばらに解かないことで差がつく。', ex: [{ q: '次の作例の文章を読んで答えよう。\n「昔の人は、夜になると早く眠り、日の出とともに起きた。明かりが貴重で、夜に活動することが難しかったからだ。( A )、電灯が広まると、人々は夜おそくまで起きていられるようになった。【このこと】は、人々に自由な時間を与えた。( B )、体が本来もっている眠りのリズムを乱すことにもなった。」\n(1)( A )( B )に入る接続語を、ア〜エから選ぼう。ア だから イ ところが ウ たとえば エ その一方で(同じ語は1回しか使えない)\n(2)「このこと」が指す内容を答えよう。', hint: '(1)Aは昔と今の対比、Bは「自由な時間を与えた」と「リズムを乱した」の関係を考えます。', steps: ['(2)を先に考える。「このこと」の直前の文は「電灯が広まると、人々は夜おそくまで起きていられるようになった」。これが指示内容。', '(1)A:前は「昔は夜に活動できなかった」、後ろは「電灯で夜おそくまで起きられるようになった」。予想とちがう変化が起きているので、逆接の「ところが」が合う。「その一方で」は、同じものの二つの面を並べる言い方なので、昔と今の変化を述べるAには合わない。', 'B:前は「自由な時間を与えた」(よい面)、後ろは「眠りのリズムを乱した」(悪い面)。同じ「このこと」がもつ別の面を並べて対比しているので「その一方で」。', '「だから」「たとえば」は、どちらの空らんの前後の関係にも合わないことを確かめる。'], a: '(1)A=イ(ところが) B=エ(その一方で) (2)電灯が広まり、人々が夜おそくまで起きていられるようになったこと。', check: 'B の後ろの文の主語は書かれていませんが、「このこと」が主語として続いていると考えると、「このことは、自由な時間を与えた。その一方で、(このことは)リズムを乱すことにもなった。」と意味が通ります。指示語の内容が、Bの前後の両方の主語になっていることを確かめましょう。' }] }
    ],
    drill: [
      { lv: 2, q: '「風が強く、波も高くなってきた。そのため、船の出発は午後に延期された。」の「そのため」の「その」が指す内容を答え、「そのため」の前後がどんな関係かを答えよう。', a: '「その」が指す内容=風が強く、波も高くなってきたこと。関係=前が原因・理由、後ろが結果(順接)。', exp: '「そのため」は、指示語「その」と「ため」が結びついて、接続語のように使われる言い方です。「その」が指す内容が原因、後ろの内容が結果になります。\n同じように指示語をふくむ接続の言い方には、「それに対して」(対比)、「このことから」(根拠から結論を導く)、「それでも」(逆接)、「そのうえ」(累加)などがあります。\nこれらを読むときは、「その」「この」「それ」が何を指すかを必ず確かめましょう。指示内容があいまいなままだと、「何が原因で何が結果か」を正確に言えなくなります。' },
      { lv: 3, q: '「ある町では、図書館が夜九時まで開くようになった。仕事帰りの人や、部活動のあとの中高生が利用できるようになった。また、静かな勉強の場所がほしい人にも喜ばれている。このように、( )ことで、図書館は多くの人にとって身近な場所になった。」\n( )に入る内容を、本文の言葉を使って15字以内で答えよう。', a: '(例)開館時間を夜九時まで延ばした(14字)', exp: '「このように」は、前に述べた内容をまとめる指示語です。ここでは、図書館が夜九時まで開くようになったことと、その結果、いろいろな人が利用できるようになったことをまとめています。\n( )の後ろに「ことで、図書館は多くの人にとって身近な場所になった」とあるので、( )には【身近な場所になった原因】が入ります。具体的な利用者(仕事帰りの人、中高生など)は結果の例なので、原因にはあたりません。\n「このように」の後ろは、まとめの文であり、筆者の主張に近い内容が来ることが多いです。前の具体例から、原因と結果を整理して読みましょう。' },
      { lv: 3, q: '「次のような話がある。ある村の人々は、川の水が減ると、上流の森の木を切るのをやめた。森が水をたくわえることを、経験から知っていたのだ。」の「次のような話」は、どこからどこまでを指すか。また、この指示語の働きを説明しよう。', a: '指す範囲=「ある村の人々は、川の水が減ると、上流の森の木を切るのをやめた。森が水をたくわえることを、経験から知っていたのだ。」(後ろの2文)。働き=これから具体的な話(例)を述べることを、前もって予告する働き。', exp: '指示語はふつう前の内容を指しますが、「次のような」「以下の」「こんな」などは、【後ろの内容を指す】ことがあります。\n「次のような話がある」は、読み手に「これから例を出します」と予告し、注意を向けさせる働きをしています。説明文では、主張を述べる前に、具体例を予告してから示す書き方がよくあります。\n範囲を答えるときは、話がどこで終わるかに注意します。ここでは2文目の「経験から知っていたのだ」で、村の人々の話が終わっています。その後に筆者の考えが続くことが多いので、例と主張の境目を見きわめることが大切です。' }
    ],
    faq: [
      ['「このように」の後ろは、いつも筆者の主張なの?', 'いつもとはかぎりませんが、主張やまとめが来ることがとても多いです。「このように」は、前の具体例や説明をまとめる言葉なので、その後ろには、例から分かる一般的な考えが書かれやすいからです。ただし、段落の途中の「このように」は、小さなまとめにすぎないこともあります。文章全体の主張かどうかは、最後の段落や、「しかし」の後ろの内容と照らし合わせて確かめましょう。'],
      ['指示語の内容を答えるとき、本文の言葉をそのまま抜き出していいの?', '問題の指示によります。「抜き出しなさい」とあれば、本文の言葉をそのまま、字数どおりに書きます。「説明しなさい」「答えなさい」なら、本文の言葉を使いながら、指示語に当てはめて意味が通るように形を整えます。とくに広い範囲を指す指示語では、具体例を全部並べると字数が足りないので、共通点でまとめる必要があります。どちらの場合も、最後に指示語の部分に答えを入れて読み、意味が通るかを確かめましょう。']
    ]
  });

  add('j_keigo', {
    secs: [
      { h: 'さらに深く:「二重敬語」と「敬語の連結」はどうちがう?', t: '敬語のまちがいとしてよく挙げられるのが【二重敬語】です。二重敬語とは、【一つの語に、同じ種類の敬語を二重に使ったもの】です。例:「おっしゃられる」は、尊敬語「おっしゃる」に、さらに尊敬の「れる」を重ねているので二重敬語です。正しくは「おっしゃる」で十分です。\nところが、一見二重に見えても、まちがいではない言い方があります。\n①【敬語の連結】…「お読みになっていらっしゃる」は、「お読みになる」(尊敬語)と「いらっしゃる」(「いる」の尊敬語)という、【別々の語】がそれぞれ敬語になってつながったものです。一つの語に二重にかかっているのではないので、二重敬語ではありません。「ご案内してさしあげる」なども同じです。\n②【習慣として定着したもの】…「お召し上がりになる」(召し上がる+お〜になる)、「お伺いする」(伺う+お〜する)は、形の上では二重敬語ですが、広く使われてきたため、文化庁の「敬語の指針」でも、習慣として定着していて許容される例として挙げられています。\nつまり、まちがいかどうかを判断するには、(1)一つの語に重ねているのか、別々の語がつながっているのかを見る、(2)習慣として定着した例かどうかを知っておく、の2点が必要です。入試では、定着していない「おっしゃられる」「ご覧になられる」「お越しになられる」などが誤りの例として出ます。', key: '二重敬語は「一つの語」に同じ種類の敬語を重ねたもの。別々の語がつながった「敬語の連結」はまちがいではない。「お召し上がりになる」「お伺いする」は習慣として定着している。', ex: [{ q: '次の文のうち、敬語の使い方として適切でないものを1つ選び、正しく直そう。\nア 先生は、今、本をお読みになっていらっしゃる。 イ お客様が、料理をお召し上がりになる。 ウ 校長先生が、明日の予定をおっしゃられた。', hint: 'それぞれ、敬語が「一つの語」に重なっているのか、「別々の語」についているのかを見ましょう。', steps: ['アは「お読みになる」と「いらっしゃる」の2つの語がそれぞれ尊敬語になってつながった敬語の連結。まちがいではない。', 'イの「お召し上がりになる」は、形の上では二重だが、習慣として定着していると認められている言い方。', 'ウの「おっしゃられた」は、「おっしゃる」という一つの語に、さらに尊敬の「られる」を重ねた二重敬語。', 'ウを「おっしゃった」に直す。'], a: 'ウ。正しくは「校長先生が、明日の予定をおっしゃった。」', check: 'イについて、より簡潔にしたいなら「召し上がる」だけでも正しい敬語です。入試では、「定着しているから許容」と「より適切な形」のどちらが問われているかを、設問の言い方で確かめましょう。' }] },
      { h: '実戦演習:会話の場面で、だれに対する敬語かを判断して直す', t: '入試の敬語問題は、会話文の中で「場面に合わない敬語」を見つけて直す形が多いです。戦略は次のとおりです。\n①会話の【登場人物の関係】(話し手・聞き手・話題の人物、ウチかソトか)を確かめます。\n②傍線部の【動作の主語】を決めます。主語が目上・ソトの人なら尊敬語、自分やウチの人なら謙譲語です。\n③二重敬語や、尊敬語と謙譲語の取りちがえがないかを確かめます。\n落とし穴は、自分の家族や自分の学校の先生について、ソトの人に話す場面です。ソトの人に話すときは、ウチの人の動作には謙譲語を使います。', key: '動作の主語と、その人がウチかソトかを決めてから敬語を選ぶ。ソトの人への会話で、ウチの人の動作を立ててしまう誤りに気づけるかで差がつく。', ex: [{ q: '中学生の山田さんが、職場体験でお世話になった会社に電話をかけた。次の会話の傍線部①〜③のうち、敬語の使い方が適切でないものをすべて選び、正しく直そう。\n山田「もしもし、先週職場体験で①【お世話になられた】、南中学校の山田です。」\n会社の人「ああ、山田さん。こんにちは。」\n山田「担任の佐藤先生も、よろしくと②【申しておりました】。あの、鈴木様は③【いらっしゃいますか】。」', hint: '①の動作の主語はだれでしょう。②の佐藤先生は、会社の人から見てウチの人ですか、ソトの人ですか。', steps: ['①「お世話になる」の主語は山田さん自身。自分の動作に尊敬の「られる」をつけるのは誤り。「お世話になった」が正しい。', '②「言う」の主語は佐藤先生。山田さんにとっては目上だが、電話の相手(会社の人)から見ると、山田さんの学校のウチの人。ソトの人に話すので謙譲語「申す」を使うのが適切。', '③「いる」の主語は会社の鈴木様。ソトの人なので尊敬語「いらっしゃる」が適切。', '適切でないのは①だけ。'], a: '①のみ適切でない。「先週職場体験でお世話になった、南中学校の山田です。」に直す。(②③は適切)', check: '②を「おっしゃっていました」にすると、会社の人の前で自分の学校の先生を立てることになり、ウチ・ソトの使い分けに反します。主語と、聞き手から見た立場の両方で確かめましょう。' }] }
    ],
    drill: [
      { lv: 2, q: '「先生が、私の絵をご覧になられた。」の敬語のまちがいを説明し、正しく直そう。', a: '「ご覧になる」は「見る」の尊敬語であり、さらに尊敬の助動詞「られる」を重ねた二重敬語になっている。正しくは「先生が、私の絵をご覧になった。」', exp: '「ご覧になる」は、それだけで「見る」の尊敬語として完成しています。そこに「られる」を加えると、一つの語に尊敬を二重に重ねることになり、二重敬語になります。\n同じように、「お越しになられる」「お帰りになられる」「おっしゃられる」も二重敬語の例です。\n「〜になられる」という形を見たら、二重敬語ではないかと疑ってみましょう。ただし、「先生が校長になられた」のように、動詞「なる」そのものに尊敬の「られる」がついた場合は、敬語が一つだけなので二重敬語ではありません。' },
      { lv: 3, q: '(店員が客に)「こちらのパンフレットを、ご自由にお持ちしてください。」の敬語のまちがいを説明し、正しく直そう。', a: '「お持ちする」は謙譲語の形(お〜する)なので、客の動作に使うのは誤り。客の動作には尊敬語を使い、「こちらのパンフレットを、ご自由にお持ちください。」(または「お持ちになってください」)と直す。', exp: '「お〜する」は謙譲語、「お〜になる」「お〜ください」は尊敬語の形です。「お」がついているので丁寧に聞こえますが、「お〜する」の形は、自分の動作をへりくだって言うときに使います(例:お荷物をお持ちします)。\nここでパンフレットを持っていくのは客なので、客を高める尊敬語を使います。「お持ちください」は、「お〜ください」という尊敬の依頼の形で、簡潔で自然な言い方です。\n「ご〜する」も謙譲語(ご案内する)、「ご〜になる」「ご〜ください」は尊敬語(ご利用ください)です。「する」がつくかどうかに注目すると、見分けやすくなります。' },
      { lv: 3, q: '次の文は、敬語のまちがいとして指摘されることがある。理由を説明し、より適切な言い方に直そう。\n(会社の受付で客に)「田中様でございますね。こちらで少々お待ちしてください。」', a: '「お待ちする」は謙譲語の形(お〜する)で、客の「待つ」動作に使っているのが誤り。より適切な言い方は「田中様でいらっしゃいますね。こちらで少々お待ちください。」また、「田中様でございますね」の「ございます」は丁寧語だが、相手を直接立てるには尊敬語の「いらっしゃいます」のほうが適切とされる。', exp: 'この問題には、2つのポイントがあります。\n1つめは、「お待ちしてください」の誤りです。「お待ちする」は、自分が相手を待つときの謙譲語です(お待ちしております)。客に待ってもらうときは、尊敬語の「お待ちください」を使います。\n2つめは、「でございます」と「でいらっしゃいます」のちがいです。「ございます」は丁寧語で、聞き手に対するていねいさを表しますが、話題の人物を高める働きはありません。相手の人物そのものについて言うときは、尊敬語「いらっしゃる」を使った「田中様でいらっしゃいますね」のほうが、相手を立てる言い方になります。' }
    ],
    faq: [
      ['「お伺いする」は二重敬語なのに、なぜ使ってもいいの?', '「伺う」はそれだけで謙譲語なので、「お〜する」をつけると形の上では二重になります。しかし、この言い方は長く広く使われてきたため、文化庁の「敬語の指針」では、習慣として定着していて問題がないものの例として挙げられています。言葉のきまりは、理屈だけでなく、実際の使われ方によって決まる面もあるのです。ただし、入試で「より簡潔で適切な形」を問われたら、「伺う」と答えるのが安全です。'],
      ['敬語は、たくさん使うほどていねいになるの?', 'そうとはかぎりません。必要以上に敬語を重ねると、二重敬語になってまちがいになったり、回りくどくて聞き取りにくくなったりします。また、親しい友だちに敬語を使いすぎると、よそよそしい印象を与えることもあります。大切なのは、相手との関係や場面に合った敬語を、正しい形で使うことです。「一つの動作に一つの敬語」を目安にすると、すっきりした、ていねいな言い方になります。']
    ]
  });

  add('j_kobun_m', {
    secs: [
      { h: 'さらに深く:係り結びの「や・か」― 疑問と反語', t: '係り結びで、「ぞ・なむ・こそ」は意味を強める(強調)働きでした。これに対して、【や・か】は、疑問(〜か)と反語(〜か、いや〜ない)の意味を表し、文末は連体形になります。\n①【疑問】…答えが分からないので、本当にたずねている。例:「いづれの山か天に近き」(どの山が天に近いか)。\n②【反語】…「〜だろうか、いや〜ない」と、問いの形で強く打ち消す。例:「誰か知らむ」(だれが知っているだろうか、いや、だれも知らない)。\n疑問か反語かは、【文脈】で決めます。話し手がすでに答えを知っていて、強く言いたいときは反語です。反語の文末は「〜む(〜ん)」などの推量の形になることが多いのも手がかりです。\nもう一つ大事なのが、【結びの省略】です。会話や文章の途中で「〜にや」「〜にか」で文が切れているときは、後ろに「あらむ」「ありけむ」などの言葉が省略されています。たとえば『源氏物語』の冒頭「いづれの御時にか」は、「どの帝の御代であったろうか」という意味で、「にか」の後ろに「ありけむ」が省略されていると考えます。「や」「か」を見たら、結びの語がどこにあるか、または省略されていないかを確かめましょう。\nなお、文末にある「や」「か」は係助詞ではなく、終助詞(疑問・詠嘆)として使われることもあります。係り結びになるのは、文の途中にある場合です。', key: '「や・か」は疑問か反語で、結びは連体形。答えを知っていて強く打ち消すなら反語。「〜にや」「〜にか」の後ろは結びが省略されていることがある。', ex: [{ q: '次の作例の傍線部の意味を、疑問か反語かを判断して現代語訳しよう。\n①「この花の名を、【たれか知る】」と、人に問ひけり。 ②「かかる山里に、【たれか訪ね来む】。」とて、門をとざしけり。', hint: 'それぞれ、話し手が本当に答えを知りたがっているのか、答えを分かっていて言っているのかを考えましょう。', steps: ['①の文脈を確かめる。「と、人に問ひけり」とあり、話し手は花の名を知りたくて、実際に人に質問している。だから疑問。', '①の結び「知る」は、四段活用「知る」の連体形(係助詞「か」の結び)。訳は「だれが知っているか」。', '②の文脈を確かめる。「とて、門をとざしけり」とあり、だれも来ないと思ったから門をとざしている。答え(だれも来ない)を分かって言っているので反語。', '②の結び「む」は推量の助動詞の連体形。反語なので「だれが訪ねて来るだろうか、いや、だれも来ないだろう」と訳す。'], a: '①疑問。(この花の名を)だれが知っているか。 ②反語。(こんな山里に)だれが訪ねて来るだろうか、いや、だれも訪ねて来ないだろう。', check: '②を疑問にすると、「だれが来るのだろう」と思いながら門をとざすことになり、行動と合いません。後ろの行動と矛盾しないかで、疑問と反語を確かめます。' }] },
      { h: '実戦演習:初めて読む古文の小問を、順に解く', t: '高校入試の古文は、教科書で習っていない文章が出されることも多く、注や現代語訳がついています。戦略は次のとおりです。\n①まず【注】と【現代語訳】(ついていれば)に目を通し、だれが出てくるかをつかみます。\n②本文を読み、【会話文】(「 」や「と」「とて」の前)に印をつけます。\n③小問は、仮名遣い→係り結び→主語→内容の順に、知識で解ける問題から片づけます。\n④内容の問題は、本文の該当部分を現代語訳と照らし合わせて答えます。\n落とし穴は、主語が書かれていない文で、前の文の主語をそのまま当てはめてしまうことです。会話の前後では主語が入れかわることが多いので注意しましょう。', key: '知識で解ける小問から先に片づけ、会話文の前後で主語が入れかわることに気づけるかで差がつく。', ex: [{ q: '次の作例の古文を読んで答えよう。\n「今は昔、ある山里に翁ありけり。庭に梅の木を植ゑて、朝夕これを見るをたのしみとしけり。ある年、梅の花いとうるはしく咲きたりければ、隣の人来て、『一枝をたまへ』と言ふ。翁、『花は見るものにこそあれ、折るものかは』と言ひて、与へざりけり。」\n(うるはし=美しい。たまへ=ください。かは=〜だろうか、いや〜ない)\n(1)「植ゑて」を現代仮名遣いに直そう。(2)「一枝をたまへ」と言ったのはだれか。(3)「見るものにこそあれ」の係りの助詞と結びの語を答えよう。(4)翁が枝を与えなかったのはなぜか、説明しよう。', hint: '(3)「こそ」の結びは已然形です。(4)は翁の会話の内容を現代語にしてみましょう。', steps: ['(1)「ゑ」は「え」に直すので「うえて」。', '(2)直前に「隣の人来て」とあるので、「一枝をたまへ」と言ったのは隣の人。翁の言葉ではない。', '(3)係りの助詞は「こそ」。結びの語は「あれ」(ラ変動詞「あり」の已然形)。', '(4)翁の言葉を訳す。「花は見るものであって、折るものだろうか、いや、折るものではない」。「かは」は反語。', '翁は、花は木に咲いているのを眺めて楽しむものであり、枝を折ってしまうものではないと考えたので、与えなかった。'], a: '(1)うえて (2)隣の人 (3)係りの助詞=こそ、結びの語=あれ (4)花は木に咲いているのを見て楽しむものであり、枝を折ってしまうべきものではないと考えたから。', check: '(4)は、翁が「朝夕これを見るをたのしみとしけり」という前の文とも合っているかを確かめます。翁は花を見ることを大切にしている人物なので、答えと矛盾しません。' }] }
    ],
    drill: [
      { lv: 2, q: '作例「いづれの道をか行くべき。」の係りの助詞と、結びの語を答えよう。また、この文を現代語訳しよう。', a: '係りの助詞=か。結びの語=べき(推量・当然の助動詞「べし」の連体形)。訳:どの道を行くのがよいだろうか。', exp: '「か」は疑問・反語の係助詞なので、文末が連体形になります。「べし」の連体形は「べき」です。\n文の初めに「いづれの」(どの)という疑問の語があり、話し手はどの道を行けばよいか分からずにまよっている、と読めるので、ここでは疑問と考えます。\n「べし」には、推量(〜だろう)、意志(〜しよう)、当然(〜べきだ)、適当(〜のがよい)など、いくつもの意味があります。ここでは、どの道が適しているかを考えているので、「〜のがよいだろうか」と訳すと自然です。' },
      { lv: 3, q: '『源氏物語』の冒頭「いづれの御時にか、女御、更衣あまたさぶらひたまひける中に…」の「いづれの御時にか」について、(1)後ろに省略されている語を補い、(2)意味を答えよう。(御時=帝の御代)', a: '(1)「ありけむ」(または「あらむ」)が省略されている。「いづれの御時にか(ありけむ)」。(2)どの帝の御代であったろうか。', exp: '「にか」で文が区切れていますが、係助詞「か」の結びとなる語が見当たりません。このような場合、「に」(断定の助動詞「なり」の連用形)の後ろに「あり」が続き、さらに推量の「む」や過去推量の「けむ」がついた形が省略されていると考えます。\nこの物語は、昔のある帝の時代の話として書き始められているので、過去推量「けむ」を補って「どの帝の御代であったろうか」と訳すのが一般的です。\n「〜にや」「〜にか」の後ろに「あらむ」「ありけむ」が省略される形は、古文でとてもよく出てきます。省略された語を補えると、高校の古文でも役に立ちます。' },
      { lv: 3, q: '作例「月の光は昔に変はらねど、見る人はいづこへか行きにけむ。」の「か」の結びの語を答え、文全体を現代語訳しよう。また、この文から読み取れる話し手の気持ちを説明しよう。', a: '結びの語=けむ(過去推量の助動詞「けむ」の連体形)。訳:月の光は昔と変わらないけれど、(昔いっしょに)見た人はどこへ行ってしまったのだろうか。気持ち:昔と変わらない月を見ながら、かつて共に月を見た人がいなくなってしまったことをさびしく思い、なつかしむ気持ち。', exp: '係助詞「か」の結びは、文末の「けむ」です。「けむ」は四段型に活用し、終止形と連体形が同じ「けむ」の形なので、形を見ただけでは分かりませんが、係り結びのきまりから連体形と判断します。\n「変はらねど」の「ね」は打消の「ず」の已然形、「ど」は逆接の接続助詞です。月の光は「変わらない」のに、人は「変わってしまった(いなくなった)」という対比が、この文の中心です。\n変わらない自然と、変わってしまう人の世を対比するのは、古文や和歌によく見られる表現です。対比に気づくと、話し手の気持ちが読み取りやすくなります。' }
    ],
    faq: [
      ['「ぞ・なむ・こそ」と「や・か」は、なぜ同じ係り結びなのに働きがちがうの?', '係り結びは、文の途中の語に係助詞をつけて、文末の形を変えることで、文全体に特別な気持ちをこめるしくみです。どんな気持ちをこめるかは係助詞によってちがい、「ぞ・なむ・こそ」は強調、「や・か」は疑問・反語を表します。文末の形も、「こそ」だけが已然形で、残りは連体形です。働きのちがいと、結びの形のちがいの両方をセットで覚えておきましょう。'],
      ['反語の訳で、「いや〜ない」まで書かないといけないの?', '入試の現代語訳では、反語であることがはっきり分かるように、「〜だろうか、いや〜ない」と書くのが安全です。「〜だろうか」だけだと、疑問と区別がつかないからです。ただし、文脈によっては「〜するはずがない」「決して〜ない」と、打ち消しの意味だけで訳すこともあります。どちらの場合も、反語は「強い打ち消し」を表すことを、答えにきちんと表すことが大切です。']
    ]
  });

  add('j_kanbun_m', {
    secs: [
      { h: 'さらに深く:返り点の組み合わせ ― 「レ」と「二」、「上レ」', t: '返り点は、1つの文の中で組み合わせて使われます。とくに、レ点と一・二点が近くにあるとき、読む順番をまちがえやすくなります。ここでは2つの組み合わせを見ておきましょう。\n①【レ点の字の下に、二点がついている】…例:陶淵明「桃花源記」の「欲レ窮二其林一」(其の林を窮めんと欲す)。\n読み方:「欲」にはレ点があるので、すぐ下の「窮」を先に読みたい。ところが「窮」には二点があるので、さらに一点の「林」まで先に読む。順番は「其→林→窮→欲」です。つまり、【レ点の返り先が二点なら、一点まで読んでから返る】と考えます。\n②【上レ点(一レ点)】…1つの字に、上点(または一点)とレ点がいっしょについた形です。例:劉備の言葉「勿下以二悪小一而為上レ之」(悪小なるを以て之を為すこと勿かれ)。\n読み方:「勿」(下)と「以」(二)は飛ばし、「悪→小」(一)を読んで「以」(二)に返る。「而」は置き字なので読まない。次の「為」には「上レ」がついているので、まず【レ点が先に働いて】すぐ下の「之」を読み、次に「為」、そして上点の働きで「勿」(下)に返ります。順番は「悪→小→以→之→為→勿」です。\n組み合わせを読むときのコツは、【返り点のない字は上から順に読み、返り点のある字は「先に読むべき字」を読み終えてから読む】という基本に、いつも立ちもどることです。読む順に番号をふってから書き下し文を作ると、まちがいが減ります。', key: 'レ点の返り先に二点があれば、一点まで読んでから返る。「上レ」「一レ」は、まずレ点で下の1字を読み、次に上点・一点として働く。', ex: [{ q: '「勿下以二悪小一而為上レ之」の漢字を、読む順に並べよう。また、書き下し文にして、意味を答えよう。(而は置き字。勿=なかれ、〜するな)', hint: '返り点のない字から順に読み、「上レ」は、まずレ点として働くことに注意します。', steps: ['「勿」には下点、「以」には二点があるので、どちらも飛ばす。', '「悪」は返り点がないので読む(1)。「小」には一点があるので読み(2)、二点の「以」に返る(3)。', '「而」は置き字なので読まない。「為」には「上レ」がついている。まずレ点が働くので、すぐ下の「之」を先に読み(4)、「為」に返る(5)。', '「為」の上点が働いて、下点の「勿」に返る(6)。', '書き下し文は「悪小なるを以て之を為すこと勿かれ」。意味は「悪いことが小さいからといって、それをしてはならない」。'], a: '読む順:悪→小→以→之→為→勿。書き下し文:悪小なるを以て之を為すこと勿かれ。意味:悪いことが小さいからといって、それを行ってはならない。', check: '読んだ字が6字(而を除いた全部)そろっているか、同じ字を2回読んでいないかを確かめます。「勿かれ」は禁止を表し、文の最後に読むことも確認しましょう。' }] },
      { h: '実戦演習:書き下し文から返り点をつける', t: '高校入試では、書き下し文を示して、白文に返り点をつけさせる問題が出ます。戦略は次のとおりです。\n①書き下し文の言葉が、白文のどの字にあたるかを確かめ、【読む順番の番号】を白文の字にふります。\n②番号が「1つ前の字に返る」ところにはレ点、「2字以上はなれて返る」ところには一・二点をつけます。\n③一・二点をはさんで、さらに返るところがあれば上・下点を使います。\n④最後に、返り点のとおりに読んで、書き下し文と一致するかを確かめます。\n落とし穴は、ひらがなで書かれた送り仮名(「を」「に」など)を、漢字と取りちがえることです。書き下し文の中の漢字だけを数えて番号をつけましょう。', key: '白文の字に「読む順番の番号」をふってから返り点を決める。最後に返り点どおりに読み直して確かめるかどうかで差がつく。', ex: [{ q: '次の書き下し文を参考にして、白文に返り点をつけよう。\n(1)書き下し文「山に登る者有り。」 白文「有登山者」\n(2)書き下し文「千里の馬を買ふ者有り。」 白文「有買千里馬者」', hint: '(1)は一・二点とレ点、(2)は上・下点が必要です。', steps: ['(1)書き下し文の順に番号をふる。山(1)→登(2)→者(3)→有(4)。白文の並びは「有(4) 登(2) 山(1) 者(3)」。', '「登」は1つ下の「山」から返るのでレ点。「有」は「者」から2字以上はなれて返るので、「者」に一点、「有」に二点。→「有二登レ山者一」。', '(2)番号をふる。千(1)→里(2)→馬(3)→買(4)→者(5)→有(6)。白文は「有(6) 買(4) 千(1) 里(2) 馬(3) 者(5)」。', '「買」は「馬」から2字以上はなれて返るので、「馬」に一点、「買」に二点。さらに「有」は、一・二点をはさんで「者」から返るので、「者」に上点、「有」に下点。→「有下買二千里馬一者上」。', 'それぞれ、返り点どおりに読んで、書き下し文と一致することを確かめる。'], a: '(1)有二登レ山者一 (2)有下買二千里馬一者上', check: '(2)で「有」にも一・二点を使おうとすると、「買」の一・二点と重なってしまいます。一・二点をはさんでさらに返るときは上・下点を使う、というきまりを確かめましょう。' }] }
    ],
    drill: [
      { lv: 2, q: '「欲レ窮二其林一」の漢字を読む順に並べ、書き下し文にしよう。(欲=〜しようと思う。窮=きわめる、行きつくところまで行く)', a: '読む順:其→林→窮→欲。書き下し文:其の林を窮めんと欲す。', exp: '「欲」にはレ点があるので、すぐ下の「窮」を先に読みたいところです。しかし、「窮」には二点がついているので、さらに一点のついた「林」まで先に読みます。\nそこで、返り点のない「其」を読み、一点の「林」を読んで、二点の「窮」に返り、最後にレ点の「欲」に返ります。\n「欲」は「〜せんと欲す」と読み、「〜しようと思う」という意味になります。そのため、「窮」に推量・意志の「ん(む)」をつけて「窮めんと欲す」と読みます。この文は、漁師が桃の花の林の終わりまで行ってみようとした場面の一節です。' },
      { lv: 3, q: '『論語』の「己所レ不レ欲、勿レ施二於人一」を書き下し文にし、意味を答えよう。(施=ほどこす、行う。於は置き字)', a: '書き下し文:己の欲せざる所は、人に施すこと勿かれ。意味:自分がしてほしくないことは、人にしてはならない。', exp: '前半の「己所レ不レ欲」は、「己」を読んだ後、「所」と「不」にレ点があるので、「欲」→「不」→「所」の順に返ります。「己の欲せざる所」=「自分が望まないこと」となります。レ点が2つ続くときは、下から順に1字ずつ返ります。\n後半の「勿レ施二於人一」は、「於」が置き字なので読まず、「人」(一)→「施」(二)→「勿」(レ)の順です。「施」は一・二点で「人」から返り、その「施」にレ点の「勿」が返ります。ここにも、レ点の返り先が二点という組み合わせが使われています。「於」は読みませんが、「人に」と送り仮名「に」で働きを表します。' },
      { lv: 3, q: '次の書き下し文を参考にして、白文「不知人之不善」に返り点をつけよう。書き下し文「人の不善を知らず。」', a: '不レ知二人之不善一', exp: 'まず、書き下し文の順に番号をふります。人(1)→之(2)→不善(3)→知(4)→不(5)。ここで「不善」は「ふぜん」と音読みする一つの熟語なので、まとめて扱います。\n白文の並びは「不(5) 知(4) 人(1) 之(2) 不善(3)」です。「知」は「不善」から2字以上はなれて返るので、「不善」の下の字(善)に一点、「知」に二点をつけます。「不」はすぐ下の「知」から返るのでレ点です。\nこの文には「不」が2つありますが、1つめは「ず」と読む否定の字、2つめは熟語「不善」の一部です。同じ字でも働きがちがうことに注意しましょう。熟語の2字は、ハイフンでつないで1語として扱うこともあります。' }
    ],
    faq: [
      ['「上レ」や「一レ」は、なぜレ点が先に働くの?', 'レ点は「すぐ下の1字を先に読んでから返る」という、いちばん近い距離の返り点だからです。「為上レ之」なら、「為」を読むには、まずすぐ下の「之」を読む必要があります。「之」を読んで「為」に返ったあと、今度は「為」についている上点が働いて、下点の字へ返ります。近い返り(レ点)を先に、遠い返り(上点・一点)を後に処理すると覚えておけば、迷わずに読めます。'],
      ['返り点をつける問題で、答えが2通り考えられることはある?', '基本的には、1つの読み方に対して返り点のつけ方は1通りに決まるようにきまりが作られています。たとえば、1字だけ返るときは一・二点ではなくレ点を使う、一・二点をはさんで返るときは上・下点を使う、などです。答えが2通りに見えるときは、レ点で済むところに一・二点を使っていないか、返る距離を正しく数えているかを見直しましょう。熟語は1語として扱うことにも注意します。']
    ]
  });

  add('j_shiika', {
    secs: [
      { h: 'さらに深く:俳句の「取り合わせ」― 2つのものがひびき合う', t: '俳句はわずか17音しかないので、多くのことを説明することはできません。そこで俳人たちがよく使ってきたのが【取り合わせ】という方法です。取り合わせとは、【季語と、それとは直接関係のない別のもの】を1句の中に並べ、2つがひびき合って生まれる気分を読者に感じとらせる方法です。\nたとえば松尾芭蕉の「荒海や佐渡によこたふ天河」では、「荒海」と「天河(天の川)」という2つの大きな景色が並べられています。荒れた暗い海と、その上空にかかる静かな天の川。2つは、ふつうは一緒に語られないものですが、並べられることで、雄大さとさびしさが重なった、広い夜の世界が立ち上がります。切れ字「や」が、2つのものの間に【間(ま)】をつくり、読者に「この2つはどうつながるのか」と考えさせる働きをしています。\nこれに対して、1つの題材だけを集中してえがく作り方を【一物仕立て】といいます。「〜の〜が〜している」と、1つの景色を細かく見つめる句です。\n取り合わせの句を鑑賞するときは、次の手順で考えます。\n①切れ字や句切れで、句を2つの部分に分ける。\n②それぞれの部分が表すもの(季語の情景/もう一方のもの)を確かめる。\n③2つに共通する気分(静けさ、なつかしさ、はかなさ など)を言葉にする。\n共通点が見つかると、作者がなぜその2つを並べたのかが見えてきます。', key: '取り合わせは、季語と別のものを並べ、2つのひびき合いで気分を伝える方法。切れ字で分け、2つに共通する気分を言葉にして鑑賞する。', ex: [{ q: '次の俳句(作例)について答えよう。\n「風鈴や祖母の手紙の太き文字」\n(1)季語と季節、切れ字を答えよう。(2)この句は、どんな2つのものを取り合わせているか。(3)2つのものに共通する気分を説明しよう。', hint: '切れ字の前と後ろで、句を2つに分けてみましょう。', steps: ['(1)季語は「風鈴」で、季節は夏。切れ字は「や」。', '(2)切れ字「や」で分けると、前半は「風鈴」、後半は「祖母の手紙の太き文字」。風鈴の音と、祖母からの手紙の文字が取り合わせられている。', '(3)風鈴の音は、すずしくすんだ、どこかなつかしい響き。祖母の太い文字からは、祖母の力強さや、あたたかい人がらが感じられる。', '2つに共通するのは、夏の日のおだやかさの中で、離れて暮らす祖母を思うなつかしく温かい気分。風鈴の音が聞こえる部屋で手紙を読む情景が浮かぶ。'], a: '(1)季語=風鈴、季節=夏、切れ字=や (2)風鈴(の音)と、祖母からの手紙の太い文字。(3)夏の部屋に響く風鈴のすずしくなつかしい音と、祖母の力強くあたたかい文字がひびき合い、離れて暮らす祖母をなつかしく思う気分が伝わる。', check: '鑑賞では、2つのものの「つながり」が本文から無理なく説明できるかを確かめます。「祖母は風鈴を作る人だ」のように、句に書かれていない事実を作り出していないかに注意しましょう。' }] },
      { h: '実戦演習:鑑賞文の空らんを、作品の言葉から埋める', t: '高校入試の詩歌の問題では、作品の後に生徒の鑑賞文や話し合いがあり、空らんを埋める問題が多く出ます。戦略は次のとおりです。\n①鑑賞文を先に読み、空らんの前後で【何を説明しようとしているか】(情景・心情・技法・季語)を確かめます。\n②作品にもどり、それに対応する言葉を探します。抜き出しなら、字数に合う部分を正確に写します。\n③自分の言葉で書く空らんなら、作品の言葉を根拠に、鑑賞文の流れにつながる形で書きます。\n落とし穴は、作品を自分なりに想像しすぎて、作品にない情景を書いてしまうことです。答えの根拠は、いつも作品の言葉にあります。', key: '鑑賞文の空らんは「何を説明する部分か」を先に確かめる。答えの根拠を作品の言葉に求められるかで差がつく。', ex: [{ q: '次の俳句(作例)と、それについての鑑賞文を読んで答えよう。\n俳句「卒業歌廊下でひとり聞いており」\n鑑賞文「この句の季語は『( ① )』で、季節は春である。体育館から聞こえてくる歌を、作者は『( ② )』で、しかも『ひとり』で聞いている。にぎやかな式の場から少し離れた場所にいることで、( ③ )が感じられる。」\n(1)①②に入る言葉を、俳句から抜き出そう。(2)③に入る内容を、15字程度で考えて書こう。', hint: '③は、「ひとり」「廊下」という言葉から、作者の気持ちを考えます。', steps: ['(1)①季節が春とあるので、季語は「卒業歌」(卒業は春の季語)。', '②作者が歌を聞いている場所は「廊下」。鑑賞文の「場所にいる」という流れとも合う。', '(2)③は、式の場から離れて「ひとり」で歌を聞く作者の気持ち。にぎやかさと対比される、しんみりとした感情が入る。', '卒業というできごとから、別れのさびしさや、過ぎた日々を思う気持ちが考えられる。「〜が感じられる」につながるよう、名詞で終える。'], a: '(1)①卒業歌 ②廊下 (2)③(例)別れを前にした静かなさびしさ', check: '③に「卒業できてうれしい気持ち」と書くと、「ひとり」「離れた場所」という作品の言葉とつながりません。鑑賞文の「にぎやかな式の場から少し離れた」という対比にも合う内容かで確かめます。' }] }
    ],
    drill: [
      { lv: 2, q: '松尾芭蕉の俳句「荒海や佐渡によこたふ天河」の季語と季節、切れ字を答えよう。また、「天河」は今の季節感とずれやすいが、それはなぜかも説明しよう。', a: '季語=天河(天の川)、季節=秋、切れ字=や。今の感覚では天の川は七夕(七月)の夏のものと思いやすいが、俳句の季語は旧暦にもとづいており、旧暦の七月は秋にあたるから。', exp: '天の川は、夏の夜空でも見られますが、季語としては秋に分類されます。俳句の季節は旧暦(昔の暦)をもとに決められていて、旧暦では七月・八月・九月が秋だったからです。七夕(旧暦七月七日)も、季語では秋になります。\n「よこたふ」は「横たわる」の意味で、天の川が佐渡島の方向に横たわるように見えている情景です。\n「荒海」と「天の川」という、2つの大きな景色を取り合わせた句として知られています。季語の季節を答える問題では、今の感覚ではなく、旧暦の季節で考えるように気をつけましょう。' },
      { lv: 3, q: '次の2つの俳句(作例)のうち、取り合わせで作られているのはどちらか。理由も説明しよう。\nA「朝顔のつるがのびゆく窓の外」 B「朝顔や今日から一人で行く学校」', a: 'B。Bは切れ字「や」で句が切れ、季語「朝顔」と、それとは直接関係のない「今日から一人で行く学校」という別の題材を並べているから。Aは「朝顔のつる」という1つの題材だけを見つめてえがいている一物仕立てである。', exp: 'Aは、朝顔のつるが窓の外にのびていく様子だけをえがいています。題材が1つにしぼられているので、一物仕立ての句です。\nBは、「朝顔や」と切れ字で切ったあと、「今日から一人で行く学校」という、朝顔とは関係のない出来事を並べています。朝の花である朝顔のすがすがしさと、一人で学校へ行くようになった子どもの少し緊張した新しい一歩が、ひびき合います。\n取り合わせかどうかを見分けるには、①切れ字などで句が2つに分かれているか、②2つの部分の題材が直接つながっていないか、を確かめます。' },
      { lv: 3, q: '取り合わせの句では、2つのものが「近すぎても遠すぎてもよくない」と言われることがある。それはなぜか。例を挙げて説明しよう。', a: '2つのものが近すぎる(意味がほとんど同じ)と、ひびき合いが生まれず、説明的になってしまう。遠すぎる(つながりが感じられない)と、読者が2つを結びつけられず、気分が伝わらない。例:「雪や白くつもる冬の朝」は、雪・白い・冬が同じことのくり返しで近すぎる。一方、まったく関係のない2つを並べただけでは、何を伝えたいのか分からない。', exp: '取り合わせの魅力は、2つのものの間にある「すき間」を、読者が想像でうめるところにあります。\n近すぎる例では、「雪」と「冬の朝」「白く」が同じイメージのくり返しになっていて、読者が想像する余地がありません。17音しかない俳句では、同じ意味の言葉を重ねるのはもったいないことでもあります。\n反対に、2つのものに共通する気分がまったく見つからないと、読者はとまどってしまいます。\n鑑賞するときも、この「ちょうどよい距離」を意識して、作者がなぜその2つを選んだのかを考えると、句の味わいが深まります。' }
    ],
    faq: [
      ['取り合わせと一物仕立ては、どちらがすぐれているの?', 'どちらがすぐれているということはありません。取り合わせは、2つのもののひびき合いで、広がりのある気分を伝えるのに向いています。一物仕立ては、1つのものを深く見つめ、細かな発見を伝えるのに向いています。作者は、伝えたいことに合わせて作り方を選んでいます。鑑賞するときは、どちらの作り方かを見分けたうえで、その作り方がどんな効果を生んでいるかを考えると、作品の理解が深まります。'],
      ['俳句の鑑賞で、自分の想像を書いてもいいの?', '作品の言葉にもとづいた想像なら、書いてかまいません。俳句は短いので、読者の想像で情景をおぎなって味わうものです。ただし、入試の鑑賞問題では、作品の言葉と結びつかない想像は根拠がないと判断されます。「〜という言葉から、〜が想像できる」のように、どの言葉から想像したのかを示すと、説得力のある鑑賞になります。作品にない人物や出来事を作り出さないように注意しましょう。']
    ]
  });

  add('j_dokkai', {
    secs: [
      { h: 'さらに深く:筆者の「問い」と「答え」を対応させて読む', t: '説明文や論説文の多くは、筆者が【問い】を立て、それに【答え】ていく形で書かれています。この問いと答えの対応をつかむと、文章全体の骨組みが一気に見えてきます。\n①【問いの形】…「〜だろうか」「なぜ〜のか」「〜とは何か」などの文は、筆者が読者に投げかける【問題提起】です。序論(はじめの段落)に置かれることが多いです。\n②【答えの位置】…問いの答えは、本論の最後や結論の段落に書かれることが多いです。「〜からである」「〜のだ」「つまり〜」などの形で示されます。\n③【問いの種類】…「なぜ〜か」なら答えは理由、「〜とは何か」なら答えは定義・説明、「〜べきか」なら答えは筆者の主張です。問いの種類が分かれば、答えの形も予想できます。\nたとえば、文章が「なぜ、渡り鳥は迷わずに遠くまで飛べるのだろうか」で始まれば、文章のどこかに「〜を手がかりにしているからである」という理由が書かれているはずです。途中の段落は、その答えにたどりつくための観察や実験の説明だと分かります。\n注意したいのは、【見せかけの問い】です。「本当にそうだろうか」のように、一般的な考えに疑いを向ける問いは、反語に近く、「そうではない」という筆者の主張を予告しています。問いを見つけたら、本当に答えを探す問いなのか、反対の考えを示す問いなのかを見きわめましょう。', key: '「〜だろうか」の問いを見つけたら、その答えがどこにあるかを探す。問いの種類(理由・定義・主張)から答えの形を予想できる。', ex: [{ q: '「①なぜ、日本の家には、玄関でくつをぬぐ習慣があるのだろうか。②日本は雨が多く、土地も湿っている。③外を歩いたくつには、どろや湿気がつきやすい。④また、昔の日本の家では、床に直接座ったり、ふとんをしいて寝たりしてきた。⑤床をきれいに保つことは、生活そのものを守ることだったのである。⑥くつをぬぐ習慣は、こうした気候と暮らし方から生まれたのだ。」\n(1)問題提起の文はどれか。番号で答えよう。(2)その答えにあたる文はどれか。番号で答え、答えの内容を簡潔に説明しよう。', hint: '①の問いは「なぜ」なので、答えは「理由」になります。', steps: ['(1)「〜のだろうか」の形をした①が問題提起。「なぜ」で始まるので、答えは理由になると予想する。', '②〜⑤は、理由を組み立てる材料。②③は気候(雨・湿気)、④⑤は暮らし方(床に座る・寝る)。', '(2)⑥の「こうした気候と暮らし方から生まれたのだ」が、問いへの答え。「こうした」が②〜⑤をまとめている。', '答えの内容を簡潔にまとめる。雨が多く湿った気候でくつが汚れやすいうえに、床に座ったり寝たりする暮らしでは床をきれいに保つ必要があったから。'], a: '(1)① (2)⑥。雨が多く湿った気候のためくつが汚れやすく、また床に直接座ったり寝たりする暮らしでは床を清潔に保つ必要があったので、くつをぬぐ習慣が生まれたということ。', check: '①の「なぜ〜のか」に、⑥の内容を「〜からである」の形で当てはめて、問いと答えがきちんと対応するかを確かめます。' }] },
      { h: '実戦演習:問いと答えの対応から、要旨と理由を書く', t: '高校入試の説明文では、文章全体の要旨や、筆者の考えの理由を書かせる記述問題が出ます。戦略は次のとおりです。\n①まず【問題提起の文】を探し、何が問われているかをつかみます。\n②その答えにあたる部分を探し、答えに必要な【材料(理由・具体例)】が、どの段落にあるかを確かめます。\n③記述では、具体例は一般的な言葉に置きかえ、「問い→答え」が一続きになるようにまとめます。\n落とし穴は、具体例をそのまま答えに入れて字数が足りなくなることです。具体例は、「何を示すための例か」を一言にしてから使いましょう。', key: '問題提起と答えを対応させ、具体例を一般的な言葉に言いかえられるかで差がつく。', ex: [{ q: '次の作例の文章を読んで答えよう。\n「①私たちは、分からない言葉があると、すぐにスマートフォンで調べる。②では、紙の辞書を引くことには、もう意味がないのだろうか。③紙の辞書でひとつの言葉を探していると、その前後にある、知らなかった言葉が自然と目に入ってくる。④調べるつもりのなかった言葉に出会い、思わず読みふけってしまうこともある。⑤検索は、知りたい答えにまっすぐたどりつくための道具である。⑥それに対して紙の辞書は、寄り道をしながら、言葉の世界を広げてくれる道具なのだ。」\n筆者は、紙の辞書を引くことにはどんな意味があると考えているか。検索とのちがいがわかるように、50字以内で説明しよう。', hint: '②の問いに対する答えが、⑥にあります。⑤との対比に注目しましょう。', steps: ['問題提起を確かめる。②「紙の辞書を引くことには、もう意味がないのだろうか」。反語に近い問いで、「意味はある」という主張を予告している。', '答えを探す。⑥「紙の辞書は、寄り道をしながら、言葉の世界を広げてくれる道具なのだ」。', '検索とのちがいを確かめる。⑤「検索は、知りたい答えにまっすぐたどりつくための道具」と対比されている。', '③④の具体例は、「探している言葉の前後で、知らなかった言葉に偶然出会うこと」を示している。これを「思いがけない言葉との出会い」とまとめる。', '「検索は〜だが、紙の辞書は〜」の形で、50字以内にまとめる。'], a: '(例)答えにまっすぐたどりつく検索とちがい、思いがけない言葉に出会いながら言葉の世界を広げられること。(48字)', check: '答えに、検索の特ちょう(まっすぐたどりつく)と、紙の辞書の特ちょう(寄り道・思いがけない出会い・言葉の世界が広がる)の両方が入っているか、50字以内に収まっているかを確かめます。' }] }
    ],
    drill: [
      { lv: 2, q: '説明文で、「〜とは、いったい何だろうか。」という問題提起があった。この問いの答えは、どのような形で書かれることが多いか。', a: '「〜とは、…のことである」「〜とは、…である」のように、その言葉の意味や性質を説明する(定義する)形で書かれることが多い。', exp: '問いの種類によって、答えの形は予想できます。\n「なぜ〜か」と理由を問う問いには、「〜からである」「〜ためである」と理由で答えます。「〜とは何か」と内容を問う問いには、「〜とは、…のことである」と定義や説明で答えます。「〜べきだろうか」と判断を問う問いには、「〜べきだ」「〜べきではない」と筆者の主張で答えます。\n答えの形を先に予想しておくと、長い文章の中でも、答えにあたる文を見つけやすくなります。文末の形に注目する習慣をつけましょう。' },
      { lv: 3, q: '「①私たちは、雑草をじゃまなものと考えがちだ。②しかし、雑草は本当に役に立たないのだろうか。③雑草の根は、土の中に細かいすき間を作り、水や空気を通しやすくする。④また、地面をおおうことで、雨で土が流されるのを防いでいる。」\n②の問いは、どのような働きをしているか。説明しよう。', a: '「雑草は役に立たない」という一般的な考え(①)に疑いを向け、「雑草には役に立つ面がある」という筆者の主張を予告する働きをしている。', exp: '②の問いは、答えを知らないから聞いているのではなく、①の一般的な考えに疑問を投げかけることで、「実はそうではない」という主張を読者に予告しています。このような問いは、反語に近い働きをします。\n「しかし」という逆接の接続語の後にあることも、①の考えを否定する方向へ話を進める合図です。\n③④は、雑草が役に立つ具体的な理由(土に水や空気を通す、土が流されるのを防ぐ)を示しています。問いの働きを見ぬくと、その後の段落が何のために書かれているかも分かり、文章全体の流れをつかみやすくなります。' },
      { lv: 3, q: '1つの文章の中に、問題提起が2つあることがある。そのとき、文章の構成としてどのような形が考えられるか。例を挙げて説明しよう。', a: '(例)大きな問い(「なぜ〜か」)を最初に立て、その答えを考えるために、途中でもう一つの小さな問い(「では、〜はどうか」)を立てる形。例:「なぜ人は朝に眠いのか」という大きな問いに答えるために、途中で「では、眠りのリズムは何によって決まるのか」という小さな問いを立て、それに答えたうえで、最初の問いの答えにつなげる。', exp: '長い説明文では、大きな問いにいきなり答えるのが難しいため、途中で小さな問いを立てて、一歩ずつ答えに近づいていく構成がよく見られます。「では」「それでは」は、新しい問いを立てるときの合図になることが多い接続語です。\nこのような文章を読むときは、それぞれの問いと答えを対応させてメモし、小さな答えが大きな答えにどうつながっているかを確かめます。\n要旨をまとめるときは、大きな問いとその答えを中心に書き、小さな問いは、答えにたどりつくための過程としてあつかうと、まとまりのある要旨になります。' }
    ],
    faq: [
      ['問題提起がない文章は、どうやって読めばいいの?', '問題提起がはっきり書かれていない文章でも、筆者は何かの問いに答えるつもりで書いています。その場合は、文章の最後の結論や、「つまり」「このように」の後の文を読み、「この文は、どんな問いへの答えだろう」と逆に考えてみましょう。たとえば結論が「森は水をたくわえる働きをもつ」なら、隠れた問いは「森にはどんな働きがあるか」です。隠れた問いを自分で立てると、文章の骨組みが見えてきます。'],
      ['「〜だろうか」の文は、全部問題提起なの?', '全部ではありません。文章のはじめで話題を示す問いは問題提起ですが、文章の途中や終わりにある「〜だろうか」は、読者に考えさせるための呼びかけや、反語に近い強調であることもあります。たとえば結論の段落の「私たちは、このままでよいのだろうか」は、「このままではいけない」という主張を強めています。問いの位置と、その後に何が書かれているかを確かめて、働きを判断しましょう。']
    ]
  });

  add('jx_jh2', {
    secs: [
      { h: 'さらに深く:呼応の副詞 ― 文末の形を予告する言葉', t: '副詞の中には、【後ろに決まった言い方がくることを予告する】ものがあります。これを【呼応の副詞】(陳述の副詞・叙述の副詞)といいます。入試では、文法問題としても、読解や作文の「文のねじれ」の問題としても出されます。\n主な呼応の副詞と、後ろにくる形は次のとおりです。\n・【打ち消し】…決して・少しも・全然・とうてい → 〜ない。例:決して忘れない。\n・【推量】…おそらく・たぶん・さぞ → 〜だろう。例:おそらく雨が降るだろう。\n・【打ち消しの推量】…まさか・よもや → 〜ないだろう・〜まい。例:まさか負けないだろう。\n・【疑問・反語】…なぜ・どうして → 〜か。例:なぜ遅れたのか。\n・【仮定】…もし・たとえ・万一 → 〜なら・〜ても。例:たとえ雨が降っても行く。\n・【たとえ(比喩)】…まるで・あたかも → 〜ようだ。例:まるで夢のようだ。\n・【願望・依頼】…どうか・ぜひ → 〜ください・〜たい。例:どうか許してください。\nこれらを知っていると、2つのことに役立ちます。1つは、【文の誤りを見つける】ことです。「私は決してあきらめる。」は、「決して」と「〜ない」が呼応していないので誤りです。もう1つは、【読解で文の意味を先読みする】ことです。「たとえ」と出てきたら、後ろに「〜ても」が来て、逆接の内容が続くと予想できます。\n「全然」は、話し言葉では「全然大丈夫」のように肯定でも使われますが、入試や作文では、「全然〜ない」と打ち消しで使うのが安全です。', key: '呼応の副詞は後ろの形を予告する。「決して〜ない」「たとえ〜ても」「まるで〜ようだ」のセットを知ると、文のねじれの発見と先読みに使える。', ex: [{ q: '次の文の誤りを、呼応の副詞に注目して直そう。\n①たとえ明日が雨なら、試合は行われる。 ②まるで春が来たので、暖かい日だった。 ③このことは、少しも知っている。', hint: 'それぞれの副詞が、後ろにどんな形を求めているかを考えます。', steps: ['①「たとえ」は「〜ても」と呼応する仮定(逆接)の副詞。「雨なら」では呼応しない。また「雨でも試合が行われる」という意味なので、「たとえ明日が雨でも」に直す。', '②「まるで」は「〜ようだ」と呼応するたとえの副詞。「来たので」では呼応しない。「まるで春が来たような、暖かい日だった」に直す。', '③「少しも」は「〜ない」と呼応する打ち消しの副詞。「知っている」では呼応しない。意味から「少しも知らない」に直す。', '直した文を読み、意味が自然に通るかを確かめる。'], a: '①たとえ明日が雨でも、試合は行われる。 ②まるで春が来たような、暖かい日だった。 ③このことは、少しも知らない。', check: '③を「よく知っている」と副詞のほうを直すこともできます。どちらを直すかは、文の意味から判断します。入試で「呼応の副詞に注目して直せ」とあれば、副詞に合わせて文末を直すのが基本です。' }] },
      { h: '実戦演習:文法知識を読解に生かす融合問題', t: '高校入試では、1つの文章の中で、文法・語句・読解をまとめて問う融合問題が出ます。戦略は次のとおりです。\n①文法の小問(品詞・呼応・敬語など)は、【傍線部をふくむ一文】だけで解けることが多いので、先に片づけます。\n②読解の小問は、文法の答えを手がかりにすることがあります。たとえば、呼応の副詞「決して」があれば、筆者の強い否定の気持ちが読みとれます。\n③記述では、文法的に正しい文(主語と述語、呼応)で書けているかを最後に確かめます。\n落とし穴は、自分の記述の中で呼応を誤ることです。「筆者は決して〜とは考えている」のような誤りは、減点の対象になります。', key: '文法の小問は一文で解き、その知識を読解の根拠にも使う。自分の記述の呼応のねじれを見直せるかで差がつく。', ex: [{ q: '次の作例の文章を読んで答えよう。\n「人は、失敗をおそれるあまり、新しいことに挑戦しなくなることがある。しかし、失敗は【決して】むだなものではない。【もし】一度も失敗しなければ、自分のやり方のどこに問題があるのかを知る機会もないだろう。失敗は、次にどうすればよいかを教えてくれる先生のようなものなのだ。」\n(1)「決して」「もし」と呼応している部分を、それぞれ抜き出そう。(2)「先生のようなもの」で使われている表現技法の名前を答えよう。(3)筆者は、失敗をどのようなものだと考えているか。「機会」という言葉を使って40字以内で説明しよう。', hint: '(3)は、「もし〜だろう」の文を、肯定の形に言いかえてみましょう。', steps: ['(1)「決して」は打ち消しと呼応するので「(むだなもの)ではない」。「もし」は仮定と呼応するので「(失敗し)なければ」。', '(2)「〜のような」を使って、失敗を先生にたとえているので直喩(明喩)。', '(3)「もし一度も失敗しなければ、問題を知る機会もない」を裏返すと、「失敗すると、自分のやり方の問題を知る機会が得られる」となる。', 'さらに「次にどうすればよいかを教えてくれる」という最後の文の内容を加え、「機会」を使ってまとめる。'], a: '(1)「決して」=ではない、「もし」=なければ (2)直喩(明喩) (3)(例)自分のやり方の問題点を知る機会となり、次にどうすればよいかを教えてくれるもの。(39字)', check: '(3)は、仮定の文「もし〜なければ、〜ない」を裏返して読むことで、筆者の主張(失敗には価値がある)が見えてきます。答えの文が「〜もの」で終わり、問いの「どのようなもの」に対応しているかも確かめましょう。' }] }
    ],
    drill: [
      { lv: 2, q: '次の( )に入る言葉を、下から選んで答えよう。\n①( )彼が来ても、私の考えは変わらない。 ②( )明日は晴れるだろう。 ③( )遠慮なく、お申し出ください。\n〔たとえ・おそらく・どうか〕', a: '①たとえ ②おそらく ③どうか', exp: '①は後ろに「来ても」とあるので、逆接の仮定と呼応する「たとえ」が入ります。②は「晴れるだろう」と推量の形なので、「おそらく」が入ります。③は「お申し出ください」と依頼の形なので、「どうか」が入ります。\nこのように、空らんの後ろの文末の形を見れば、入る副詞を決めることができます。\nなお、「どうか」には、「どうかしている(ふつうではない)」のように、呼応の副詞ではない使い方もあります。また、「ぜひ」も依頼・願望と呼応しますが、「ぜひ〜ない」とは言わない点で、「どうか」と同じく肯定の願いに使われます。' },
      { lv: 3, q: '「まさか」と「よもや」は、どちらも後ろに同じような形がくる呼応の副詞である。どんな形と呼応するかを答え、それぞれを使って例文を作ろう。', a: '打ち消しの推量(〜ないだろう・〜まい)と呼応する。例文:「まさか彼がうそをつくことはないだろう。」「よもや約束を忘れはしまい。」', exp: '「まさか」「よもや」は、「そんなことはありえないだろう」という、打ち消しの推量の気持ちを表す副詞です。後ろに「〜ないだろう」「〜まい」がきます。\n「まい」は、打ち消しの推量(〜ないだろう)や、打ち消しの意志(〜しないつもりだ)を表す助動詞です。「よもや〜まい」は、やや古風でかたい言い方です。\nなお「まさか」は、「まさかの時に備える」(万一の場合)のように、名詞として使われることもあります。また、会話では「まさか!」と、驚きを表す感動詞のように使われることもあり、呼応の副詞と区別が必要です。' },
      { lv: 3, q: '次の文には、文法上の誤りが2つある。それぞれ指摘して、正しい文に直そう。\n「私の夢は、決して人の役に立つ仕事につきたいので、毎日努力している。」', a: '誤り①:「決して」は打ち消しと呼応する副詞なのに、打ち消しの形が後ろにない(「決して」を「ぜひ」「必ず」などに変えるか、削る)。誤り②:主語「私の夢は」と述語が対応していない(ねじれ)。直した文の例:「私の夢は、人の役に立つ仕事につくことなので、毎日努力している。」(または「私は、必ず人の役に立つ仕事につきたいので、毎日努力している。」)', exp: '1つめは、呼応の副詞の誤りです。「決して」は「〜ない」と呼応するので、この文のように「つきたい」という肯定の願いとは結びつきません。願いを強めたいなら「ぜひ」、意志を強めたいなら「必ず」を使います。\n2つめは、主語と述語のねじれです。「私の夢は」が主語なら、述語は「〜ことだ」「〜ことなので」のように名詞の形で受ける必要があります。「つきたい」は「私は」に対応する述語です。\n作文で長い文を書くと、このような誤りが起こりやすくなります。一文を短く区切ったり、書き終えた文の主語と述語、呼応の副詞を確かめたりする習慣をつけましょう。' }
    ],
    faq: [
      ['「全然大丈夫」は、まちがった日本語なの?', '話し言葉では広く使われていて、明治時代の小説などにも「全然」を肯定で使った例があることが知られています。そのため、一概にまちがいとは言えません。ただし、現在の書き言葉や入試では、「全然〜ない」と打ち消しで使うのが標準的だと考えられています。作文や記述問題では、誤解を招かないよう「全然」は打ち消しといっしょに使い、肯定の意味を強めたいときは「まったく」「とても」などを使うと安全です。'],
      ['呼応の副詞は、なぜ「陳述の副詞」とも呼ばれるの?', '「陳述」とは、話し手が文の内容をどう述べるか(打ち消すのか、推量するのか、たずねるのか)という、文の述べ方のことです。呼応の副詞は、この述べ方を前もって示す働きをするので、「陳述の副詞」や「叙述の副詞」と呼ばれます。これに対して、「ゆっくり歩く」の「ゆっくり」のように動作の様子を表す副詞を状態の副詞、「とても大きい」の「とても」のように程度を表す副詞を程度の副詞といいます。']
    ]
  });

  add('jx_jh3', {
    secs: [
      { h: 'さらに深く:「だ」の識別 ― 4つの正体を見分ける', t: '難関校の識別問題では、「ない」「れる・られる」「の」に加えて、【「だ」の識別】がよく出ます。「だ」には、主に次の4つの正体があります。\n①【断定の助動詞「だ」】…名詞などについて「〜である」と言い切る。例:今日は日曜日だ。\n②【形容動詞の活用語尾】…「静かだ」「きれいだ」の「だ」。形容動詞は一語なので、「だ」は語の一部です。\n③【過去・完了の助動詞「た」が濁ったもの】…動詞の音便形の後ろで「た」が「だ」になる。例:本を読んだ。泳いだ。\n④【助動詞「そうだ」「ようだ」の一部】…例:雨が降りそうだ。夢のようだ。\n見分けるための置きかえテストは次のとおりです。\n・①か②か迷ったら、【「とても」をつけてみる】、または【「な」に変えて名詞につなげてみる】。「とても静かだ」「静かな部屋」と言えれば形容動詞(②)です。「とても日曜日だ」「日曜日な朝」とは言えないので、①は断定の助動詞です。\n・③は、直前が【動詞の音便形】(読ん・泳い など)になっていることで分かります。「だ」を「た」にもどして、過去の意味(〜た)になれば③です。\n・④は、「そう」「よう」がすぐ前にあれば、「そうだ」「ようだ」で一語の助動詞と考えます。\n①と②の区別がいちばん問われます。「健康だ」「自由だ」のように、名詞にも形容動詞にも見える語は、「とても健康だ」「健康な人」と言えるかで確かめましょう。言えれば形容動詞です。', key: '「だ」は断定・形容動詞の語尾・「た」の濁音・「そうだ/ようだ」の一部の4種類。「とても」をつける、「な」に変える、「た」にもどす、の置きかえで見分ける。', ex: [{ q: '次の傍線部の「だ」の文法的説明を答えよう。\n①この町はとても静か【だ】。 ②兄は大学生【だ】。 ③川で泳い【だ】。 ④明日は晴れるよう【だ】。', hint: '「とても」をつける、「な」に変える、「た」にもどす、などのテストを試してみましょう。', steps: ['①「とても静かだ」と言え、「静かな町」と「な」に変えて名詞につなげられる。「静かだ」は形容動詞なので、「だ」はその活用語尾。', '②「とても大学生だ」「大学生な兄」とは言えない。名詞「大学生」に、断定の助動詞「だ」がついている。', '③直前の「泳い」は、動詞「泳ぐ」の連用形が音便(イ音便)になったもの。「だ」は過去の助動詞「た」が濁ったもの。', '④直前に「よう」があり、「ようだ」で推定(たとえ)を表す一語の助動詞。「だ」はその一部。'], a: '①形容動詞「静かだ」の活用語尾 ②断定の助動詞「だ」 ③過去の助動詞「た」(が濁ったもの) ④助動詞「ようだ」の一部', check: '①は、文の中ですでに「とても」がついていることも、形容動詞であることの手がかりになります。置きかえテストの結果が、文の中の他の語とも矛盾しないかを確かめましょう。' }] },
      { h: '実戦演習:複数の条件がついた記述問題', t: '難関校の記述問題では、「〜という語を使って」「〜と〜を対比して」「〜字以上〜字以内で」など、【複数の条件】がつくことがあります。戦略は次のとおりです。\n①解く前に、条件を【箇条書きにして】、一つずつ番号をつけます。\n②本文から、答えに必要な部分(理由・言いかえ・対比など)を集めます。\n③指定語は、本文の中でどう使われているかを確かめてから、同じ意味で使います。\n④書いたら、条件を一つずつ確かめてチェックを入れます。\n落とし穴は、内容はよいのに条件を1つ落として大きく減点されることです。とくに、指定語を「入れただけ」で、文の中で意味が通っていない答えは、条件を満たしたと見なされないことがあります。', key: '条件を番号つきで書き出し、書き終えたら一つずつチェックする。指定語を本文と同じ意味で使えているかで差がつく。', ex: [{ q: '次の作例の文章を読んで答えよう。\n「地図アプリを使えば、初めての町でも迷わずに目的地に着ける。だが、画面の矢印だけを見て歩く人は、町の景色をほとんど覚えていない。一方、紙の地図を手に迷いながら歩いた人は、途中で見た古い店や坂道を、あとになっても思い出せる。迷うことは、時間のむだに見えて、実は町を自分の体で知るための大切な時間なのである。」\n問い:筆者は「迷うこと」をどのようなものと考えているか。次の条件に従って書こう。\n条件1:「地図アプリ」と「紙の地図」を対比すること。 条件2:「記憶」という語を使うこと。 条件3:50字以上70字以内で書くこと。', hint: '最後の文が筆者の考えです。「記憶」は、本文の「覚えていない」「思い出せる」を言いかえる語として使えます。', steps: ['条件を確かめる。①地図アプリと紙の地図の対比、②「記憶」を使う、③50〜70字。', '本文から対比を整理する。地図アプリ=迷わないが、景色をほとんど覚えていない。紙の地図=迷いながら歩くが、店や坂道をあとで思い出せる。', '「記憶」の使い方を決める。「覚えていない」「思い出せる」を、「町の記憶が残らない/残る」と言いかえる。', '筆者の考え(最後の文)を入れる。迷うことは、むだに見えて、町を自分の体で知るための大切な時間。', '対比→筆者の考えの順にまとめ、字数を数えて50〜70字に調整する。'], a: '(例)地図アプリで迷わず歩くと町の記憶は残らないが、紙の地図で迷いながら歩くと記憶に残るので、迷うことは町を体で知る大切な時間だと考えている。(68字)', check: '条件を一つずつ確かめます。①地図アプリ⇔紙の地図の対比がある、②「記憶」を「残る/残らない」と本文の内容に合う意味で使っている、③68字で50〜70字に収まっている。字数オーバーのときは、「ほとんど」「自分の」など、意味を変えずに削れる語から削ります。' }] }
    ],
    drill: [
      { lv: 2, q: '「彼は、とても親切だ。」と「これは、親切心だ。」の「だ」の文法的説明を、それぞれ答えよう。', a: '「親切だ」の「だ」=形容動詞「親切だ」の活用語尾。「親切心だ」の「だ」=断定の助動詞「だ」。', exp: '「親切だ」は、「とても親切だ」と程度の副詞がつけられ、「親切な人」と「な」の形で名詞につなげられるので、形容動詞です。「だ」はその活用語尾で、独立した単語ではありません。\n「親切心」は名詞なので、「とても親切心だ」「親切心な人」とは言えません。名詞「親切心」に、断定の助動詞「だ」がついています。\nこのように、似た語でも、形容動詞か名詞かで「だ」の正体が変わります。迷ったら、「とても」をつける・「な」に変える、という2つのテストをしてみましょう。どちらか一方だけでなく、両方で確かめると確実です。' },
      { lv: 3, q: '次の傍線部のうち、文法的説明が他と異なるものを1つ選び、理由を説明しよう。\nア 本を読ん【だ】。 イ 空を飛ん【だ】。 ウ 宿題はもう済ん【だ】。 エ これは姉の本【だ】。', a: 'エ。ア・イ・ウの「だ」は、動詞の連用形の撥音便(読ん・飛ん・済ん)についた過去・完了の助動詞「た」が濁ったものだが、エの「だ」は名詞「本」についた断定の助動詞「だ」だから。', exp: 'ア「読んだ」、イ「飛んだ」、ウ「済んだ」は、それぞれ「読む」「飛ぶ」「済む」の連用形が撥音便になり、その後ろの「た」が「だ」に濁ったものです。「だ」を「た」にもどすと、「読みた」「飛びた」とは言いませんが、意味は「〜た」(過去・完了)です。\nウの「済んだ」は、「もう」とあることから、過去というより完了(〜してしまった)の意味ですが、文法上の種類は同じ助動詞「た」です。\nエは、名詞「本」の後ろについて、「これは姉の本である」と言い切る断定の助動詞です。直前の語が動詞の音便形か名詞かを見れば、すぐに区別できます。' },
      { lv: 3, q: '次の文章を読み、筆者が「便利さ」についてどのように考えているかを、「失う」という語を使い、40字以上60字以内で書こう。\n作例「電子レンジのおかげで、料理は短い時間でできるようになった。けれども、鍋の前で火加減を見ながら、においや音で煮え具合を知るという経験は、少なくなった。便利さは、私たちに時間をくれるが、その代わりに何かを持ち去っていく。」', a: '(例)便利さは料理の時間を短くしてくれるが、火加減を見ながらにおいや音で煮え具合を知る経験を失わせるものだと考えている。(57字)', exp: '筆者の考えは、最後の文「便利さは、私たちに時間をくれるが、その代わりに何かを持ち去っていく」に表れています。「何か」の内容は、前の文の「火加減を見ながら、においや音で煮え具合を知るという経験」です。\n指定語「失う」は、本文の「持ち去っていく」を言いかえる語として使います。「便利さが〜を失わせる」「私たちは〜を失う」のどちらの形でもかまいませんが、主語と述語が対応しているかに注意しましょう。\n答えは、「便利さは〜をくれるが、〜を失わせる」という対比の形にすると、筆者の考えの両面を表せます。字数は句読点もふくめて数え、40字以上60字以内に収まっているかを確かめましょう。' }
    ],
    faq: [
      ['「だ」が形容動詞の語尾か断定の助動詞か、どうしても分からないときは?', '「とても」をつけるテストと、「な」に変えて名詞につなげるテストの両方を試しましょう。両方とも自然に言えれば形容動詞、両方とも言えなければ「名詞+断定の助動詞」です。「健康」「自由」「平和」などは、名詞としても使われるので迷いやすい語です。「とても健康だ」「健康な体」と言えるので、この形では形容動詞と判断します。文の中で「健康を保つ」のように「を」がつけば名詞です。'],
      ['記述問題で、字数が少しオーバーしてしまったら?', '字数制限は必ず守らなければなりません。制限をこえると、内容がよくても大きく減点されたり、0点になったりすることがあります。オーバーしたら、①「とても」「ほとんど」などの程度の言葉、②くり返しの言葉、③具体例のこまかい部分、の順に削ると、意味を変えずに字数を減らせます。反対に、字数が足りないときは、理由や対比の相手など、条件に関わる要素が抜けていないかを確かめましょう。']
    ]
  });

  add('j_kogo', {
    secs: [
      { h: 'さらに深く:よい意味にも悪い意味にもなる古語', t: '古文単語の中には、【よい意味にも悪い意味にもなる語】があります。これらは「程度がふつうではない」「心が強く動かされる」という中心の意味をもっていて、その「ふつうではない」方向が、よいほうか悪いほうかで訳が変わるのです。\n①【ゆゆし】…もとは「神聖で、ふれてはならない」という意味。そこから「おそれ多い」「不吉だ・忌まわしい」、さらに「(程度が)はなはだしい」「すばらしい」と、よい意味にも悪い意味にも広がりました。\n②【すごし】…「ぞっとするほどもの寂しい・恐ろしい」が中心。そこから「ぞっとするほどすばらしい」の意味も生まれました。\n③【かしこし】…「おそれ多い」が中心。そこから「(おそれ多いほど)すぐれている・りっぱだ」、連用形「かしこく」で「たいそう・はなはだしく」、さらに「運がよい」の意味もあります。\n④【いみじ】…「程度がはなはだしい」。「いみじくうれし」(とてもうれしい)、「いみじく悲し」(ひどく悲しい)と、後ろの語で方向が決まります。\nこれらの語を訳すときは、【何について言っているか】と【前後に、よい・悪いを示す語があるか】を確かめます。たとえば「ゆゆしき大事」なら、大きな事件の重大さを表して「たいへんな」、「ゆゆしき人の御かたち」なら、人の容姿をほめて「すばらしい」と訳します。\n入試では、こうした語の訳を問い、選択肢に「よい意味」と「悪い意味」の両方を並べることがよくあります。中心の意味を覚えたうえで、場面に合う方向を選ぶことが大切です。', key: '「ゆゆし・すごし・かしこし・いみじ」は「程度がふつうではない」が中心。よい方向か悪い方向かは、話題と前後の語で決める。', ex: [{ q: '次の作例の傍線部を、文脈に合わせて訳し分けよう。\n①夜ふけて、山の奥より、【すごき】風の音聞こゆ。 ②舞ひ終はりたる姿の、いと【すごく】めでたければ、人々ほめあへり。', hint: '中心の意味は「ぞっとするほど」です。①と②で、よい方向・悪い方向のどちらかを考えます。', steps: ['中心の意味を確かめる。「すごし」は「ぞっとするほど(心に強くせまる)」。', '①の場面は「夜ふけて」「山の奥より」聞こえる風の音。人のいない、さびしく恐ろしい場面なので、悪い方向。「ぞっとするほどもの寂しい」と訳す。', '②は、舞を終えた姿について言っていて、後ろに「めでたければ(すばらしいので)」「ほめあへり」とある。よい方向なので「ぞっとするほどすばらしく」と訳す。', '訳を本文に入れて、場面に合っているかを確かめる。'], a: '①ぞっとするほどもの寂しい(恐ろしい)風の音 ②(舞い終えた姿が)ぞっとするほどすばらしく(りっぱで)', check: '②で「恐ろしく」と訳すと、「めでたければ」「ほめあへり」と合いません。前後のほめ言葉が、よい方向で訳す根拠になっていることを確かめます。' }] },
      { h: '実戦演習:語句解釈の選択肢を、中心の意味と文脈でしぼる', t: '大学入試の古文では、傍線部の語句の解釈として最も適当なものを選ぶ問題が必ずと言ってよいほど出ます。戦略は次のとおりです。\n①傍線部の【重要単語】を見つけ、中心の意味を思い出します。\n②中心の意味から外れた選択肢(現代語の意味にもとづくものなど)を消します。\n③残った選択肢を、【前後の文脈】(だれについて言っているか、よい評価か悪い評価か)で比べます。\n④助動詞や助詞(打消・推量・敬語など)の訳が正しいかも確かめます。\n落とし穴は、単語の意味だけで選んで、文法(打消や推量)の訳の誤りを見落とすことです。単語と文法の両方を照らし合わせましょう。', key: '単語の中心の意味で選択肢を2つにしぼり、最後は文法(打消・推量・敬語)の訳で決める。ここで差がつく。', ex: [{ q: '次の作例の古文を読んで答えよう。\n「その寺の僧、仏の道にくはしく、経をよむ声のいとたふとかりければ、都の人々、ゆゆしき聖なりとて、遠きよりまうで来けり。されど僧は、人の多く集まるをうるさしと思ひて、やがて山深く入りにけり。」\n(くはし=くわしい。たふとし=尊い。聖=りっぱな僧。まうづ=参上する。やがて=すぐに)\n問:傍線部「ゆゆしき聖なり」の解釈として最も適当なものを選ぼう。\nア 不吉な僧である イ おそろしい僧である ウ すばらしい聖人である エ 身分の低い僧である', hint: '「ゆゆし」の中心は「ふつうではない」。前後で、僧はよく評価されていますか。', steps: ['重要単語は「ゆゆし」。中心の意味は「(おそれ多いほど)ふつうではない」で、よい意味にも悪い意味にもなる。', 'エ「身分の低い」は、「ゆゆし」の意味と関係がないので消す。', '前後の文脈を確かめる。僧は「仏の道にくはしく」、経を読む声が「いとたふとかり」とほめられている。', 'さらに「遠きよりまうで来けり」と、人々がわざわざ遠くから参上している。よい評価なので、ア「不吉な」・イ「おそろしい」は合わない。', 'よい方向の訳であるウ「すばらしい聖人である」が最も適当。'], a: 'ウ', check: 'ウを本文に入れると、「人々が、すばらしい聖人だと言って、遠くから参上した」となり、前の「たふとかりければ」(尊かったので)と因果関係がつながります。また、後半で僧が人の集まりをきらって山に入るのは、評判が高すぎたためと読め、話の流れとも合います。' }] }
    ],
    drill: [
      { lv: 2, q: '作例「帝の御文を賜はりて、いとかしこく思ひけり。」の「かしこく」の意味を答え、文全体を訳そう。', a: '「かしこく」=おそれ多く。訳:帝のお手紙をいただいて、たいそうおそれ多く思った。', exp: '「かしこし」は、もとは「(神や身分の高い人に対して)おそれ多い」という気持ちを表す語です。帝(天皇)からお手紙をいただくという場面なので、中心の意味の「おそれ多い」と訳すのが自然です。\nなお、「かしこし」には「すぐれている・りっぱだ」「運がよい」の意味もあり、連用形「かしこく」は「たいそう・はなはだしく」と程度を表すこともあります。たとえば「かしこく晴れたり」なら「たいそうよく晴れた」となります。\nどの意味になるかは、話題が身分の高い人に関わるか、人や物の能力を評価しているか、などの文脈で判断します。' },
      { lv: 3, q: '作例の2つの文の「ゆゆし」を、それぞれ文脈に合わせて訳そう。\n①その年、都に病はやりて、ゆゆしきことども多かりけり。 ②この君の御かたち、ゆゆしきまでうつくしくおはします。', a: '①(病がはやって)不吉な・忌まわしい(恐ろしい)ことがたくさんあった。②(この若君のお顔立ちは)不吉なほどに(この世のものとは思えないほど)かわいらしくていらっしゃる。', exp: '①は、病気が流行して人々が苦しんでいる場面なので、悪い方向の「不吉だ・忌まわしい」と訳します。\n②は少しむずかしい例です。「うつくしく」(かわいらしく)とほめているので、よい方向に見えますが、「ゆゆしきまで」は「不吉に感じられるほどに」と訳すのが一般的です。昔の人は、あまりにすぐれたものは、神にとられて早く亡くなってしまうのではないかと不安に思うことがありました。そのため、「ゆゆしきまで」は、美しさがこの世のものとは思えないほどであることを、「不吉なほど」という言い方で強調しているのです。\nこのように、よい意味と悪い意味が重なることもあるので、中心の意味から考えることが大切です。' },
      { lv: 3, q: '作例「人々のいみじう笑ひけるを聞きて、翁はいみじう恥づかしと思ひけり。」の2つの「いみじう」は、それぞれどんな方向の意味で、どう訳せばよいか。また、「いみじう」はどんな形が変化したものか答えよう。', a: '1つめ:程度のはなはだしさを表し、「たいそう・ひどく(笑った)」と訳す(人々が大笑いした)。2つめ:程度のはなはだしさを表し、「ひどく・たいそう(恥ずかしい)」と訳す。翁にとってはつらい方向。「いみじう」は、形容詞「いみじ」の連用形「いみじく」がウ音便になったもの。', exp: '「いみじ」は「程度がはなはだしい」という中心の意味をもち、それ自体はよいとも悪いとも決まっていません。よい方向か悪い方向かは、後ろの語で決まります。\n1つめは「笑ひける」に、2つめは「恥づかし」にかかっていて、どちらも「とても・ひどく」と訳せます。ただし、人々にとっては楽しい笑いでも、笑われた翁にとってはつらい出来事であり、同じ「いみじう」が、話の中で正反対の気持ちを強めていることに注目しましょう。\n「いみじう」は、連用形「いみじく」の「く」が「う」になったウ音便です。古文ではよく見る形なので、「〜う」の形の形容詞は連用形の音便だと気づけるようにしましょう。' }
    ],
    faq: [
      ['よい意味と悪い意味の両方がある語は、どちらで覚えればいいの?', 'どちらか一方ではなく、「中心の意味」で覚えるのがおすすめです。たとえば「ゆゆし」なら「ふつうではない(おそれ多いほど)」、「すごし」なら「ぞっとするほど」と覚えておけば、場面に合わせて、よい方向にも悪い方向にも訳を作れます。そのうえで、入試でよく出る訳(ゆゆし=不吉だ・すばらしい、すごし=もの寂しい・すばらしい)をセットで確認しておくと、選択肢の問題でも迷わずに済みます。'],
      ['現代語の「すごい」は、古文の「すごし」と関係があるの?', '関係があります。現代語の「すごい」は、古語の「すごし」から来た言葉です。古文では「ぞっとするほどもの寂しい・恐ろしい」という意味が中心でしたが、時代とともに「ぞっとするほどすばらしい」の意味が強くなり、さらに現在では、よい意味でも悪い意味でも「程度がはなはだしい」ことを表す、とても広い言葉になりました。ただし、古文で「すごし」を見たら、まず「もの寂しい・恐ろしい」の意味を考えるのが基本です。']
    ]
  });

  add('jx_std', {
    secs: [
      { h: 'さらに深く:漢文の詠嘆と願望の句形', t: '否定・疑問・反語・使役・受身などの句形に加えて、入試では【詠嘆】(感動を表す)と【願望】(願いを表す)の句形もよく問われます。どちらも、話し手の気持ちが強く出る形なので、人物の心情を問う設問の根拠になります。\n【詠嘆の句形】\n①【嗚呼・噫・嗟】(ああ)…文頭で、感動やなげきを表す。\n②【何其A也】(何ぞ其れAなるや)…なんとAなことよ。例:「何ぞ其れ速やかなるや」=なんと速いことよ。\n③【豈不A哉】(豈にAならずや)…なんとAではないか。もとは反語の形(どうしてAでないことがあろうか)ですが、感動をこめて「なんとAではないか」と訳すことが多い形です。\n④【不亦A乎】(亦Aならずや)…なんとAではないか。『論語』の「不亦説乎」(亦説ばしからずや)が有名です。\n⑤【A哉】(Aなるかな)…Aだなあ。文末の「哉」「矣」「夫」などが詠嘆を表す。\n【願望の句形】\n①【願A】(願はくはAせよ/Aせん)…どうかAしてください(相手への願い)/なんとかAしたい(自分の願い)。\n②【請A】(請ふAせよ/Aせん)…どうかAしてください/どうかAさせてください。例:『孟子』「請以レ戦喩」(請ふ戦ひを以て喩へん)=どうか戦争でたとえさせてください。\n③【庶幾A】(庶幾はくはAせよ)…どうかAであってほしい。\n願望の文末の読みは、相手に頼むときは命令形(〜せよ)、自分がしたいときは「〜ん(む)」となります。だれの動作かを確かめて読み分けることが大切です。', key: '詠嘆は「何其〜也」「豈不〜哉」「不亦〜乎」「〜哉」、願望は「願はくは」「請ふ」。願望は、相手への願いなら「〜せよ」、自分の願いなら「〜せん」と読む。', ex: [{ q: '次の句形の書き下し文と意味を答えよう。①何其多也 ②請以レ戦喩(『孟子』。喩=たとえる)', hint: '①は詠嘆、②は願望の形です。②でたとえるのはだれでしょう。', steps: ['①「何其A也」は詠嘆の句形。「何ぞ其れAなるや」と読む。Aは「多」なので「何ぞ其れ多きや」。', '①の意味は「なんと多いことよ」。疑問(どうして多いのか)ではなく、感動を表している。', '②「請」は願望。「以レ戦」は「戦ひを以て」、「喩」は「喩ふ」。', '②でたとえるのは話し手自身(孟子)。自分がしたいことを願うので、文末は「〜ん」と読み、「請ふ戦ひを以て喩へん」。意味は「どうか戦争でたとえさせてください」。'], a: '①書き下し文:何ぞ其れ多きや。意味:なんと多いことよ。②書き下し文:請ふ戦ひを以て喩へん。意味:どうか戦争(のこと)でたとえさせてください。', check: '②を「喩へよ」と命令形で読むと、「相手にたとえてもらう」意味になります。この場面は、戦争を好む王に対して、孟子が自分からたとえ話をしようとしているので、「喩へん」が正しいと確かめられます。' }] },
      { h: '実戦演習:句形から人物の心情を読む', t: '共通テストの漢文では、句形の知識を使って、登場人物の心情や態度を説明させる問題が出ます。戦略は次のとおりです。\n①会話文の中の【句形(詠嘆・願望・反語・疑問)】を見つけ、印をつけます。\n②句形ごとに、話し手の気持ちを一言でメモします(詠嘆=感動・あきれ・なげき、願望=強い願い、反語=強い否定)。\n③その気持ちが、話の流れの中で何に向けられているかを確かめます。\n落とし穴は、「何其〜也」を疑問(どうして〜なのか)と訳してしまうことです。「何其」と「也」がセットで出たら、まず詠嘆を考えましょう。', key: '会話の句形から話し手の気持ちを一言でつかむ。詠嘆の「何其〜也」を疑問と取りちがえないかで差がつく。', ex: [{ q: '次の作例の漢文を読んで答えよう。\n「客曰、願聞二先生之説一。先生笑曰、何其急也。学者先修二其身一、而後可レ言レ道。」\n(先生=学問を教える人。修=おさめる、身を正しくする)\n(1)「願聞二先生之説一」を書き下し文にし、意味を答えよう。(2)「何其急也」を書き下し文にし、意味を答えよう。(3)先生は、客のどのような態度に対して、どう考えているか説明しよう。', hint: '(1)聞きたいのはだれでしょう。(2)は詠嘆の形です。', steps: ['(1)「願」は願望。聞きたいのは話し手の客自身なので、文末は「〜ん」と読む。「願はくは先生の説を聞かん」。', '(1)の意味は「どうか先生のお考えをお聞きしたい」。', '(2)「何其A也」は詠嘆。「何ぞ其れ急なるや」と読み、「なんとせっかちなことよ」という意味。', '(3)先生の続く言葉「学者先修二其身一、而後可レ言レ道」は「学ぶ者は先づ其の身を修めて、而る後に道を言ふべし」。学ぶ者はまず自分の身を正しくし、その後で道(正しい生き方)について語るべきだ、という意味。', '先生は、客がまだ自分の身を修めていないのに、すぐに先生の考え(道)を聞こうとする態度を、あきれながら、せっかちだと考えている。'], a: '(1)書き下し文:願はくは先生の説を聞かん。意味:どうか先生のお考えをお聞きしたい。(2)書き下し文:何ぞ其れ急なるや。意味:なんとせっかちなことよ。(3)先生は、まず自分の身を正しくすることが先であるのに、客がそれをせずにすぐ教えを聞こうとする態度をせっかちだと感じ、学ぶ順序がちがうと考えている。', check: '(2)を疑問「どうしてそんなに急ぐのか」と訳しても、先生の次の言葉(学ぶ順序の説明)とつながるように見えます。しかし「笑ひて曰はく」とあるので、本当に理由をたずねるより、あきれて感動をこめた詠嘆と読むほうが自然です。' }] }
    ],
    drill: [
      { lv: 2, q: '「豈不レ美哉」を書き下し文にし、詠嘆として意味を答えよう。', a: '書き下し文:豈に美ならずや。(豈に美しからずや と読むこともある) 意味:なんと美しいことではないか。', exp: '「豈不A哉」は、もとは反語の形で、「どうしてAでないことがあろうか(いや、Aである)」という意味です。これが「Aではないか」という強い肯定になり、そこに感動がこめられて、「なんとAではないか」という詠嘆の意味で使われるようになりました。\n反語の「豈A哉」(豈にAならんや=どうしてAだろうか、いやAではない)と形が似ていますが、間に「不」があるかどうかで意味が反対になります。「不」があれば肯定(詠嘆)、なければ否定(反語)です。\n「哉」は文末で詠嘆や疑問・反語を表す字で、「や」「かな」と読みます。' },
      { lv: 3, q: '次の2つの「願」の文の、文末の読み方がちがう理由を説明しよう。\n①願大王察レ之(願はくは大王之を察せよ) ②願得二一言一(願はくは一言を得ん)', a: '①は、話し手が相手(大王)に「どうかお察しください」と頼む願いなので、相手の動作を命令形「察せよ」で読む。②は、話し手自身が「なんとか一言をいただきたい」と願うので、自分の意志・願望を表す「得ん」と読む。', exp: '願望の句形「願はくは〜」は、文末の読み方で、だれの動作を願っているかが変わります。\n相手に何かをしてほしいときは、相手の動作を命令形(〜せよ)で読み、「どうか〜してください」と訳します。\n自分が何かをしたいときは、意志・願望の「〜ん(む)」で読み、「なんとかして〜したい」と訳します。\n①は、主語として「大王」が示されているので、相手への願いだとすぐに分かります。②は主語が書かれていませんが、「一言を得る」のは話し手自身だと文脈から判断できます。主語が書かれていないときは、だれがその動作をするのが自然かを考えましょう。' },
      { lv: 3, q: '「嗚呼、哀哉。」と「哀哉、人之不レ学也。」の2つの文について、それぞれ書き下し文にし、意味を答えよう。また、2つめの文の語順の特徴を説明しよう。', a: '1つめ:書き下し文=嗚呼、哀しいかな。意味=ああ、悲しいことだなあ。2つめ:書き下し文=哀しいかな、人の学ばざるや。意味=悲しいことだなあ、人が学ばないことは。語順の特徴:感動の言葉「哀しいかな」を先に出し、何について悲しんでいるか(人が学ばないこと)を後に置く倒置の形になっていて、なげきの気持ちが強調されている。', exp: '「嗚呼」は「ああ」と読み、感動やなげきを表す語です。「哉」は文末で「かな」と読み、「〜だなあ」と詠嘆を表します。\n2つめの文は、ふつうの語順なら「人の学ばざるは、哀しいかな」(人が学ばないのは悲しいことだ)となるところです。それを、感情を表す部分を先に、その対象を後に置くことで、まず話し手のなげきが強く伝わる形になっています。日本語の倒置法と同じ効果です。\n文末の「也」は、ここでは「や」と読み、主題を示して詠嘆の気持ちをそえています。漢文でも、語順を入れかえることで感情を強める表現があることを覚えておきましょう。' }
    ],
    faq: [
      ['詠嘆と反語は、形が似ていてまぎらわしいです。どう見分けるの?', '「豈不〜哉」「不亦〜乎」のように、反語の形に「不」が入っていると、反語の否定がさらに否定されて「強い肯定」になり、そこから詠嘆(なんと〜ではないか)の意味が生まれます。「不」があるかどうかを最初に確かめましょう。また、「何其〜也」は、「何」が疑問の字なので疑問・反語とまちがえやすいのですが、「其」と「也」がセットになっていれば詠嘆を考えます。最後は、前後の文脈で、話し手が感動しているのか、否定しているのかを確かめます。'],
      ['「請」は、なぜ「どうか〜させてください」と「どうか〜してください」の両方の意味になるの?', '「請」はもともと「こう(お願いする)」という意味の字で、何をお願いするかによって訳が変わるからです。自分がある動作をすることの許しを求めるなら「どうか〜させてください」、相手にある動作をしてもらいたいなら「どうか〜してください」となります。読み方も、前者は「〜ん」、後者は「〜せよ」となります。だれの動作かを文脈で確かめれば、どちらの意味か判断できます。']
    ]
  });

  add('hd_jpn', {
    secs: [
      { h: 'さらに深く:「し」の識別 ― 過去・サ変・強意の副助詞', t: '「なり」「ぬ」「に」「なむ」の識別に続いて、難関大で問われるのが【「し」の識別】です。1字の語なので見落としやすく、しかも可能性が多いのが特徴です。主なものは次の5つです。\n①【過去の助動詞「き」の連体形】…連用形につく。例:見し人(見た人)。ただし、カ変・サ変には特別な接続をする(来し=こし・きし、せし)。後ろに体言が続くか、係り結びの結びになっていることが多い。\n②【サ変動詞「す」の連用形】…「〜し(て)」の形で「〜して」と訳せる。例:物語などして(物語などをして)、心地あしくして。\n③【強意の副助詞「し」】…語について意味を強める。取りのぞいても文の意味が変わらない。「しも」「し〜ば」の形が多い。例:「名にし負はば」(在原業平)=名として持っているならば。\n④【形容詞の活用語尾】…「高し」「うつくし」など、形容詞の終止形や、シク活用の語幹の一部。\n⑤【動詞の活用語尾の一部】…「出だし」(四段「出だす」の連用形)など。\n見分けの手順は、(1)「し」が動詞や形容詞の一部になっていないか(④⑤)を最初に確かめ、(2)直前の語が連用形なら①を考え、後ろに体言や係り結びがあるか確かめる、(3)「して」の形でサ変の「する」と訳せるなら②、(4)取りのぞいても文が成り立つなら③、の順です。\nとくに③の強意の副助詞は、和歌でよく使われます。「し」を取りのぞいて意味が通るかどうかを、必ず試してみましょう。', key: '「し」は、語の一部か → 連用形+し(過去「き」連体形)か → 「して」でサ変か → 取りのぞけるか(強意の副助詞)、の順で確かめる。', ex: [{ q: '次の作例の傍線部の「し」の文法的説明を答えよう。\n①昔【見し】人も、今はなし。 ②心地あしく【して】、物も食はず。 ③名に【し】負はば、いざこと問はむ。 ④山いと【高し】。', hint: '①は直前の語の活用形、③は「し」を取りのぞいてみましょう。', steps: ['①直前の「見」は上一段「見る」の連用形。後ろに体言「人」が続いているので、過去の助動詞「き」の連体形。「昔見た人」。', '②「あしくして」は、形容詞「あし」の連用形「あしく」+「して」。「して」の「し」はサ変動詞「す」の連用形で、「気分が悪くて」と訳せる(接続助詞「して」とする考え方もある)。', '③「名にし負はば」の「し」を取りのぞくと「名に負はば」となり、意味が変わらない。強意の副助詞。', '④「高し」は形容詞「高し」の終止形で、「し」は活用語尾。'], a: '①過去の助動詞「き」の連体形 ②サ変動詞「す」の連用形(「して」で接続助詞とする説もある) ③強意の副助詞 ④形容詞「高し」の活用語尾', check: '①の「見」は未然形と連用形が同じ形ですが、過去の「き」は連用形につくので、連用形と判断します。接続のきまりで活用形を逆に決められることを確かめましょう。' }] },
      { h: '実戦演習:一つの文章の中で、複数の識別を組み合わせる', t: '難関大の古文では、一つの傍線部の中に「に」「し」「なり」「ぬ」などが重なり、それぞれの文法的説明の組み合わせとして正しいものを選ぶ問題が出ます。戦略は次のとおりです。\n①傍線部を【単語に区切り】、識別が必要な語に番号をつけます。\n②一つずつ、【接続(直前の語の活用形)】で候補をしぼります。\n③接続だけで決まらないものは、後ろに続く語や意味で決めます。\n④選択肢を見て、自分の答えと一致する組み合わせを選びます。選択肢を先に見ると、もっともらしい説明に引きずられやすくなります。\n落とし穴は、四段・上一段など、未然形と連用形が同じ形・終止形と連体形が同じ形の動詞です。形で決まらないときは、後ろの語から逆に決めましょう。', key: '傍線部を区切り、接続→後ろの語→意味の順に一語ずつ決める。選択肢を見る前に自分で答えを出せるかで差がつく。', ex: [{ q: '次の作例の傍線部の文法的説明として正しい組み合わせを選ぼう。\n「【去年の春、ともに花を見し人の、いづちか行きにし】と、思ひ出づるもかなし。」\n傍線部の「見し」の「し」(a)、「行きにし」の「に」(b)・「し」(c)\nア a=サ変動詞の連用形 b=断定の助動詞 c=強意の副助詞\nイ a=過去の助動詞 b=完了の助動詞 c=過去の助動詞\nウ a=過去の助動詞 b=格助詞 c=サ変動詞の連用形\nエ a=強意の副助詞 b=完了の助動詞 c=過去の助動詞', hint: 'a・cの「し」の直前は何形でしょう。bの「に」の後ろに何が続いていますか。', steps: ['a:「見し人」の「見」は上一段「見る」の連用形。後ろに体言「人」が続くので、過去の助動詞「き」の連体形。', 'b:「行きにし」の「に」は、四段「行く」の連用形「行き」についている。後ろに過去の「き」(し)が続くので、完了の助動詞「ぬ」の連用形。', 'c:「にし」の「し」は、連用形「に」についている。文中に係助詞「か」があり、その結びとして連体形になっているので、過去の助動詞「き」の連体形。', '組み合わせは a=過去、b=完了、c=過去。これに一致するのはイ。', '意味を確かめる。「去年の春、いっしょに花を見た人が、どこへ行ってしまったのだろうか」。'], a: 'イ', check: 'bを断定の「なり」の連用形と考えると、直前が連用形「行き」なので接続が合いません(断定は体言・連体形につく)。また、「にし」「にき」「にけり」のように、「に」の後ろに過去の助動詞が続くのは、完了の「ぬ」の典型的な形であることも確かめましょう。' }] }
    ],
    drill: [
      { lv: 2, q: '作例「京より来し人に、都のことを問ふ。」の「来し」の読み方と、「し」の文法的説明を答えよう。', a: '読み方=「こし」(「きし」とも読む)。「し」=過去の助動詞「き」の連体形。訳:京から来た人に、都のことをたずねる。', exp: '過去の助動詞「き」は、ふつうは連用形につきますが、カ変動詞「来」とサ変動詞「す」には特別なつき方をします。\nカ変「来」に「き」の連体形「し」がつくときは、「来し」と書いて「こし」と読む(未然形「こ」+し)のが一般的で、「きし」(連用形「き」+し)と読むこともあります。已然形「しか」がつくときも「こしか」「きしか」となります。\nサ変「す」には、「せし」「せしか」(未然形「せ」+し・しか)の形でつきます。たとえば「物語せし人」は「物語をした人」です。これらの特別な接続は、入試でよく問われるので、セットで覚えておきましょう。' },
      { lv: 3, q: '在原業平の和歌「名にし負はばいざこと問はむ都鳥わが思ふ人はありやなしやと」について、(1)「名にし負はば」の「し」の文法的説明と、その判断の根拠を答えよう。(2)「名にし負はば」を現代語訳しよう。', a: '(1)強意の副助詞。根拠:「し」を取りのぞいて「名に負はば」としても文の意味が変わらず、文の骨組みに関係しない働きだから。また、「し」の直前が名詞+格助詞「に」で、動詞の連用形ではないので、過去の助動詞「き」ではない。(2)(都という言葉を)名前として持っているならば。', exp: '「し」の直前は「名に」で、名詞「名」+格助詞「に」です。過去の助動詞「き」は活用語の連用形につくので、ここでは当てはまりません。サ変動詞「す」の連用形と考えても、「名にして負はば」とはならず、意味が通りません。\n「し」を取りのぞいても「名に負はば」(名前として持っているならば)となり、文が成り立つので、意味を強める副助詞と判断します。副助詞の「し」は、「し〜ば」の形で条件の部分を強めることが多く、和歌でよく見られます。\n「負はば」は、四段「負ふ」の未然形+「ば」で、「もし〜ならば」という仮定条件です。都鳥という名前に「都」が入っていることから、都のことを知っているなら教えてほしい、と呼びかけている歌です。' },
      { lv: 3, q: '作例「この事、人に語りしかば、皆あやしと言ひき。」の「し」と「き」の文法的説明を答え、文を現代語訳しよう。また、「しか」と「き」が同じ語であることを、活用表を使って説明しよう。', a: '「語りしかば」の「しか」=過去の助動詞「き」の已然形(「し」はその一部)。「言ひき」の「き」=過去の助動詞「き」の終止形。訳:このことを人に話したところ、皆が不思議だと言った。説明:過去の助動詞「き」は、(せ)・〇・き・し・しか・〇 と活用し、終止形が「き」、連体形が「し」、已然形が「しか」となるので、「しか」と「き」は同じ助動詞の活用形である。', exp: '過去の助動詞「き」は、特殊な形で活用する助動詞です。未然形「せ」(「せば」の形で反実仮想に使う)、終止形「き」、連体形「し」、已然形「しか」で、連用形と命令形はありません。\n「語りしかば」は、四段「語る」の連用形「語り」+「き」の已然形「しか」+接続助詞「ば」です。已然形+ばは確定条件で、「〜したところ・〜したので」と訳します。\nこのように、「し」は「しか」の一部として出てくることもあります。「し」の識別をするときは、後ろに「か」が続いて已然形「しか」になっていないかも確かめましょう。' }
    ],
    faq: [
      ['強意の副助詞「し」は、訳さなくていいの?', '現代語訳では、ふつうは訳しません。強意の副助詞「し」は、意味を強める働きをしますが、それにあたる現代語がないため、訳すとかえって不自然になるからです。ただし、文法的説明を問われたときに「訳さないから何もない」と考えず、「強意の副助詞」と答えられるようにしておく必要があります。「しも」の形では「〜でも・〜に限って」などと訳すこともあるので、文脈で判断しましょう。'],
      ['過去の「き」と「けり」は、なぜ両方あるの?', '「き」と「けり」は、どちらも過去を表しますが、使われ方がちがいます。「き」は、話し手(書き手)が自分で直接経験した過去を表すことが多く、「けり」は、人から伝え聞いた過去や、今になって気づいたことを表すことが多いです。そのため、物語の地の文では「けり」が多く、日記や回想の部分では「き」が多くなる傾向があります。また、「けり」には、和歌や会話で「〜だなあ」と気づきや感動を表す詠嘆の意味もあります。']
    ]
  });

  add('kt_ron', {
    secs: [
      { h: 'さらに深く:「類比(たとえ)」の論理をほどく', t: '評論の筆者は、自分の主張を分かりやすくするために、まったく別の分野のできごとを持ち出して説明することがあります。これを【類比(アナロジー)】といいます。たとえば、言葉について論じている文章で、急に「地図」や「料理」の話が出てくることがあります。\n類比を読むときに大切なのは、【何と何が対応しているのか】を表にして整理することです。\n例:「地図は、土地のすべてを描くことはできない。描くものを選び、それ以外を捨てることで、はじめて役に立つ地図になる。言葉も同じである。私たちは、言葉にすることで、経験の一部を選び出し、残りを捨てている。」\nこの文章の対応は、次のようになります。\n・地図 ⇔ 言葉\n・土地 ⇔ 経験\n・描くものを選ぶ ⇔ 経験の一部を言葉にする\n・それ以外を捨てる ⇔ 言葉にならない部分が捨てられる\n・役に立つ地図になる ⇔ (伝えられるようになる)\nこのように整理すると、筆者が言葉について言いたいこと(言葉は経験を選びとるものであり、同時に何かを捨てている)がはっきりします。また、表の右側に空らんがあれば、左側から推理して、本文に書かれていない部分まで読みとることができます。\n入試では、類比の部分に傍線が引かれ、「どういうことか」と問われることが多いです。その答えは、【たとえの側(地図)ではなく、主張の側(言葉)の言葉で書く】のが原則です。選択肢でも、たとえの話のまま説明しているものは、主張の説明になっていないので誤りになりやすいのです。', key: '類比は「何と何が対応しているか」を表にして読む。傍線部の説明は、たとえの側ではなく主張の側の言葉で答える。', ex: [{ q: '「料理人は、素材の味を引き出すために、あえて多くの調味料を使わない。足すことよりも、引くことのほうがむずかしいのだ。文章を書くこともまた、料理に似ている。」\nこの文章で、「料理」と「文章を書くこと」はどのように対応しているか。また、筆者が文章を書くことについて言いたいことを説明しよう。', hint: '「素材の味」「調味料」は、文章では何にあたるでしょう。', steps: ['対応を表にする。料理 ⇔ 文章を書くこと。', '「素材の味」⇔ 書き手が伝えたい内容(中心の考え)。「調味料」⇔ かざりの言葉や、よけいな説明。', '「多くの調味料を使わない」⇔ よけいな言葉を足さない。「引くことのほうがむずかしい」⇔ 書いたものを削ることのほうがむずかしい。', '主張の側の言葉でまとめる。文章では、言葉を足すよりも、よけいな言葉を削って伝えたい内容を引き立てることのほうが大切で、むずかしい。'], a: '対応:料理=文章を書くこと、素材の味=伝えたい内容、調味料=かざりやよけいな説明の言葉。言いたいこと:文章を書くときは、言葉を多く足すよりも、よけいな言葉を削って、本当に伝えたい内容を引き立てることのほうが大切であり、またむずかしいということ。', check: '答えに「調味料」「素材」などの料理の言葉が残っていないかを確かめます。主張の側(文章)の言葉だけで説明できていれば、類比を正しく読みとれています。' }] },
      { h: '実戦演習:類比と逆説をふくむ評論の読解', t: '共通テストの評論では、類比・逆説・対比が一つの文章の中で組み合わされます。戦略は次のとおりです。\n①本文を読みながら、類比の部分では【対応表】を、対比の部分では【A⇔B】のメモを、余白に簡単に書きます。\n②傍線部の説明問題では、傍線部をふくむ一文を、メモを使って主張の側の言葉に置きかえます。\n③選択肢は、【たとえのまま説明しているもの】【対比の向きが逆になっているもの】を先に消します。\n落とし穴は、類比の中の一部だけを取り出して、筆者の主張全体と取りちがえることです。類比が何を説明するために持ち出されたのかを、段落の最初と最後で確かめましょう。', key: '類比は対応表、対比はA⇔Bのメモを作ってから選択肢を見る。たとえのまま説明している選択肢を消せるかで差がつく。', ex: [{ q: '次の作例の文章を読んで答えよう。\n「庭師は、木をのびるままにはしておかない。枝を切り、形を整えることで、木はかえって健やかに育つ。人の記憶もまた、庭のようなものである。私たちは、すべての出来事を覚えているわけではない。多くを忘れ、いくつかの出来事だけを、くり返し思い出すことで、自分という一本の木の形を作っている。だとすれば、【忘れることは、記憶の欠陥ではなく、記憶の働きそのもの】なのである。」\n問:傍線部はどういうことか。最も適当なものを選ぼう。\nア 庭師が枝を切るように、人はいやな出来事を進んで忘れるべきだということ。\nイ 人は多くの出来事を忘れることで、残った出来事から自分らしさを形づくっており、忘却は記憶にとって欠かせない働きだということ。\nウ 記憶には限界があるので、人はすべての出来事を覚えておくことができないということ。\nエ 木が健やかに育つためには、枝を切って形を整えることが必要だということ。', hint: '「庭師・枝・木」は、記憶の話では何に対応するでしょう。傍線部の「欠陥ではなく」という対比にも注意します。', steps: ['対応表を作る。庭師が枝を切る ⇔ 人が多くを忘れる。残った枝 ⇔ くり返し思い出す出来事。木の形 ⇔ 自分という形(自分らしさ)。', '傍線部の対比を確かめる。「欠陥(悪いもの・足りないもの)」⇔「働きそのもの(必要な働き)」。忘れることは、悪いことではなく、記憶にとって必要な働きだ、という逆説。', 'エは、たとえ(木と枝)の側のまま説明しているので、傍線部の説明になっていない。消す。', 'ウは、「記憶には限界がある」と、忘れることを欠陥(足りないもの)としてとらえていて、傍線部の「欠陥ではなく」と逆。消す。アは「いやな出来事を進んで忘れるべき」と、本文にない内容(いやな出来事・べき)を加えている。消す。', 'イは、忘れることで自分らしさが形づくられる(対応表どおり)、忘却は記憶に欠かせない働き(対比どおり)と、両方を正しく説明している。'], a: 'イ', check: 'イを傍線部に当てはめて、本文の流れ(庭師のたとえ→記憶の説明→結論)とつながるかを確かめます。また、ウが「一般論(忘れることは記憶の欠陥だ)」そのものであることに気づくと、筆者が否定している考えを選ばせる典型的な誤答だと分かります。' }] }
    ],
    drill: [
      { lv: 2, q: '(作例)「楽譜は音楽そのものではない。演奏されてはじめて、音楽は生まれる。法律の条文もまた、それだけでは正義ではない。」\nこの文章の類比で、「楽譜」と「演奏」は、法律の側ではそれぞれ何に対応すると考えられるか。', a: '楽譜=法律の条文。演奏=条文を実際の出来事に当てはめて使うこと(裁判などで適用すること)。', exp: '類比の対応を考えるときは、まず本文にはっきり書かれている対応(楽譜⇔条文)を確かめ、次に書かれていない対応を推理します。\n楽譜は、書かれているだけでは音にならず、演奏されてはじめて音楽になります。同じように、法律の条文は、書かれているだけでは正義を実現せず、実際の出来事に当てはめて使われることで、はじめて正義が生まれる、というのが筆者の考えだと推理できます。\n「演奏」に対応する語は本文に書かれていませんが、類比の筋道から、「条文を実際に使うこと」と考えるのが自然です。入試では、このように書かれていない対応を選択肢から選ばせる問題も出ます。' },
      { lv: 3, q: '(作例)「翻訳は、ある言語の器から別の言語の器へ、水を移しかえる作業に似ている。どれほど注意深く移しても、こぼれる水は必ずある。しかし、移しかえなければ、その水は、元の器を持つ人のほかには、だれののどもうるおさない。」\n筆者は翻訳についてどのように考えているか。類比の対応をふまえて説明しよう。', a: '翻訳では、元の言語のもつ意味や味わいのすべてを別の言語に移すことはできず、必ず失われるものがあるが、それでも翻訳しなければ、その文章の内容は元の言語を知る人以外には伝わらないので、翻訳には大きな価値があると考えている。', exp: '対応表を作ると、次のようになります。器=言語、水=文章の意味や味わい、こぼれる水=翻訳で失われる部分、のどをうるおす=文章の内容が読者に伝わり、役立つこと。\nこの文章は、「こぼれる水は必ずある」(翻訳の限界)と「移しかえなければ、だれののどもうるおさない」(翻訳の価値)を、「しかし」でつないでいます。筆者の主張は、逆接の後ろの「翻訳の価値」のほうに重心があります。\n答えでは、「器」「水」などのたとえの言葉を使わず、「言語」「意味」「伝わる」などの主張の側の言葉で説明することが大切です。限界と価値の両方を書くと、筆者の考えを正確に表せます。' },
      { lv: 3, q: '評論で、類比(たとえ)を使った説明には、どのような利点と危険があるか。説明しよう。', a: '利点:むずかしい抽象的な考えを、読者がよく知っている身近なものに置きかえることで、直感的に分かりやすくできる。危険:たとえの側の性質を、主張の側にもそのまま当てはまると思いこませてしまうことがある。本当は似ていない部分まで似ているように感じさせ、筆者の主張を実際以上にもっともらしく見せることがある。', exp: '類比は、強力な説明の道具です。「記憶は庭のようだ」と言われると、記憶の働きが目に見えるように分かります。\nしかし、どんなたとえも、すべての点で似ているわけではありません。たとえば、庭師は意図して枝を切りますが、人は意図して出来事を忘れるとはかぎりません。たとえの側の性質(意図して切る)をそのまま主張の側に当てはめると、誤った理解につながります。\n評論を読むときは、類比の分かりやすさに引きこまれるだけでなく、「どこまでが似ていて、どこからは似ていないか」を考える姿勢が大切です。これは、自分で小論文を書くときにも役立つ見方です。' }
    ],
    faq: [
      ['類比と比喩は、どうちがうの?', '比喩は、「雪のような肌」のように、あるものを別のものにたとえて表現する方法全体を指します。類比は、比喩の中でも、二つのものの「関係やしくみ」が似ていることを使って、論理的に説明する方法です。「地図が土地の一部を選ぶように、言葉は経験の一部を選ぶ」のように、複数の要素の対応関係があるのが類比の特徴です。評論で類比が出てきたら、一つの言葉の置きかえではなく、対応表を作ることを意識しましょう。'],
      ['類比の部分は、具体例と同じように読み飛ばしてもいいの?', '読み飛ばさないほうがよいです。類比は具体例と同じく、主張を説明するための材料ですが、傍線部が引かれやすい部分でもあります。また、類比の中に、筆者の主張の大事な要素(何が選ばれ、何が捨てられるか、など)が込められていることが多いです。ただし、読むときは、たとえの話そのものを理解するのではなく、主張の側に置きかえるとどうなるかを考えながら読むことが大切です。']
    ]
  });

  add('kt_bun', {
    secs: [
      { h: 'さらに深く:会話の「ずれ」に心情が隠れている', t: '小説の会話は、情報を伝えるためだけに書かれているのではありません。むしろ、【言葉どおりの意味と、本当に言いたいことのずれ】に、人物の心情が表れることが多いのです。共通テストの文学的文章でも、会話の言外の意味を問う設問がよく出ます。\n会話のずれには、次のような型があります。\n①【答えになっていない返事】…問いに正面から答えず、別の話をする。例:「試験、どうだった?」「……今日の夕飯、何?」。答えたくない(結果がよくなかった、触れられたくない)気持ちが読みとれます。\n②【言葉と状況の不一致】…状況にそぐわない言葉を言う。例:大事な試合に負けた直後に「いい天気だな」とつぶやく。気持ちの整理がつかず、言葉が見つからない状態を表します。\n③【くり返し】…同じ言葉をくり返す。例:「そう、そうなんだ」。相手の言葉を受けとめようとしているが、すぐには受け入れられない動揺を表すことがあります。\n④【言いかけてやめる】…「あの、実は……いや、何でもない」。言いたいことがあるのに、言えない葛藤を表します。\nこうしたずれを読むときは、【相手の言葉 → 返事 → 前後の行動】の三つを並べ、「なぜ、この人物はこう答えたのか」を考えます。そのうえで、【言葉の表面の意味】と【その奥の気持ち】を分けて説明すると、選択肢を選ぶときにも、記述で答えるときにも根拠のある答えになります。', key: '会話のずれ(答えない返事・場違いな言葉・くり返し・言いかけ)は心情のサイン。相手の言葉・返事・前後の行動を並べ、表面と奥の気持ちを分けて説明する。', ex: [{ q: '(作例)「『引っこしの日、決まったんだ』と真紀が言うと、陽菜は窓の外を見たまま、『ふうん。あ、見て、ひこうき雲』と言った。真紀は何も言わずに、陽菜と同じ空を見上げた。」\n陽菜の返事から読み取れる気持ちと、真紀の行動の意味を説明しよう。', hint: '陽菜は、引っこしの話に正面から答えていますか。', steps: ['会話を並べる。真紀:引っこしの日が決まった(大事な知らせ)。陽菜:「ふうん」と短く受けたあと、ひこうき雲の話に変える。', '陽菜の返事は、大事な知らせに正面から答えていない「答えになっていない返事」の型。窓の外を見たまま(真紀の顔を見ない)という行動もそえられている。', '陽菜は、真紀との別れがつらく、その話を正面から受けとめることができないので、別の話に気をそらそうとしていると読める。', '真紀の「何も言わずに、同じ空を見上げた」は、陽菜の気持ちを察して、それ以上話を続けず、そばに寄りそおうとする行動と読める。'], a: '陽菜は、真紀が引っこすことをさびしく思い、その話を正面から受けとめられずに、わざと別の話に気をそらしている。真紀は、陽菜のそうした気持ちを察して、それ以上何も言わず、同じ空を見ることで陽菜に寄りそおうとしている。', check: '陽菜の気持ちを「真紀の引っこしに興味がない」とすると、「窓の外を見たまま」という、顔を合わせないしぐさの意味が説明できません。真紀の反応(何も言わずに寄りそう)とも合うかで確かめます。' }] },
      { h: '実戦演習:会話と行動から、二人の関係の変化を読む', t: '共通テストの文学的文章では、登場人物どうしの関係が、場面の中でどう変化したかを問う設問が出ます。戦略は次のとおりです。\n①場面の【はじめ】と【終わり】で、二人の会話の調子(よそよそしい・打ちとける など)と、距離(物理的な距離・視線)を比べます。\n②変化の【きっかけ】となった言葉や行動を探します。\n③選択肢は、「はじめの状態」「きっかけ」「終わりの状態」の三つがすべて本文と合うかで判断します。\n落とし穴は、関係の変化を大げさに読みすぎることです。小説では、「完全に仲直りした」のではなく、「少しだけ歩み寄った」程度の変化がえがかれることが多いので、選択肢の言葉の強さに注意しましょう。', key: '関係の変化は「はじめ・きっかけ・終わり」の三点で確かめる。変化の大きさを本文以上に強く言う選択肢を消せるかで差がつく。', ex: [{ q: '次の作例の文章を読んで答えよう。\n「父と二人で釣りに来るのは、三年ぶりだった。車の中でも、父はラジオのニュースを聞いているだけで、ぼくに話しかけなかった。ぼくも、窓の外ばかり見ていた。\n川べりに並んで糸をたらしても、しばらくはどちらも黙っていた。やがて父の竿が大きくしなった。父はあわてて立ち上がり、足をすべらせて浅瀬にしりもちをついた。ずぶぬれの父と目が合った。次の瞬間、二人は同時にふき出した。\n『昔、お前も同じことをしたな』と父が言った。『覚えてないよ』とぼくは言ったが、本当は覚えていた。」\n問:この場面での「ぼく」と父の関係の変化の説明として最も適当なものを選ぼう。\nア はじめは互いに口をきかなかったが、父の失敗をきっかけに笑い合い、昔のことを話題にできるほどには打ちとけた。\nイ はじめは仲が悪かったが、父の失敗をきっかけに、すべてのわだかまりが解けて、何でも話せる親子にもどった。\nウ はじめから仲がよかったが、父の失敗を見て、「ぼく」は父を少し軽く見るようになった。\nエ はじめは互いに口をきかなかったが、魚が釣れたことをきっかけに、父が「ぼく」をほめるようになった。', hint: 'はじめ・きっかけ・終わりの三点で、選択肢を本文と照らし合わせましょう。', steps: ['はじめの状態:車の中でも川べりでも、二人は黙っている。話しかけない、窓の外を見る、という距離のある関係。', 'きっかけ:父がしりもちをついてずぶぬれになり、目が合って二人が同時にふき出したこと。魚が釣れたことではない。', '終わりの状態:父が昔の話をし、「ぼく」は「覚えてない」と言いながら本当は覚えていた。昔の話ができるほどには近づいたが、まだ素直にはなりきれていない。', 'イは「すべてのわだかまりが解けて、何でも話せる」が言いすぎ(「ぼく」は本当のことを言っていない)。ウは「はじめから仲がよかった」「軽く見る」が本文と合わない。エはきっかけが誤り。', 'アは、はじめ・きっかけ・終わりの三点とも本文と合い、変化の程度(打ちとけた「ほどには」)も適切。'], a: 'ア', check: '最後の「『覚えてないよ』とぼくは言ったが、本当は覚えていた」は、関係が近づいたことと、まだ照れくさくて素直になれないことの両方を示しています。イのような「完全な仲直り」を否定する根拠になることを確かめましょう。' }] }
    ],
    drill: [
      { lv: 2, q: '(作例)「『絵、上手になったね』と先生が言うと、拓海は『べつに』と言って、絵をくるくると丸めた。けれど、その日の帰り道、拓海の足取りはいつもより軽かった。」\n拓海の「べつに」という返事には、どんな気持ちが隠れているか説明しよう。', a: '先生にほめられて本当はうれしいが、それを素直に表すのが照れくさいので、そっけない返事をしている。', exp: '「べつに」という言葉だけを見ると、ほめられても何とも思っていないように見えます。しかし、「その日の帰り道、拓海の足取りはいつもより軽かった」という後の行動から、拓海が実はうれしく思っていたことが分かります。\n「けれど」という逆接は、前の態度(そっけない)と後の様子(うれしそう)が食いちがっていることを示す合図です。\n言葉の表面(興味がない)と、その奥の気持ち(うれしい・照れくさい)を分けて説明しましょう。「絵を丸めた」というしぐさも、照れかくしの行動として読むことができます。' },
      { lv: 3, q: '(作例)「入院している祖母を見舞うと、祖母は『庭のあじさい、今年も咲いたかい』とだけたずねた。わたしは、まだつぼみだったのを知っていたが、『うん、きれいに咲いてるよ』と答えた。」\n「わたし」の返事について、言葉と事実のずれを指摘し、そこから読み取れる気持ちを説明しよう。', a: 'ずれ:実際にはあじさいはまだつぼみなのに、「きれいに咲いてるよ」と事実とちがうことを答えている。気持ち:入院している祖母を安心させ、喜ばせたいという思いやりの気持ち。(祖母が早く元気になって、咲いた花を見てほしいという願いも読み取れる。)', exp: '「わたし」は、あじさいがまだつぼみだと知りながら、「咲いている」と答えています。これは、相手を傷つけたり心配させたりしないための、思いやりからのうそと読めます。\n祖母が「とだけたずねた」とあることにも注目しましょう。入院中の祖母にとって、庭のあじさいは家や元気だったころの暮らしを思い出させるものであり、その質問には、家に帰りたいという気持ちがこめられているとも考えられます。\n「わたし」の返事は、そうした祖母の気持ちを察したうえでのものだと説明すると、より深い読みになります。ただし、本文に書かれていないこと(祖母の病気が重い、など)は断定しないようにしましょう。' },
      { lv: 3, q: '(作例)「『もう、いいよ』と兄は言った。弟は『いいって、何が』と聞き返したが、兄はそれ以上答えず、弟がこわした模型の部品を、一つずつ箱にしまいはじめた。」\n兄の「もう、いいよ」という言葉の言外の意味を、兄の行動をふまえて二通り考え、本文からより適当なほうを選んで理由を説明しよう。', a: '考えられる意味:①もう怒っていない、ゆるす。②もうお前には期待しない、あきらめた。より適当なのは①。理由:兄は、こわされた模型の部品を捨てずに「一つずつ」ていねいに箱にしまっており、怒りをぶつけたり投げ出したりするのではなく、出来事を静かに受け入れようとしている様子がうかがえるから。(ただし、部品を片づける行動には、残念に思う気持ちもふくまれている。)', exp: '「もう、いいよ」は、文脈によって「ゆるす」とも「あきらめる・見放す」とも取れる、あいまいな言葉です。このような言葉は、前後の行動から意味を決めます。\n兄が部品を「一つずつ箱にしまいはじめた」という行動は、こわれた模型を大切に扱っていることを示しています。また、弟を責める言葉が続かないことから、怒りをおさめようとしていると読むのが自然です。\n一方で、「それ以上答えず」という部分には、悲しさや残念な気持ちを言葉にしきれない様子も表れています。入試の選択肢では、「ゆるし」と「残念さ」の両方をふくむものが正解になることも多いので、気持ちを一つにしぼりすぎないことも大切です。' }
    ],
    faq: [
      ['会話文の言外の意味を読みすぎてしまうことはない?', 'あります。すべての会話に隠れた意味があるわけではありません。言外の意味を考えてよいのは、会話にずれ(答えになっていない、状況に合わない、くり返す、言いかける など)があるときや、前後の行動と言葉が食いちがっているときです。ずれがなければ、言葉どおりに受けとってかまいません。読みすぎを防ぐには、自分の解釈の根拠になる本文の言葉を、必ず一つ以上挙げられるかを確かめましょう。'],
      ['関係の変化を問う問題で、選択肢の言葉の強さはどう判断するの?', '本文の最後の場面で、二人の関係がどこまで近づいた(または離れた)かを、具体的な言葉や行動で確かめます。「笑い合った」「昔の話をした」程度なら、「少し打ちとけた」くらいが適切で、「すべて解決した」「完全に理解し合えた」は言いすぎです。とくに、最後に素直になれない様子(照れ・うそ・言いかけ)が書かれているときは、関係の変化がまだ途中であることを示しています。']
    ]
  });

  add('kt_jitsu', {
    secs: [
      { h: 'さらに深く:規約・案内の「条件」と「例外」を正確に読む', t: '実用的文章の大問では、図書館の利用案内、施設の規約、募集要項など、【きまりを説明する文章】がよく使われます。こうした文章で大切なのは、【条件】と【例外】を正確に読み取ることです。\n①【条件を示す言葉】…「〜の場合は」「〜に限り」「〜のときのみ」「〜以上」「〜未満」「〜までに」など。とくに数の範囲は、「以上・以下」(その数をふくむ)と「未満・超える」(その数をふくまない)を区別します。例:「十八歳未満」は十八歳をふくまないので、十七歳以下のことです。\n②【例外を示す言葉】…「ただし」「なお」「〜を除く」「この限りではない」など。「ただし」の後ろには、前に述べた原則が当てはまらない場合が書かれています。\n③【複数の条件の組み合わせ】…「AかつB」(両方を満たす)と「AまたはB」(どちらか一方でよい)のちがいに注意します。「市内在住または在勤の方」は、市内に住んでいるか、市内で働いているかのどちらかでよい、という意味です。\n設問では、ある人物の状況(年齢、住所、日時など)が示され、「この人はサービスを利用できるか」「料金はいくらか」と問われることが多いです。解くときは、【原則 → 条件 → 例外】の順に、人物の状況を一つずつ当てはめていきます。例外を見落とすと、計算や判断がすべてずれてしまうので、「ただし」「なお」には必ず印をつけましょう。', key: '「以上・以下」と「未満・超える」、「かつ」と「または」を区別し、「ただし」「なお」の例外に必ず印をつける。原則→条件→例外の順に当てはめる。', ex: [{ q: '(作例)ある市民プールの利用案内\n「利用料金:一般 400円、中学生以下 200円。ただし、六歳未満は無料(保護者の同伴が必要)。市内在住または在学の六十五歳以上の方は、一般料金の半額とします。なお、毎月第二日曜日は、中学生以下無料です。」\n次の人たちが、第二日曜日に一緒に利用するときの料金の合計はいくらか。\n・母(四十歳、市内在住) ・兄(中学二年生) ・妹(五歳) ・祖父(七十歳、市外在住)', hint: 'それぞれの人に、原則→条件→例外の順に当てはめます。祖父の住所に注意しましょう。', steps: ['母:四十歳なので一般料金。特別な条件は当てはまらないので400円。', '兄:中学生なので原則は200円。ただし、「なお」以下の例外で、第二日曜日は中学生以下無料なので0円。', '妹:五歳は「六歳未満」に当てはまる(六歳をふくまない範囲に五歳は入る)ので無料。保護者(母)が一緒なので条件も満たす。0円。', '祖父:六十五歳以上だが、半額になる条件は「市内在住または在学」。祖父は市外在住で、在学もしていないので条件を満たさない。一般料金400円。', '合計:400+0+0+400=800円。'], a: '800円', check: '祖父を半額(200円)にして600円と答えるのが典型的な誤りです。「六十五歳以上」という条件だけでなく、「市内在住または在学」という条件を同時に満たす必要があることを確かめます。' }] },
      { h: '実戦演習:複数の資料を照らし合わせて、正しい記述を選ぶ', t: '実用的文章の大問では、案内文・表・グラフなど複数の資料を照らし合わせて、正しい説明を選ぶ問題が出ます。戦略は次のとおりです。\n①選択肢を一つずつ見て、それが【どの資料のどの部分】について述べているかを確かめます。\n②数値が出てきたら、必ず計算して確かめます。割合なら「何を全体としているか」を確かめます。\n③選択肢の中の【言い切りの言葉】(すべて・必ず・最も・〜だけ)に注意し、資料から本当にそう言えるかを確かめます。\n落とし穴は、資料に書かれていない原因や理由を、選択肢がつけ加えている場合です。資料から「分かること」と「推測にすぎないこと」を区別しましょう。', key: '選択肢ごとに根拠の資料を特定し、数値は必ず計算、言い切りの言葉は疑う。資料にない因果を加えた選択肢を見ぬけるかで差がつく。', ex: [{ q: '(作例)ある高校の図書室の資料\n資料1(案内):「貸出冊数は一人五冊まで、期間は二週間。ただし、長期休業前の一週間は、十冊まで、休業明けまで借りられます。」\n資料2(表):月別の貸出冊数 四月 300冊、五月 360冊、六月 270冊、七月 540冊\n問:資料から読み取れることとして最も適当なものを選ぼう。\nア 七月の貸出冊数は、四月の貸出冊数の二倍をこえている。\nイ 五月の貸出冊数は、四月に比べて二割増えている。\nウ 七月の貸出冊数が多いのは、生徒が夏休みの課題のために本を借りたからである。\nエ 六月の貸出冊数は、四月から七月の中で二番目に多い。', hint: '数値は必ず計算します。ウは、資料から本当に言えることですか。', steps: ['ア:七月540冊÷四月300冊=1.8倍。二倍をこえていないので誤り。', 'イ:五月360冊−四月300冊=60冊。60÷300=0.2なので二割増え。正しい。', 'ウ:資料1から、長期休業前は多く借りられることは分かるが、「夏休みの課題のため」という理由は資料に書かれていない。推測にすぎないので不適当。', 'エ:多い順に並べると、七月540、五月360、四月300、六月270。六月は最も少ないので誤り。', 'よって、資料から確実に読み取れるのはイ。'], a: 'イ', check: 'イは、増えた量(60冊)を「もとの量」(四月の300冊)で割って割合を出しています。五月の360冊で割ると約17%となり、誤った判断になります。増加率は、必ず「比べる前の量」を全体として計算することを確かめましょう。' }] }
    ],
    drill: [
      { lv: 2, q: '(作例)「本講座の対象は、市内在住かつ二十歳以上の方です。」この講座を受けられるのは、次のうちだれか。すべて選ぼう。\nア 市内在住の十九歳 イ 市外在住の二十五歳 ウ 市内在住の二十歳 エ 市内在勤で市外在住の三十歳', a: 'ウ', exp: '「かつ」は、二つの条件を両方とも満たす必要があることを表します。この講座の条件は、①市内在住、②二十歳以上、の両方です。\nアは①を満たしますが、十九歳なので②を満たしません。イは二十歳以上ですが、市外在住なので①を満たしません。エは市内で働いていますが、住んでいるのは市外なので①を満たしません(「在勤」は条件にふくまれていません)。\nウは市内在住で、二十歳です。「以上」はその数をふくむので、二十歳は条件を満たします。もし条件が「または」なら、ア・イ・ウ(エは年齢は満たす)と大きく変わります。「かつ」と「または」を読み分けることが大切です。' },
      { lv: 3, q: '(作例)ある美術館の料金案内「一般1200円、大学生800円、高校生以下無料。二十名以上の団体は、一般・大学生の料金から二割引きとします。ただし、高校生以下は団体の人数にふくめません。」\n一般十五名、大学生三名、高校生五名のグループで入館するときの料金の合計を求めよう。', a: '20400円', exp: 'まず、団体割引が使えるかどうかを確かめます。グループは全部で23名ですが、「ただし」以下の例外により、高校生以下は団体の人数にふくめません。そのため、人数に数えるのは一般十五名+大学生三名=十八名です。二十名に届かないので、団体割引は使えません。\n料金は、一般1200円×15名=18000円、大学生800円×3名=2400円、高校生は無料なので0円です。合計は18000+2400=20400円になります。\nもし高校生を人数にふくめて二割引きにすると、(18000+2400)×0.8=16320円となり、誤りです。「ただし」の例外が、割引の条件そのものを変えていることに注意しましょう。' },
      { lv: 3, q: '(作例)ある町の資料「図書館の利用者数:二〇二〇年 8000人、二〇二四年 10000人。町の人口:二〇二〇年 40000人、二〇二四年 50000人。」\nある生徒が「利用者数が二五%増えたので、町の人たちは以前より図書館をよく使うようになった」と述べた。この意見の問題点を、計算をもとに説明しよう。', a: '利用者数は8000人から10000人へ二五%増えているが、町の人口も40000人から50000人へ二五%増えている。人口に対する利用者の割合は、二〇二〇年が8000÷40000=二〇%、二〇二四年が10000÷50000=二〇%で変わっていない。したがって、利用者数の増加は人口の増加によるものと考えられ、町の人たちが以前より図書館をよく使うようになったとは言えない。', exp: '実数(人数)が増えたからといって、一人ひとりの行動が変わったとはかぎりません。全体の人数(人口)が増えれば、同じ割合の人が利用していても、利用者数は増えます。\nこの問題では、利用者数の増加率(10000−8000)÷8000=0.25と、人口の増加率(50000−40000)÷40000=0.25が同じです。そのため、人口に対する利用者の割合は、どちらの年も二〇%で変わっていません。\n実用的文章の問題では、このように「実数」と「割合」を区別して考えることがよく求められます。「増えた」という意見を見たら、何に対する割合で見ると変化があるのかを確かめる習慣をつけましょう。' }
    ],
    faq: [
      ['「以上」「以下」「未満」は、なぜまちがえやすいの?', 'ふだんの会話では、これらの言葉をあまり区別せずに使うことがあるからです。しかし、規約や法律では厳密に区別されています。「以上」「以下」は、基準の数をふくみます(二十歳以上=二十歳もふくむ)。「未満」「超える」は、基準の数をふくみません(十八歳未満=十八歳はふくまない)。迷ったら、基準の数ちょうどの人が条件に入るかどうかを、具体的に考えてみると確かめられます。'],
      ['資料の問題で、「推測」の選択肢はいつも誤りなの?', '「資料から読み取れること」を問う設問では、資料に書かれていない理由や原因を述べた選択肢は、ふつう誤りになります。ただし、設問が「資料をふまえて考えられること」「推測できること」を問うている場合は、資料を根拠にした妥当な推測が正解になることもあります。設問の文末が「読み取れること」なのか「考えられること」なのかを必ず確かめ、それに合った基準で選択肢を判断しましょう。']
    ]
  });

  add('kt_ko', {
    secs: [
      { h: 'さらに深く:会話文と「心内文」の範囲を見きわめる', t: '古文には、かぎかっこ(「」)のない文章が多く、【どこからどこまでが会話か、心の中の思いか】を自分で判断する必要があります。とくに、声に出さない心の中の思いを【心内文】といい、共通テストではその範囲や内容がよく問われます。\n範囲を見きわめる手がかりは次のとおりです。\n①【終わりの目印】…会話文・心内文の終わりには、「と」「とて」「など」がくることが多く、その後に「言ふ」「思ふ」「おぼゆ」「聞こゆ」などの動詞が続きます。「〜と思ひて」「〜とて」を見つけたら、その直前が会話・心内文の終わりです。\n②【始まりの目印】…始まりには決まった目印がないので、【文の調子が変わるところ】を探します。たとえば、地の文の「けり」(過去)から、会話文の「む」(推量)や「侍り」(丁寧語)に変わるところが始まりになりやすいです。また、「いかで」「あはれ」などの感情をこめた言葉や、呼びかけの言葉も始まりの手がかりになります。\n③【敬語の変化】…地の文では作者の立場で敬語が使われますが、会話文・心内文では話し手(思う人)の立場で使われます。敬語の使い方が急に変わったら、そこから会話や心内文が始まっている可能性があります。\n範囲が分かったら、【だれの言葉・思いか】を確かめます。「と思ふ」の主語が、心内文の主です。心内文の中では、思っている人自身の動作に敬語はつかないので、敬語のない動作の主語は、その人自身であることが多いのです。', key: '会話文・心内文の終わりは「と・とて・など」+「言ふ・思ふ」。始まりは文の調子・敬語の変わり目で探す。心内文の中の敬語のない動作は、思っている本人の動作であることが多い。', ex: [{ q: '次の作例の古文で、心内文を抜き出し、だれの思いかを答えよう。\n「姫君、月をながめたまひて、いかでかの人に今ひとたび会はむ、と思しけり。」\n(ながむ=物思いにふけって見る。思す=お思いになる)', hint: '「と思しけり」の直前が心内文の終わりです。始まりは、文の調子が変わるところを探します。', steps: ['終わりの目印を探す。「と思しけり」の「と」の直前、「会はむ」までが心内文。', '始まりを探す。「ながめたまひて」までは地の文(尊敬語「たまふ」で姫君を高めている)。「いかで」(なんとかして)という願いをこめた言葉から調子が変わる。', 'よって心内文は「いかでかの人に今ひとたび会はむ」。', '「思し」は「思ふ」の尊敬語で、主語は前の「姫君」。心内文の中の「会はむ」には敬語がないので、姫君自身の動作と考えられる。', '意味は「なんとかしてあの人にもう一度会いたい」。'], a: '心内文:いかでかの人に今ひとたび会はむ。だれの思いか:姫君。(意味:なんとかしてあの人にもう一度会いたい)', check: '心内文の中の「会はむ」に尊敬語がついていないことと、思っている人が姫君であることが一致しているかを確かめます。地の文なら姫君の動作には「たまふ」がつくはずなので、敬語のちがいが範囲の根拠になります。' }] },
      { h: '実戦演習:心内文をふくむ場面の解釈を選ぶ', t: '共通テストの古文では、心内文の内容や、それをふまえた人物の行動の理由を問う問題が出ます。戦略は次のとおりです。\n①まず「と」「とて」+「思ふ・言ふ」を探し、会話文・心内文の範囲に印をつけます。\n②それぞれの会話・心内文が、だれのものかを確かめます。\n③心内文の内容を現代語にし、その後の行動とつながるかを確かめます。\n④選択肢は、「だれの思いか」「思いの内容」「行動との関係」の三点で照らし合わせます。\n落とし穴は、心内文の主を、直前に出てきた別の人物と取りちがえることです。心内文の後の「思ふ」「思す」の敬語の有無も、主を決める手がかりになります。', key: '「と思ふ/と思す」の敬語の有無で心内文の主を確かめ、思いと行動のつながりで選択肢を判断できるかで差がつく。', ex: [{ q: '次の作例の古文を読んで答えよう。\n「ある女房、宮の御前にて、歌を詠めと仰せられけれど、よき歌も思ひ浮かばざりければ、いかがせむ、人に笑はれなむ、と思ひて、ただうつぶして候ひけり。宮、これを御覧じて、さらば明日までに詠め、とのたまはせけり。」\n(宮=身分の高い女性。候ふ=おそばに控える)\n問:女房が「うつぶして候ひけり」とあるのはなぜか。最も適当なものを選ぼう。\nア 宮の歌があまりにすばらしく、感動して顔を上げられなかったから。\nイ よい歌が浮かばず、どうしようもなく、人に笑われてしまうだろうと思ったから。\nウ 宮に笑われたことがはずかしく、顔を見せたくなかったから。\nエ 明日まで待ってもらえることになり、ほっとしたから。', hint: '「と思ひて」の前の心内文を探し、その内容を訳してみましょう。', steps: ['会話・心内文の範囲を確かめる。「歌を詠め」(宮の言葉)、「いかがせむ、人に笑はれなむ」(と思ひて=心内文)、「さらば明日までに詠め」(とのたまはせけり=宮の言葉)。', '心内文「いかがせむ、人に笑はれなむ」の主は、「と思ひて」に敬語がないことと文の流れから、女房。', '心内文を訳す。「いかがせむ」=どうしようか(どうしようもない)。「笑はれなむ」=笑は(未然形)+れ(受身)+な(強意)+む(推量)=きっと笑われてしまうだろう。', 'その直前に「よき歌も思ひ浮かばざりければ」(よい歌も思い浮かばなかったので)とあり、思いと行動(うつぶす)がつながる。', 'アは歌を詠むのは女房のほうなので誤り。ウは「宮に笑われた」とあるが、まだ笑われていない(推量)。エは宮の言葉の後のことで、うつぶした理由ではない。イが正しい。'], a: 'イ', check: 'ウの誤りは、「なむ」を完了(笑われてしまった)と取りちがえたものです。「な+む」は強意+推量で、まだ起きていない未来のことを表すので、「笑われてしまうだろう」と訳すことを確かめましょう。また、宮の言葉に「のたまはせ」(最高敬語)が使われていることから、敬語で人物を区別できることも確認できます。' }] }
    ],
    drill: [
      { lv: 2, q: '作例「翁、この子を見て、我が子となるべき人なめり、とて、手にうち入れて家へ持ちて来ぬ。」の会話文(心内文)を抜き出そう。また、「なめり」はどのような形が変化したものか答えよう。', a: '会話文(心内文):我が子となるべき人なめり。「なめり」=断定の助動詞「なり」の連体形「なる」+推定の助動詞「めり」。「なるめり」が撥音便で「なんめり」となり、「ん」が表記されずに「なめり」となったもの。', exp: '「とて」の直前が、会話文(または心内文)の終わりです。始まりは、「見て」の後で、文の調子が「〜べき人なめり」という推定の言い方に変わるところです。\n「なめり」は、古文でよく出る形です。断定「なり」の連体形「なる」に推定「めり」がつき、「なるめり」→「なんめり」(撥音便)→「なめり」(撥音の無表記)と変化しました。訳は「〜であるようだ」です。同じように「ななり」は「なるなり」(〜であるそうだ・〜であるようだ)、「あめり」は「あるめり」です。\n「とて」は「〜と言って」「〜と思って」の両方の意味があり、声に出したかどうかは文脈で判断します。' },
      { lv: 3, q: '作例「中将、文を見たまひて、あな心憂、などかくは書きけむ、とうち嘆きたまふ。」について、(1)心内文(会話文)を抜き出し、(2)だれの思いかを答え、(3)「書きけむ」の主語として考えられる人物を、敬語に注目して説明しよう。', a: '(1)あな心憂、などかくは書きけむ (2)中将 (3)手紙を書いた人(中将以外の人物)。心内文の中では、話し手(中将)から見た敬語が使われる。「書き」に尊敬語がないので、中将が尊敬語を使う必要のない人物(中将と同等か、目下の人物)と考えられる。また、中将が手紙を読んで嘆いているので、書いたのは中将自身ではなく、手紙の送り主である。', exp: '「と」の直前の「書きけむ」までが心内文で、始まりは感動詞「あな」(ああ)です。思っているのは、「うち嘆きたまふ」の主語の中将です。\n心内文「あな心憂、などかくは書きけむ」は、「ああ情けない、どうしてこのように書いたのだろうか」という意味です。「けむ」は過去の原因推量で、「など」(どうして)とセットになっています。\n「書き」の主語は文中に書かれていませんが、中将が手紙を「見て」嘆いていることから、手紙の送り主だと分かります。心内文の中の敬語は、思う人(中将)の立場で使われるので、「書きたまひけむ」とならないことから、送り主は中将が敬語を使わない相手だと推理できます。' },
      { lv: 3, q: '心内文の主を判断するとき、「と思ふ」と「と思す」のちがいは、どのように手がかりになるか。説明しよう。', a: '地の文では、作者が身分の高い人物の動作に尊敬語を使う。「と思す」(尊敬語)なら、心内文の主は作者が敬意を払う身分の高い人物であり、「と思ふ」(敬語なし)なら、身分の低い人物や、作者が敬語を使わない人物であると判断できる。登場人物の身分が分かっていれば、この敬語の有無で、心内文の主をしぼりこめる。', exp: '心内文の後に続く「思ふ」は地の文の一部なので、作者の立場から敬語が使われます。身分の高い人(帝・中宮・大臣・姫君など)の思いなら「思す」「思し召す」となり、身分の低い人(女房・従者など)の思いなら「思ふ」となります。\nたとえば、姫君と女房が同じ場面にいて、「〜と思ひけり」とあれば女房の思い、「〜と思しけり」とあれば姫君の思いである可能性が高いと考えられます。\nこのように、心内文の主を決めるときは、心内文の中身だけでなく、その後ろの「思ふ」の形にも注目しましょう。主語が書かれていないときほど、敬語が大きな手がかりになります。' }
    ],
    faq: [
      ['会話文と心内文は、どうやって区別するの?', '後ろに続く動詞で区別します。「と言ふ」「と申す」「とのたまふ」なら声に出した会話文、「と思ふ」「とおぼゆ」「と思す」なら心の中の思いである心内文です。「とて」だけで動詞がない場合は、「と言って」「と思って」のどちらとも取れるので、前後の場面(相手がいるか、だれかに聞こえているか)から判断します。どちらか迷うときは、その言葉にだれかが返事をしているかを確かめると、会話かどうかが分かります。'],
      ['心内文の範囲の始まりが、どうしても分かりません。', '終わりから逆にたどる方法がおすすめです。「と思ひて」の直前から一語ずつさかのぼり、「ここまでは心の中の言葉として自然か」を確かめます。地の文の特徴(過去の「けり」、作者からの敬語)が出てきたら、そこは地の文です。また、「あな」「いで」「いかで」などの感動詞や、願い・疑問の言葉は、心内文の始まりになりやすいです。現代語に訳して、「〜と思った」の「〜」に入れて自然かどうかで確かめると、範囲が決まります。']
    ]
  });

  add('kt_kan', {
    secs: [
      { h: 'さらに深く:対句から、分からない字の意味を推理する', t: '漢文には、【対句】(同じ組み立ての句を並べる表現)がとても多く使われます。対句は、形を整えて調子をよくするだけでなく、【意味を推理する手がかり】にもなります。対句では、同じ位置にある字どうしが、【似た意味】か【反対の意味】になっていることが多いからです。\n例:『孔子家語』の「良薬苦二於口一、而利二於病一。忠言逆二於耳一、而利二於行一。」(良薬は口に苦けれども病に利あり、忠言は耳に逆らへども行ひに利あり)\nこの文を対句として並べると、次のように対応しています。\n・良薬 ⇔ 忠言(よい薬 ⇔ 真心からの忠告)\n・苦二於口一 ⇔ 逆二於耳一(口に苦い ⇔ 耳に逆らう=聞いて不快だ)\n・利二於病一 ⇔ 利二於行一(病気に効く ⇔ 行いに役立つ)\nもし「逆」の意味が分からなくても、「苦」と同じ位置にあることから、「不快だ・受け入れにくい」という意味だと推理できます。また、「良薬」の話は「忠言」の話のたとえになっていて、筆者が本当に言いたいのは後半(忠告は聞きにくいが、行いのためになる)だと分かります。\n対句を見つけるコツは、【字数が同じで、同じ字(而・於・不 など)が同じ位置にある句】を探すことです。見つけたら、上下に並べて書き、対応する字どうしを線で結ぶと、意味の関係が見えてきます。共通テストでは、対句の一方に傍線が引かれ、もう一方を手がかりにして意味を答えさせる問題がよく出ます。', key: '対句では、同じ位置の字が似た意味か反対の意味になる。上下に並べて対応を確かめれば、分からない字の意味や筆者の重点を推理できる。', ex: [{ q: '『荘子』の「人皆知二有用之用一、而莫レ知二無用之用一也。」を書き下し文にし、意味を答えよう。また、この文の前半と後半の対応から、筆者が言いたいことを説明しよう。', hint: '「有用之用」と「無用之用」が対応しています。「莫」は「なし」と読みます。', steps: ['前半「人皆知二有用之用一」は「人皆有用の用を知る」と読む。「人はみな、役に立つものの役立ち方を知っている」。', '後半「莫レ知二無用之用一也」は「無用の用を知る莫きなり」と読む。「莫」は「なし」で、「役に立たないものの役立ち方を知る者はいない」。「而」は置き字で、ここでは逆接(しかし)の働き。', '対応を確かめる。人皆知 ⇔ 莫知(みな知っている ⇔ だれも知らない)、有用之用 ⇔ 無用之用(役に立つものの用 ⇔ 役に立たないものの用)。', '筆者が言いたいのは、後半の「無用の用」のほう。一見役に立たないものにも、実は大切な役立ち方があるのに、人々はそれに気づいていない、ということ。'], a: '書き下し文:人皆有用の用を知るも、無用の用を知る莫きなり。意味:人はみな、役に立つものの役立ち方は知っているが、役に立たないもの(と思われているもの)の役立ち方を知る者はいない。言いたいこと:一見役に立たないように見えるものにも、実は大切な役割があるのに、人々はそれに気づいていないということ。', check: '「有用」と「無用」、「皆知」と「莫知」が、それぞれ反対の意味で対応していることを確かめます。対句の両側が反対の意味のときは、筆者が否定している側(一般の人の考え)と、強調したい側(気づかれていない真実)を分けて考えましょう。' }] },
      { h: '実戦演習:対比の構造から本文の主張を説明する', t: '共通テストの漢文では、短い文章の中に対句や対比があり、その構造をふまえて筆者の主張を説明させる問題が出ます。戦略は次のとおりです。\n①本文の中の【対になっている句】を見つけ、上下に並べて対応をメモします。\n②対比の「両側」で、それぞれどんな結果になっているかを確かめます。\n③逆接の字(然・而・雖 など)の後ろに、筆者の意外な結論が来ていないかを確かめます。\n落とし穴は、対句の前半だけを読んで、ふつうの考え(前半)を筆者の主張と取りちがえることです。「然」「而」の後ろの、ひっくり返しに注意しましょう。', key: '対比の両側の「結果」を比べ、逆接の後ろの意外な結論をつかめるかで差がつく。', ex: [{ q: '次の作例の漢文を読んで答えよう。\n「木之直者、匠取以為レ梁。木之曲者、匠棄而不レ顧。然直木先伐、曲木独全二其天年一。」\n(匠=大工。梁=はり、屋根を支える横木。天年=天から与えられた寿命)\n(1)「曲木独全二其天年一」を書き下し文にしよう。(2)前半の二つの文の対応を説明しよう。(3)この文章は、何を言おうとしているか説明しよう。', hint: '(2)「直者」と「曲者」、「取」と「棄」が対応しています。(3)は「然」の後ろが大切です。', steps: ['(1)「全」に二点、「年」に一点があるので、「其天年」を読んでから「全」に返る。「曲木は独り其の天年を全うす」。', '(2)対応を並べる。木之直者 ⇔ 木之曲者(まっすぐな木 ⇔ 曲がった木)、匠取以為レ梁 ⇔ 匠棄而不レ顧(大工が取って梁にする ⇔ 大工が捨ててふり返らない)。', '前半の段階では、まっすぐな木は役に立ち、曲がった木は役に立たない、というふつうの価値判断が示されている。', '(3)逆接の「然」(しかれども)の後ろで結果が逆転する。まっすぐな木は先に切られてしまい、曲がった木だけが寿命をまっとうする。', '役に立たないとされるものが、かえって身を守り、長く生きることができる。つまり、役に立たないことにも価値がある(無用の用)ということを言おうとしている。'], a: '(1)曲木は独り其の天年を全うす。(2)まっすぐな木と曲がった木が対になり、まっすぐな木は大工に取られて梁として使われるのに対し、曲がった木は捨てられてふり返られない、という対比になっている。(3)人々に役立つとされるものはかえって早く切られて命を失い、役に立たないとされるものこそが身を守って寿命をまっとうできるのだから、役に立たないと思われることにも大きな価値がある、ということ。', check: '(3)を「まっすぐな木のほうが役に立つので価値がある」とすると、「然」の後ろの逆転を読み落としていることになります。対比の両側で、前半と後半の評価が入れかわっていることを確かめましょう。' }] }
    ],
    drill: [
      { lv: 2, q: '「良薬苦二於口一、而利二於病一」の「利」の意味を、対句になっている「忠言逆二於耳一、而利二於行一」と比べて答え、書き下し文にしよう。', a: '「利」=役に立つ・ためになる。書き下し文:良薬は口に苦けれども病に利あり。', exp: '対句の後半「利二於行一」(行ひに利あり)と並べると、「利」はどちらの句でも同じ位置にあり、「〜に利あり」=「〜のためになる・〜に役立つ」という意味で使われていることが分かります。\n「於」は置き字で読みませんが、「病に」「行ひに」と送り仮名「に」で働きを表します。\n「而」も置き字で読みませんが、ここでは逆接の働きをしていて、「苦けれども」と、前の部分を逆接の形で読みます。「而」は、文脈によって順接(〜して)にも逆接(〜けれども)にもなるので、前後の内容の関係から判断します。良い薬が口に苦いことと、病に役立つことは、逆の関係なので逆接と考えます。' },
      { lv: 3, q: '古くから伝わる言葉「水至清則無レ魚、人至察則無レ徒。」(至=きわめて、このうえなく。察=細かいところまで見ぬく。徒=仲間)\n書き下し文にし、意味を答えよう。また、前半と後半の対応から、筆者が言いたいことを説明しよう。', a: '書き下し文:水至つて清ければ則ち魚無く、人至つて察なれば則ち徒無し。意味:水があまりに清らかすぎると魚がすまず、人があまりに細かいところまで見ぬきすぎると仲間ができない。言いたいこと:前半の水と魚の話は、後半の人と仲間の話のたとえになっている。人は、他人の欠点を厳しく見ぬきすぎると、だれも寄りつかなくなるので、ある程度の寛容さが必要だということ。', exp: '対句を並べると、水 ⇔ 人、至清(きわめて清い) ⇔ 至察(きわめて細かく見ぬく)、無魚(魚がいない) ⇔ 無徒(仲間がいない)と対応しています。\n「則」は「すなはち」と読み、「〜ならば(そのときは)」という条件と結果を結びます。そのため、前の部分を「清ければ」「察なれば」と、已然形+ばで読みます。\n対句の前半(自然の話)と後半(人間の話)が対応しているとき、多くの場合、前半はたとえで、後半が本当に言いたいことです。水がきれいすぎると、えさや隠れ場所がなくなって魚がすめないように、人も厳しすぎると人が離れていく、という意味になります。' },
      { lv: 3, q: '対句を使った文章で、筆者の主張がどちらの句にあるかを判断するには、どのような手がかりがあるか。二つ挙げて説明しよう。', a: '①逆接の字(然・而・雖など)の位置:逆接の後ろの句に、筆者が強調したい意外な結論が来ることが多い。②たとえと主張の関係:自然や身近な物の話(水・木・薬など)と、人間や政治の話が対になっているときは、人間・政治の側が主張で、自然の側はたとえであることが多い。', exp: '対句は、二つの句が対等に並んでいるように見えますが、筆者の重点はどちらか一方にあることが多いです。\n一つめの手がかりは逆接です。「人皆知有用之用、而莫知無用之用」のように、「而」の後ろで一般の考えをひっくり返しているときは、後ろの句が主張です。\n二つめの手がかりは、たとえと主張の関係です。「良薬苦於口…忠言逆於耳…」では、薬の話は身近なたとえで、忠告の話が言いたいことです。\nこのほか、文章の最後にまとめの句があれば、そこが主張になります。対句を見つけたら、どちらに重点があるかを必ず考えるようにしましょう。' }
    ],
    faq: [
      ['対句は、漢詩だけのものではないの?', '漢詩だけのものではありません。漢詩の律詩では、決まった句を対句にするきまりがありますが、漢文の文章(散文)でも、対句はとてもよく使われます。思想家の言葉や歴史書の中で、主張をはっきりさせたり、調子をよくして覚えやすくしたりするために使われてきました。『論語』や『孟子』、『荘子』などにも多くの対句があります。文章の中で、字数と組み立てがそろった句を見つけたら、対句ではないかと考えてみましょう。'],
      ['対句の推理で、意味を決めつけてしまう危険はない?', 'あります。対句の同じ位置にある字は、似た意味か反対の意味であることが多いですが、どちらなのかは文脈で決まります。また、完全に対応していない対句もあります。対句から推理した意味は、必ず文全体に当てはめて、意味が自然に通るかを確かめましょう。注や設問文に語の意味が示されていれば、それを優先します。対句は、意味を決める唯一の根拠ではなく、有力な手がかりの一つと考えるのがよいでしょう。']
    ]
  });

  add('j_setsumei', {
    secs: [
      { h: 'さらに深く:説明の「順序」には理由がある', t: '説明的文章の筆者は、内容を思いつくままに並べているのではありません。読者に分かりやすく伝えるために、【説明の順序】を工夫しています。順序の型を知っていると、段落の並べかえ問題や、「なぜこの順で説明したのか」という問題が解きやすくなります。\n主な型は次の5つです。\n①【時間の順】…昔から今へ、作業の手順どおりに。例:米ができるまでを、田植え→稲刈り→脱穀の順に説明する。「まず」「次に」「やがて」などの言葉が目印です。\n②【空間の順】…外から内へ、上から下へ、近くから遠くへ。例:城のつくりを、堀→石垣→天守の順に説明する。\n③【原因から結果へ】…なぜそうなったかを先に示し、何が起きたかを後に示す。「そのため」「その結果」が目印です。\n④【一般から具体へ(またはその逆)】…まとめを先に述べてから例を挙げる、または例を重ねてからまとめる。\n⑤【身近なものから遠いものへ・簡単なものから難しいものへ】…読者がよく知っていることから始めて、知らないことへ進む。例:身近な冷蔵庫のしくみから始めて、地球の気候のしくみへ広げる。\n⑤は、とくに説明文で大切な順序です。読者は、知っていることを手がかりにして、新しいことを理解するからです。\n文章を読むときは、「なぜ筆者はこの例を最初に出したのか」と考えてみましょう。たいていは、読者にとって身近で分かりやすい例が先に置かれ、だんだん抽象的・専門的な内容へ進んでいきます。順序の意図が分かると、筆者が読者をどこへ導こうとしているのか、つまり主張の方向も見えてきます。', key: '説明の順序には「時間・空間・原因→結果・一般⇔具体・身近→遠い」の型がある。順序の意図を考えると、筆者が読者を導く先(主張)が見える。', ex: [{ q: '次の作例の文章について、例がこの順序で並べられている理由を説明しよう。\n「①コップに冷たい水を入れておくと、外側に水滴がつく。②冬の朝、窓ガラスの内側がくもることがある。③空に浮かぶ雲も、同じしくみでできている。④空気中の水蒸気は、冷やされると小さな水のつぶに変わるのである。」', hint: '①②③の例は、読者にとって身近なものからどう変わっていくでしょう。', steps: ['例を確かめる。①コップの水滴、②窓ガラスのくもり、③空の雲。④はそれらに共通するしくみ(まとめ)。', '①は手元のコップで、だれでもすぐに確かめられる身近な例。②は家の窓で、少し範囲が広がる。③は空の雲で、手の届かない大きな自然現象。', 'つまり、身近で小さなものから、遠くて大きなものへと順に並べられている。', '読者は、よく知っている①②を手がかりにして、③の雲のしくみも同じだと理解しやすくなる。最後に④でしくみをまとめている。'], a: '身近で小さな例(コップの水滴)から、少し広い例(窓のくもり)、遠くて大きな例(雲)へと順に並べることで、読者がよく知っている現象を手がかりに、雲のでき方も同じしくみだと理解しやすくするため。', check: '順序を逆にして、雲の話から始めた場合を考えてみます。読者はしくみを想像しにくく、理解に時間がかかるはずです。順序を入れかえたときの分かりにくさを考えると、筆者の意図を確かめられます。' }] },
      { h: '実戦演習:段落の並べかえと、順序の理由', t: '高校入試では、段落や文を正しい順に並べかえる問題や、文章の構成の特徴を説明する問題が出ます。戦略は次のとおりです。\n①並べかえる段落の【はじめの言葉】に注目します。接続語(また・しかし・つまり)や指示語(この・その)があれば、その前に何が来るかが決まります。\n②指示語の段落は、その指示内容をふくむ段落の【すぐ後】に置きます。\n③最後に、説明の順序の型(時間・原因→結果・身近→遠い など)に合っているかを確かめます。\n落とし穴は、内容だけで並べかえて、接続語や指示語の手がかりを見落とすことです。言葉の手がかりは、内容の判断よりも確かな根拠になります。', key: '段落のはじめの接続語・指示語で前後を決め、最後に順序の型で確かめる。言葉の手がかりを根拠にできるかで差がつく。', ex: [{ q: '次の作例のア〜エの段落を、正しい順に並べかえよう。また、そう判断した手がかりを説明しよう。\nア そのため、米は一年中食べられる、大切な保存食になった。\nイ 日本では、昔から米が主食として食べられてきた。\nウ 米は、よく乾燥させれば、長い間くさらずにたくわえておくことができる。\nエ このように、米が主食になった理由の一つには、たくわえやすいという性質があったのである。', hint: '「そのため」「このように」の前には、何が来なければなりませんか。', steps: ['話題を示す段落を探す。イ「日本では、昔から米が主食として食べられてきた」は、文章全体の話題を示しているので、最初に置く。', 'ウは米の性質(たくわえやすい)を説明していて、原因にあたる。', 'ア「そのため」は、前の内容を原因として結果を述べる言葉。原因はウなので、ウの後にアを置く。', 'エ「このように」は、それまでの内容をまとめる言葉。イ・ウ・アの内容(米が主食になった理由)をまとめているので最後に置く。', '順序はイ→ウ→ア→エ。話題→原因→結果→まとめで、原因から結果への順序の型にも合っている。'], a: 'イ→ウ→ア→エ。手がかり:アの「そのため」は原因(ウ)の後に、エの「このように」はまとめなので最後に来る。イは文章全体の話題を示すので最初に置く。', check: '並べた順に読んで、「主食だった→たくわえられる→だから保存食になった→このように、たくわえやすさが理由だった」と、話がなめらかにつながるかを確かめます。' }] }
    ],
    drill: [
      { lv: 2, q: '次の作例の文章は、どのような順序で説明されているか。型の名前を答えよう。\n「まず、たまねぎを細かく切る。次に、フライパンで色が変わるまでいためる。最後に、ひき肉と混ぜて形を整える。」', a: '時間の順(作業の手順の順)', exp: '「まず」「次に」「最後に」という言葉が、時間の流れにそって手順を説明していることを示しています。料理の作り方や、実験の手順、物ができるまでの過程などを説明するときに、よく使われる順序です。\n時間の順で書かれた文章では、順番を入れかえると、内容そのものが成り立たなくなります(いためる前に形を整えることはできない)。そのため、並べかえ問題では、手順として自然な順になっているかを確かめることが大切です。\n時間の順を示す言葉には、ほかに「はじめに」「それから」「その後」「やがて」「ついに」などがあります。' },
      { lv: 3, q: '説明文の筆者が、むずかしい内容を説明する前に、読者のよく知っている身近な例を先に挙げることが多いのはなぜか。説明しよう。', a: '読者は、すでに知っていることを手がかりにして新しいことを理解するので、身近な例を先に示しておくと、その後のむずかしい内容も「あの例と同じしくみだ」と結びつけて理解しやすくなるから。また、身近な例は読者の興味を引き、文章を読み進めてもらうきっかけにもなるから。', exp: '人は、まったく知らないことを、いきなり理解することは苦手です。すでに知っている経験や知識と結びつけることで、新しいことを理解します。説明文の筆者はこのことを知っているので、まず身近な例で読者の頭の中に「土台」をつくり、そこにむずかしい内容を積み上げていきます。\nもう一つの理由は、読者の興味です。「雲はどうやってできるか」より、「冷たいコップに水滴がつくのはなぜか」のほうが、読者は自分のこととして考えやすく、続きを読みたくなります。\n入試で「この例が最初に置かれている効果」を問われたら、①理解しやすくする、②興味を引く、の二点を考えるとよいでしょう。' },
      { lv: 3, q: '次の作例の文の順序を入れかえると、何が分かりにくくなるか。説明しよう。\n元の順序「森の木が切られた。そのため、雨が降ると土が流れやすくなった。その結果、下流の川がにごるようになった。」\n入れかえた順序「下流の川がにごるようになった。雨が降ると土が流れやすくなった。森の木が切られた。」', a: '元の順序は「原因→結果→さらにその結果」と、出来事のつながりを順に追っている。入れかえると、どの出来事がどの出来事の原因なのかを示す「そのため」「その結果」が使えなくなり、三つの出来事が因果関係でつながっていることが分かりにくくなる。', exp: '元の文章は、①木が切られた(原因)→②土が流れやすくなった(①の結果であり、③の原因)→③川がにごった(結果)という、因果の連鎖を順に説明しています。「そのため」「その結果」という接続の言葉が、そのつながりをはっきり示しています。\n入れかえた文章は、出来事が並んでいるだけで、それぞれの関係が示されていません。読者は「川がにごったことと、木が切られたことは関係があるのか」と迷ってしまいます。\nなお、結果を先に示してから原因をさかのぼる書き方(「なぜ川がにごったのか。それは〜」)もありますが、その場合は、「なぜなら」「それは〜からだ」など、さかのぼることを示す言葉が必要です。' }
    ],
    faq: [
      ['説明の順序の型は、一つの文章に一つだけなの?', '一つとはかぎりません。長い文章では、全体は「身近なものから遠いものへ」の順で進みながら、一つの段落の中は「原因から結果へ」の順で書かれている、というように、いくつもの型が組み合わさっていることがよくあります。順序の問題では、「文章全体の順序」を問われているのか、「ある段落の中の順序」を問われているのかを確かめてから答えましょう。'],
      ['自分で作文や説明を書くときにも、順序の型は使えるの?', '大いに使えます。たとえば、学校の行事を紹介するなら時間の順、自分の町を紹介するなら空間の順(駅から始めて、商店街、公園へ)、自分の意見を述べるなら原因から結果への順、というように、伝えたい内容に合わせて型を選ぶと、読み手に分かりやすい文章になります。書く前に、どの順序で書くかを決めてメモを作っておくと、途中で話がばらばらになるのを防げます。']
    ]
  });

  add('j_shosetsu', {
    secs: [
      { h: 'さらに深く:対照的な人物が、主人公の心を映し出す', t: '小説には、性格や考え方が【対照的な人物】が組み合わされて登場することがよくあります。明るい人物と内気な人物、すぐに行動する人物と考えこむ人物などです。作者がこうした人物を組み合わせるのは、【一方を見ることで、もう一方の特徴や気持ちがはっきり見える】からです。\nたとえば、主人公が内気な少年で、その親友がだれとでもすぐに仲よくなれる少年だとします。親友が新しい友だちと楽しそうに話している場面が書かれると、読者は、それを見ている主人公の「うらやましい」「自分もああなりたい」「取り残されたようでさびしい」といった気持ちを、直接書かれていなくても感じとることができます。\n対照的な人物を読むときのポイントは3つです。\n①【二人のちがいを言葉にする】…性格・行動・考え方のどこがちがうかを、本文の言葉で確かめる。\n②【主人公が相手をどう見ているかを読む】…あこがれ・反発・とまどいなど、相手への見方に主人公の心情が表れる。\n③【物語の中での変化に注目する】…物語の終わりで、主人公が相手の長所を認めたり、相手から何かを学んだりして変わることが多い。\n入試の小説では、「AとBの人物像のちがい」や「Bの言葉を聞いたAの気持ち」がよく問われます。対照的な人物がいたら、二人を比べる表を頭の中に作って読みましょう。', key: '対照的な人物は、主人公の特徴や気持ちを映し出す鏡。二人のちがい・主人公の相手への見方・物語の中での変化の三点で読む。', ex: [{ q: '次の作例の文章を読んで答えよう。\n「発表会の前日、真央は何度も楽譜を見返していた。一方、隣の席の遥は『大丈夫、なんとかなるって』と笑って、早めに帰っていった。真央は遥の背中を見送りながら、楽譜を持つ手に力をこめた。」\n真央と遥の人物像のちがいを説明し、遥を見送る真央の気持ちを考えよう。', hint: '「一方」という言葉で、二人が比べられています。真央の「手に力をこめた」というしぐさにも注目しましょう。', steps: ['二人のちがいを言葉にする。真央は何度も楽譜を見返す、慎重で心配性な人物。遥は「なんとかなる」と笑って早く帰る、楽観的でのんびりした人物。', '「一方」という言葉が、二人の対比を示す合図になっている。', '真央が遥を見送る場面に注目する。遥のように気楽にはなれない真央の気持ちが表れる。', '「楽譜を持つ手に力をこめた」は、遥のように楽観的にはなれず、自分はもっと練習しなければという決意や、不安を押さえこもうとする気持ちを表すしぐさと読める。'], a: '人物像:真央は何度も楽譜を見返す慎重で心配性な人物、遥は「なんとかなる」と楽観的に考える人物。真央の気持ち:遥のように気楽に構えることができない自分を感じつつ、不安を押さえて、もっとしっかり準備しようと気持ちを引きしめている。', check: '真央の気持ちを「遥に腹を立てている」とすると、「見送りながら」という静かな様子や、自分の楽譜に意識が向いていることと合いません。しぐさが向けられている先(楽譜=自分の練習)から確かめます。' }] },
      { h: '実戦演習:対照的な人物との出来事をきっかけにした心情の変化', t: '高校入試の小説では、対照的な人物との出会いや会話をきっかけに、主人公の心情が変化する場面がよく出ます。戦略は次のとおりです。\n①場面の【はじめ】の主人公の気持ちと、相手への見方を確かめます。\n②【きっかけ】となる相手の言葉や行動を見つけます。\n③場面の【終わり】の主人公の気持ちや行動を確かめ、はじめとどう変わったかを言葉にします。\n④記述では、「はじめは〜だったが、(相手の)〜によって、〜するようになった」の型でまとめます。\n落とし穴は、きっかけを書き落とすことです。心情の変化の記述では、「何によって変わったのか」が大事な要素になります。', key: '「はじめの気持ち→相手の言葉・行動(きっかけ)→終わりの気持ち」の三点をそろえて書けるかで差がつく。', ex: [{ q: '次の作例の文章を読んで答えよう。\n「ぼくは、いつも先頭に立って話す浩介が苦手だった。学級会で、浩介はまた自分の案ばかりを主張していた。ところが、ぼくが小さな声で別の案を言うと、浩介は急に話すのをやめ、『それ、いいな。もっと聞かせてよ』と身を乗り出した。ぼくは少しとまどいながらも、自分の考えを最後まで話した。話し終えると、胸の奥が、ほんのりと温かかった。」\n「ぼく」の浩介に対する気持ちは、どのように変化したか。60字以内で説明しよう。', hint: 'はじめに「苦手」だった理由と、浩介の意外な言葉に注目します。', steps: ['はじめの気持ち:浩介はいつも先頭に立ち、自分の案ばかり主張するので、「ぼく」は苦手に思っていた。', 'きっかけ:「ぼく」が小さな声で言った案に、浩介が「それ、いいな。もっと聞かせてよ」と、身を乗り出して興味を示したこと。', '終わりの気持ち:とまどいながらも最後まで話し、「胸の奥が、ほんのりと温かかった」。自分の考えを認めてもらえたうれしさと、浩介への見方が少し変わったことが読みとれる。', '「はじめは〜だったが、〜によって、〜」の型で、60字以内にまとめる。'], a: '(例)自分の案ばかり主張する浩介を苦手に思っていたが、自分の案を認めて聞いてくれたことで、浩介に親しみを感じ始めている。(57字)', check: '「ほんのりと温かかった」は、大きな変化ではなく、少しずつ気持ちが近づき始めたことを表しています。「浩介と親友になった」のように、変化を大きく書きすぎていないかを確かめましょう。' }] }
    ],
    drill: [
      { lv: 2, q: '小説で、性格が対照的な二人の人物を組み合わせて登場させると、どのような効果があるか。説明しよう。', a: '二人を比べることで、それぞれの人物の性格や考え方の特徴がはっきりと読者に伝わる。また、相手を見たときの主人公の気持ち(あこがれ・反発・さびしさなど)を、直接書かなくても読者に感じとらせることができる。', exp: '人物の特徴は、一人だけを見ていると気づきにくいものです。たとえば「慎重な人物」も、もう一人の楽観的な人物と並べることで、その慎重さが際立ちます。これは、評論文で二つの考えを比べる「対比」と同じしくみです。\nまた、主人公が対照的な相手をどう見ているかには、主人公自身の悩みや願いが表れます。内気な主人公が明るい友人を見るとき、その視線には「自分もああなりたい」という気持ちがこめられていることが多いのです。\n物語の終わりでは、二人がお互いの良さに気づいたり、主人公が相手から学んで成長したりすることが多いので、変化にも注目しましょう。' },
      { lv: 3, q: '次の作例の文章で、姉の言葉を聞いた「わたし」の気持ちを説明しよう。\n「何でも器用にこなす姉は、わたしの書道の作品を見て、『字がまっすぐで、あんたらしいね』と言った。上手だとは言わなかった。それでも、わたしはその作品を、いちばん目立つ壁にはった。」', a: '何でも器用にこなす姉に、上手だとはほめられなかったが、「あんたらしい」と自分のよさを認めてもらえたことがうれしく、自分の作品に自信と誇りを感じている。', exp: '姉は「何でも器用にこなす」人物で、「わたし」とは対照的に書かれています。そんな姉に作品を見せる「わたし」には、上手だと言ってほしいという期待や、姉と比べられることへの不安があったと考えられます。\n姉は「上手だ」とは言いませんでしたが、「まっすぐで、あんたらしい」と、技術ではなく「わたし」らしさをほめました。「それでも」という逆接の言葉の後に、作品を「いちばん目立つ壁にはった」という行動が続いていることから、「わたし」がその言葉をうれしく受けとめたことが分かります。\n「上手と言われなかったからくやしい」と読むと、壁にはるという誇らしげな行動と合いません。' },
      { lv: 3, q: '次の作例の文章について、最後の一文が表している「ぼく」の気持ちの変化を、はじめの気持ちと比べて60字以内で説明しよう。\n「転校生の大地は、休み時間になると一人で本を読んでいた。ぼくは、変わったやつだと思って近づかなかった。ある日、大地が読んでいたのは、ぼくが大好きな昆虫の図鑑だった。気がつくと、ぼくは大地の隣に座って、同じページをのぞきこんでいた。」', a: '(例)一人で本を読む大地を変わったやつだと思って避けていたが、同じ昆虫好きだと知って親しみを感じ、自分から近づこうとしている。(60字)', exp: 'はじめの「ぼく」は、大地を「変わったやつ」と思い、近づかないようにしていました。二人は対照的(一人でいる大地/近づかないぼく)に見えますが、実は共通点(昆虫が好き)があったことが、変化のきっかけになっています。\n最後の一文「気がつくと、ぼくは大地の隣に座って、同じページをのぞきこんでいた」の「気がつくと」は、「ぼく」が意識しないうちに、自然と体が動いていたことを表しています。これは、大地への親しみや興味が、考えるより先に行動に表れたことを示しています。\n記述では、はじめの気持ち(避けていた)、きっかけ(同じ昆虫好きと知った)、変化後の気持ち(親しみ・近づく)の三つを入れるようにしましょう。' }
    ],
    faq: [
      ['対照的な人物のどちらが「よい人」なのかを考えるべき?', 'どちらがよいかを決める必要はありません。多くの小説では、対照的な二人のどちらにも長所と短所があり、どちらかが正しいとはえがかれていません。大切なのは、二人のちがいが物語の中でどんな役割を果たしているか、主人公が相手をどう見て、どう変わっていくかを読むことです。入試の選択肢で、一方の人物を一方的に悪く言うものは、本文の読みとして適切でないことが多いので注意しましょう。'],
      ['心情の変化の記述で、「きっかけ」はどこまでくわしく書けばいいの?', '字数に合わせて、きっかけとなった出来事の「中心」を書けば十分です。たとえば「浩介が『それ、いいな。もっと聞かせてよ』と身を乗り出した」を全部写すのではなく、「浩介が自分の案を認めて聞いてくれたこと」のように、その出来事が主人公にとってどんな意味をもったかをまとめて書きます。本文の会話をそのまま長く引用すると字数が足りなくなるので、自分の言葉で短く言いかえる練習をしておきましょう。']
    ]
  });

  add('j_classic', {
    secs: [
      { h: 'さらに深く:三大随筆を比べると、「ものの見方」が見えてくる', t: '日本の古典には、【三大随筆】と呼ばれる作品があります。平安時代の『枕草子』(清少納言)、鎌倉時代初めの『方丈記』(鴨長明)、鎌倉時代の終わりごろの『徒然草』(兼好法師)です。どれも、作者が見たこと・感じたこと・考えたことを、自由な形で書きつづった作品ですが、【ものの見方】には大きなちがいがあります。\n①【枕草子】…宮廷に仕えた清少納言が、季節や宮廷の暮らしの中で見つけた「をかし」(趣がある・おもしろい)ものを、明るく鋭い感覚で書いています。「春はあけぼの」のように、美しいものを一瞬でとらえる見方が特徴です。\n②【方丈記】…鴨長明は、大火事・つむじ風・飢饉・地震など、都をおそった災害を目にし、この世のはかなさ(【無常】)を見つめました。冒頭の「ゆく河の流れは絶えずして、しかももとの水にあらず。」は、川の水がたえず入れかわるように、人も住まいも移り変わっていくことを表しています。\n③【徒然草】…兼好法師は、人の生き方、ものの考え方、日常の失敗談など、さまざまな話題を取り上げ、無常を受け入れたうえで、どう生きるのがよいかを考えています。\nこのように比べると、『枕草子』は「美しいものを見つける目」、『方丈記』は「移り変わるものを見つめる目」、『徒然草』は「人の生き方を考える目」というちがいがあると言えます。作品名と作者を覚えるときも、このちがいとセットにすると、内容の問題にも答えやすくなります。', key: '三大随筆は、枕草子=「をかし」を見つける目、方丈記=無常を見つめる目、徒然草=生き方を考える目。作者・時代とあわせて、ものの見方のちがいで覚える。', ex: [{ q: '『方丈記』の冒頭「ゆく河の流れは絶えずして、しかももとの水にあらず。よどみに浮かぶうたかたは、かつ消えかつ結びて、久しくとどまりたるためしなし。世の中にある人とすみかと、またかくのごとし。」について答えよう。(うたかた=水のあわ。かつ〜かつ…=一方では〜し、一方では…する。ためし=例)\n(1)「ゆく河の流れ」と「うたかた」は、何をたとえているか。(2)作者が言いたいことを説明しよう。', hint: '最後の文「世の中にある人とすみかと、またかくのごとし」が、たとえの答えです。', steps: ['(1)最後の文で「世の中にある人とすみか(住まい)も、またこのようである」と述べているので、「ゆく河の流れ」と「うたかた」は、世の中の人と住まいのたとえ。', '「ゆく河の流れ」:流れはたえないが、水はいつも新しく入れかわっている。人の世も、全体は続いていくが、そこに生きる人は入れかわっていく。', '「うたかた」:水のあわは、消えたりできたりして、長くとどまることがない。人や住まいも、生まれては消え、長く同じままではいられない。', '(2)作者は、川の流れや水のあわのように、人も住まいもたえず移り変わり、いつまでも同じままではいられない、というこの世のはかなさ(無常)を言いたいのである。'], a: '(1)世の中の人と、その住まい(すみか)。(2)川の水がたえず入れかわり、水のあわが消えたりできたりして長くとどまらないように、世の中の人や住まいも、たえず移り変わっていつまでも同じままではいられない、というこの世のはかなさ(無常)。', check: '答えが、最後の文「人とすみかと、またかくのごとし」と対応しているかを確かめます。たとえの話(川・あわ)だけで終わらず、人の世の話に置きかえて説明できていれば、作者の言いたいことをとらえられています。' }] },
      { h: '実戦演習:随筆風の古文を読み、作者の考えをつかむ', t: '高校入試の古文では、随筆の一節や、それに似た短い文章が出され、作者の考えを問う問題が出ます。戦略は次のとおりです。\n①注と現代語訳(ついていれば)を先に読み、話題をつかみます。\n②本文の中で、作者の【感想や考え】を表す部分を探します。「〜こそ〜けれ」(係り結び)、「〜べし」「〜にや」などの形や、「あはれなり」「をかし」などの評価の言葉が目印です。\n③随筆では、【具体的な出来事 → 作者の考え】の順に書かれることが多いので、出来事の部分と考えの部分を分けて読みます。\n落とし穴は、出来事の内容を答えてしまい、作者の考えを答えないことです。設問が「作者の考え」を聞いているときは、出来事から作者が何を感じたかを答えましょう。', key: '随筆は「出来事→作者の考え」の順。係り結びや評価の言葉を目印に、考えの部分を見つけられるかで差がつく。', ex: [{ q: '次の作例の古文を読んで答えよう。\n「ある人、庭の木を、形よしとて、みな切りそろへけり。されど、そののちは鳥も来ず、風の音もせずなりにけり。木はおのがままにのびたるこそ、をかしけれ。人の手を加へすぎたるは、かへりてそのよさを失ふなり。」\n(おのがまま=自分の思うまま。をかし=趣がある。かへりて=かえって)\n(1)「切りそろへけり」を現代仮名遣いに直そう。(2)係りの助詞と、その結びの語を答えよう。(3)作者の考えを、出来事と結びつけて説明しよう。', hint: '(3)本文の前半(出来事)と後半(考え)を分けて読みましょう。', steps: ['(1)「へ」は語の頭以外なので「え」に直す。「切りそろえけり」。', '(2)「のびたるこそ、をかしけれ」の「こそ」が係りの助詞で、結びは「をかしけれ」(形容詞「をかし」の已然形)。', '(3)出来事の部分:ある人が、見た目をよくしようと庭の木をみな切りそろえたが、その後は鳥も来ず、風の音もしなくなった。', '考えの部分:「木はおのがままにのびたるこそ、をかしけれ」(木は自然にのびているのが趣がある)、「人の手を加へすぎたるは、かへりてそのよさを失ふなり」(人の手を加えすぎると、かえってよさを失う)。', '出来事と考えを結びつけて、「〜という出来事から、〜と考えている」の形でまとめる。'], a: '(1)切りそろえけり (2)係りの助詞=こそ、結びの語=をかしけれ (3)庭の木をみな切りそろえたら鳥も来なくなり、風の音もしなくなったという出来事から、木は自然のままにのびているのが趣深いのであり、人が手を加えすぎると、かえってそのもののよさを失ってしまうと考えている。', check: '(3)の答えに、出来事(切りそろえた→鳥も風の音もなくなった)と、作者の考え(自然のままがよい・手を加えすぎるとよさを失う)の両方が入っているかを確かめます。考えの部分だけでも正解になることがありますが、出来事と結びつけると説得力が増します。' }] }
    ],
    drill: [
      { lv: 2, q: '三大随筆の作品名・作者・成立した時代を、それぞれ答えよう。', a: '『枕草子』=清少納言、平安時代(中ごろ)。『方丈記』=鴨長明、鎌倉時代(初め)。『徒然草』=兼好法師(吉田兼好)、鎌倉時代(終わりごろ)。', exp: '三つの作品は、成立した順に、枕草子(平安時代)→方丈記(鎌倉時代の初め)→徒然草(鎌倉時代の終わりごろ)となります。\n作者の立場もそれぞれちがいます。清少納言は、一条天皇の中宮定子に仕えた女房です。鴨長明は、京都の下鴨神社の神官の家に生まれましたが、のちに出家して、都の外の小さな庵(方丈=約三メートル四方の部屋)で暮らしました。作品名の「方丈」はここから来ています。兼好法師も出家した人です。\n作品名と作者を覚えるときは、作品名の由来(方丈=小さな庵、徒然=することがなく退屈なこと)とあわせて覚えると、忘れにくくなります。' },
      { lv: 3, q: '『方丈記』と『徒然草』は、どちらも「無常」(この世のすべては移り変わるということ)を大切なテーマとしているが、その受けとめ方にはちがいがあると言われる。どのようなちがいか、説明しよう。', a: '『方丈記』は、災害などで人や住まいが失われていく様子を見つめ、この世のはかなさを深く感じとることに重点がある。一方、『徒然草』は、無常であることを受け入れたうえで、だからこそ限られた時間をどう生きるか、人としてどうふるまうのがよいかを考えることに重点がある。', exp: '鴨長明は、大火事や地震、飢饉などを実際に体験し、人の命や住まいのはかなさを強く感じました。『方丈記』の冒頭の川やあわのたとえは、そのはかなさを印象深く表しています。\n兼好法師も、人の命がはかないことをよく知っていましたが、『徒然草』では、そのことをなげくだけでなく、「だからこそ、今をどう生きるか」という方向に考えを進めています。また、失敗談や、ものの考え方についての短い話も多く、人間への幅広い関心が見られます。\nこのように、同じテーマでも作品によって受けとめ方がちがうことを知っていると、初めて読む古文でも、作者の考えをつかみやすくなります。' },
      { lv: 3, q: '作例「月の夜、ひとり舟に乗りて、川をくだりけり。水の上に月の影うつりて、ゆらゆらとゆれたるさま、いとをかし。」について、(1)「うつりて」「ゆれたる」の主語を答えよう。(2)作者が「をかし」と感じたものは何か、説明しよう。', a: '(1)どちらも「月の影」(月の光・月の姿)。(2)川の水面に月の姿が映って、ゆらゆらとゆれている様子。', exp: '(1)「水の上に月の影うつりて」は、「月の影が水の上に映って」という意味で、「うつりて」の主語は「月の影」です。続く「ゆらゆらとゆれたるさま」も、水面に映った月の影がゆれている様子なので、主語は同じ「月の影」です。古文の「影」は、現代語の「かげ(暗い部分)」ではなく、「光」や「姿」を表すことが多いので注意しましょう。\n(2)「いとをかし」(とても趣がある)と感じた対象は、その直前の「水の上に月の影うつりて、ゆらゆらとゆれたるさま」です。「をかし」は、『枕草子』でよく使われる、明るく知的な感動を表す言葉です。何を「をかし」と感じたのかを、直前の部分から正確に読みとることが大切です。' }
    ],
    faq: [
      ['随筆と日記は、どうちがうの?', '日記は、日付にそって、その日にあった出来事や気持ちを書いていくものです。古典では『土佐日記』(紀貫之)や『更級日記』などがあります。随筆は、日付にとらわれず、作者が思いついたこと、見聞きしたこと、考えたことを自由に書くものです。ただし、古典の日記には、旅の記録や回想など、随筆に近い性格をもつものもあります。作品の種類を答える問題では、作品名と種類をセットで覚えておくことが大切です。'],
      ['「無常」は、悲しい考え方なの?', '「無常」とは、この世のすべてのものは移り変わり、同じままでとどまることはない、という仏教の考え方です。そのため、人の死や別れを思い、悲しさやはかなさを感じさせることが多いのは確かです。しかし、移り変わるからこそ、今この瞬間が大切である、と考えることもできます。『徒然草』には、そうした前向きな受けとめ方も見られます。無常は、悲しみだけでなく、生き方を見つめ直すきっかけにもなる考え方なのです。']
    ]
  });

  add('j_sakubun', {
    secs: [
      { h: 'さらに深く:読み手が迷わない文 ― 修飾語の位置と一文の長さ', t: '作文で、内容はよいのに伝わりにくい文があります。その原因の多くは、【修飾語の位置】と【一文の長さ】です。\n①【修飾語の位置】…修飾語は、くわしくする言葉の【すぐ前】に置くのが基本です。位置がはなれると、どの言葉をくわしくしているのか分からなくなります。\n例:「白い犬の小屋」は、「白い」が「犬」をくわしくするのか、「小屋」をくわしくするのか、二通りに読めます。白いのが犬なら「白い犬の、小屋」より「白い犬がすむ小屋」、白いのが小屋なら「犬の白い小屋」と書けば、迷いません。\n例:「ぼくは急いで出かける弟を呼び止めた。」は、急いだのが「ぼく」か「弟」か分かりません。弟が急いでいたなら「ぼくは、急いで出かける弟を呼び止めた。」と読点を打つか、「急いで出かける弟を、ぼくは呼び止めた。」と語順を変えます。\n②【一文の長さ】…一文が長くなると、主語と述語がはなれて、ねじれが起きやすくなります。目安として、一文は四十〜六十字程度におさえ、「〜が、〜て、〜ので」と続く文は、途中で区切ります。\n③【読点の打ち方】…読点は、意味の切れ目や、誤解を防ぎたいところに打ちます。打ちすぎると読みにくく、少なすぎると意味がまぎれます。\n入試の作文は、採点者が一度読んで分かることが大切です。書き終えたら、【二通りに読める文はないか】【主語と述語がはなれすぎていないか】の二点を確かめましょう。', key: '修飾語は、くわしくする言葉のすぐ前に置く。二通りに読める文は、語順を変えるか読点を打って直す。一文は四十〜六十字を目安に区切る。', ex: [{ q: '次の文は、二通りの意味に読める。それぞれの意味を説明し、意味が一つに決まるように書き直そう。\n「私は笑いながら手をふる友だちを見ていた。」', hint: '「笑いながら」は、「私」と「友だち」のどちらの様子でしょう。', steps: ['二通りの読みを確かめる。①笑っているのは「私」:私が笑いながら、手をふる友だちを見ていた。②笑っているのは「友だち」:私は、笑いながら手をふる友だちを見ていた。', '①の意味にしたいときは、「笑いながら」を「私」の動作「見ていた」に近づけるか、読点で区切る。「私は笑いながら、手をふる友だちを見ていた。」', 'さらに確実にするには、語順を変える。「手をふる友だちを、私は笑いながら見ていた。」', '②の意味にしたいときは、「私は、笑いながら手をふる友だちを見ていた。」と、「私は」の後に読点を打ち、「笑いながら手をふる」をひとまとまりにする。'], a: '意味①:笑っているのは「私」。直し方の例「手をふる友だちを、私は笑いながら見ていた。」 意味②:笑っているのは「友だち」。直し方の例「私は、笑いながら手をふる友だちを見ていた。」', check: '直した文を声に出して読み、もう一方の意味に取られる可能性がないかを確かめます。語順を変える方法は、読点だけに頼るより、誤解をより確実に防げます。' }] },
      { h: '実戦演習:下書きの作文を推敲する', t: '高校入試では、生徒が書いた作文の下書きを示して、直すべきところを答えさせる【推敲の問題】が出ることがあります。自分の作文の見直しにも使える力です。戦略は次のとおりです。\n①【文体】…常体(だ・である)と敬体(です・ます)がまざっていないか。\n②【主語と述語】…ねじれていないか。とくに「〜は、〜ことだ」の形になっているか。\n③【呼応】…「決して〜ない」「なぜなら〜からだ」などの呼応がくずれていないか。\n④【修飾語・読点】…二通りに読める文はないか。\n⑤【段落と内容】…条件に合った段落構成か、意見と理由が対応しているか。\n落とし穴は、一つの誤りを見つけて満足し、同じ文の中のほかの誤りを見落とすことです。一文ずつ、①〜④の観点で順番に確かめましょう。', key: '文体・ねじれ・呼応・修飾語の四つの観点で、一文ずつ順番に確かめる。一文に誤りが二つあることに気づけるかで差がつく。', ex: [{ q: '次の作文の下書き(作例)には、直すべきところが三つある。それぞれ指摘して、正しく直そう。\n「私が中学校生活で大切にしたいことは、あいさつです。なぜなら、あいさつをすると、相手との距離が近くなる。去年、私は毎朝、通学路で会うおばあさんにあいさつをしていた。最初は返事がなかったが、決して私はあきらめた。今では、おばあさんのほうから声をかけてくれる。」', hint: '文体・呼応・ねじれの観点で、一文ずつ確かめましょう。', steps: ['一文目「〜ことは、あいさつです。」は敬体。二文目以降は「近くなる」「していた」などの常体。文体がまざっているので、常体にそろえるなら「あいさつだ。」に直す。', '二文目「なぜなら、〜近くなる。」は、「なぜなら」と「〜からだ」の呼応がくずれている。「なぜなら、あいさつをすると、相手との距離が近くなるからだ。」に直す。', '四文目「決して私はあきらめた。」は、「決して」と「〜ない」の呼応がくずれていて、意味も逆になっている。「私は決してあきらめなかった。」に直す。', '三文目・五文目には誤りがないことを確かめる。'], a: '①一文目の文体(敬体)を常体にそろえる:「私が中学校生活で大切にしたいことは、あいさつだ。」 ②「なぜなら」との呼応:「なぜなら、あいさつをすると、相手との距離が近くなるからだ。」 ③「決して」との呼応:「最初は返事がなかったが、私は決してあきらめなかった。」', check: '直した作文を通して読み、文体が常体にそろっているか、理由の文が「からだ」で終わっているか、意味が通るかを確かめます。敬体にそろえる直し方も正解ですが、その場合は二文目以降をすべて敬体に直す必要があります。' }] }
    ],
    drill: [
      { lv: 2, q: '次の文を、意味が一つに決まるように書き直そう。ただし、「大きい」のは「かばん」であるとする。\n「大きい姉のかばんを借りた。」', a: '(例)姉の大きいかばんを借りた。', exp: '元の文では、「大きい」が「姉」をくわしくしているのか(大きい姉=背の高い姉、または年上の姉)、「かばん」をくわしくしているのか、はっきりしません。\n修飾語は、くわしくする言葉のすぐ前に置くのが基本です。「かばん」が大きいのなら、「大きい」を「かばん」の直前に移して、「姉の大きいかばん」とすれば、意味が一つに決まります。\nこのように、「AのB」の前に修飾語があると、AとBのどちらをくわしくしているのか、あいまいになりやすいです。作文を見直すときは、「〜の〜」の前の修飾語に注意しましょう。' },
      { lv: 3, q: '次の文は長すぎて分かりにくい。意味を変えずに、二つか三つの文に区切って書き直そう。\n「私は、夏休みに祖父の家に行ったときに、祖父が畑で育てていたトマトをいっしょに収穫して、その場で食べたトマトがとてもおいしかったので、野菜を育てることに興味をもち、今は家のベランダでミニトマトを育てている。」', a: '(例)夏休みに祖父の家に行ったとき、祖父が畑で育てていたトマトをいっしょに収穫した。その場で食べたトマトはとてもおいしく、私は野菜を育てることに興味をもった。今は、家のベランダでミニトマトを育てている。', exp: '元の文は、「〜とき、〜して、〜ので、〜もち、〜いる」と、一つの文の中に出来事がいくつもつながっていて、百字近くもあります。また、主語の「私は」と、最後の述語「育てている」が大きくはなれています。\n書き直すときは、出来事の切れ目(「〜て」「〜ので」のところ)で文を区切り、それぞれの文に主語と述語がそろうようにします。例では、①収穫した出来事、②おいしくて興味をもったこと、③今していること、の三つに分けました。\nなお、二文目に「私は」を入れて主語をはっきりさせるなど、区切ったあとの文がそれぞれ自然に読めるかも確かめましょう。' },
      { lv: 3, q: '作文で、読点を打つ位置によって意味が変わる例を一つ作り、それぞれの意味を説明しよう。', a: '(例)「母は、笑いながら話す妹を見ていた。」=笑っているのは妹。「母は笑いながら、話す妹を見ていた。」=笑っているのは母。', exp: '読点は、言葉のまとまりを示す働きをもっています。「母は、笑いながら話す妹を見ていた。」では、「笑いながら話す」がひとまとまりになって「妹」をくわしくしているので、笑っているのは妹です。\n一方、「母は笑いながら、話す妹を見ていた。」では、「笑いながら」の後で区切れるので、「笑いながら」は「見ていた」をくわしくし、笑っているのは母になります。\nこのように、読点一つで意味が変わることがあります。作文では、自分の伝えたい意味に合った位置に読点を打つことが大切です。ただし、読点だけに頼ると誤解が残ることもあるので、語順を変える方法(「話す妹を、母は笑いながら見ていた」)もあわせて考えるとよいでしょう。' }
    ],
    faq: [
      ['一文は短いほうがいいの?', '短すぎる文が続くと、文章がぶつぶつと切れて、子どもっぽい印象になることがあります。大切なのは、一文に入れる内容を一つか二つにしぼり、主語と述語がはっきり対応するようにすることです。目安として、一文を四十〜六十字程度にすると読みやすくなります。理由や具体例を説明する文では、少し長くなってもかまいませんが、六十字をこえるときは、途中で区切れないかを考えてみましょう。'],
      ['推敲は、どのタイミングでするのがいいの?', '入試では、書き終えたあとに必ず時間を残して見直すことが大切です。目安として、制限時間のうち最後の三〜五分を推敲にあてましょう。見直すときは、文体・ねじれ・呼応・誤字脱字の順に、観点を決めて読むと効率的です。また、書いている途中でも、一段落書き終えるごとにさっと読み返すと、大きな誤りを早めに直せます。消しゴムで直すときは、マス目からはみ出さないように、ていねいに書き直しましょう。']
    ]
  });
})(WPS.LESSONS);
